window.__D("text/ner-mitzva/c003",{"p":[[2800530190,"כלל וכלל והוא ענין אמיתת עצמותו כמו שהוא שבלתי יכול לבא גם לבחי' כלל אל הפרט דבינה שזהו אין של היש עכ\"פ אבל בחי' הכח מ\"ה דחכמ' הוא בבחינת אין בעצם שלמעלה לגמרי גם מהיות אין ליש דבינה על כן אינו בא לכלל תפיסה בהשגה כלל שאם הוא בא בגדר תפיסה במחשבת שכל העיונית הנ\"ל אין זה אמית' עצמותו כלל וכלל (דמה שנמשך מאין דחכמה ליש בהשגה נקרא בשם עומק המושג או בשם נקודה דיו\"ד<sup data-n=\"2173\">1</sup> ואמנם עצם החכמה כמו שהיא בבחי' אין ממש הוא שנק' שכל הנעלם מכל רעיון<sup data-n=\"2174\">2</sup> ומח' וזהו כמו מעיין חתום במקורו הנעלם שאינו בא לכלל גלוי והמשכה בנהר כלל כנ\"ל שזהו שנק' נקודה סתימא' כו' סתום לגמרי שלמעלה גם מראיית השכל כחכם הרואה את הנולד כו' שזה נק' עכ\"פ ראי' אור השכל שהוא מקור להשגת השכל כי מה שרואה את הנולד לא שרוא' מצד העצם במהות הדבר שיהי' רק ע\"פ ראיי' שכלו וראיי' שכל היינו נקוד' החכ' שיוכל לבא לידי טעם בדבר רק שזולתו לא יראה וישיג וכן מה שנקראי' עיני העדה וכה\"ג היינו רק עין השכל דהיינו בחי' נקודה דחכמה שבבינה כנ\"ל אבל בחי' ראי' והסתכלות שמצד עצם כח הפנימי שבמקור החכמה כמו שהיא בבחי' אין ממש הוא הראי' והסתכלו' במהו\"ע ממש כראי' העין בגשמיות וכמו וראו כל בשר<sup data-n=\"2175\">3</sup> שראיה זו לא ראיית השכל היא אלא כמו הביטו אליו<sup data-n=\"2176\">4</sup> כו' כמו בהבטת עין רואה ראיה גשמיות שהרי יאמרו הנה אלקינו זה לנוכח וכן מ\"ש כולם ידעו אותי שזהו ע\"י ראיה והכרה בעין גשמי כמו שאדם מכיר לחבירו ע\"י ראי' גשמי' כו' וע\"ז א' אינו דומה שמיעה לראי' היינו לראיה בגשמיות ולא לראי' השכל לבד וד\"ל ובבחי' ראיה והסתכלות בעצם כח מה שרש הנקודה דחכמ' הוא שיכול להיות שלא לפי ערך כלל אל הפרט כמו שהיה האריז\"ל רואה בסודות התורה ברגע א' מה שצריך לבא באין ויש דחו\"ב עד הדבור במשך זמן ס'<sup data-n=\"2177\">5</sup> שנה ויותר כמו ההכרה בראי' העין ממש במהות ועצם הדבר כמו שהוא ממש שא\"א שיגבילנו בשום רעיון ועיון כל עומק ועין השכל והשגה גם שירבה להעמיק בו זמן רב מאד וד\"ל:\n(ס) <b>והנה</b> להבין זה עוד בתוס' ביאור הנה אנו מוצאים כדוגמא זו בבחי' ראיה והסתכלות דחכמה שלמעל' מן ההשגה שנמשך מאין ליש הנ\"ל כמו שמצינו באד\"ר בר' חזקי'<sup data-n=\"2178\">6</sup> שפתח ואמר מסתכל הוינא כו' וא\"ל רשב\"י נושא עון חמית<sup data-n=\"2179\">7</sup> כו' שזהו כמו ראיה במהות התיקון הזה דנושא עון שהוא מי\"ג ת\"ד דא\"א כו' ובודאי שלא ראה ר' חזקי' כמו בבחי' ראי' דנבואה שהרי שרש הנבואה אינו רק בבחי' נו\"ה דז\"א<sup data-n=\"2180\">8</sup> דאצי' ולמטה בהתלבשות בנו\"ה דבי\"ע וגם משה לא ראה רק בבחי' אור אבא שבנצח דז\"א<sup data-n=\"2181\">9</sup> כו' ואיך ראה ר\"ח בת\"ד דא\"א דאצי' כו' אלא צריך לומר דראי' והסתכלות זאת היה בבחי' ראיית אור החכמה אך בבחי' פנימית ועצמות שבחכ' שלמעלה מבחי' השגת שכל שא\"א להביאו בדבור ומחשבה עיונית ג\"כ גם לא בראי' עין השכל הנ\"ל אלא בסקירה והבטה דעצמות החכמ' הנ\"ל שלא נק' כלל לפרט כו' ע\"כ א\"ל נושא עון חמית שא\"א לדבר בו כלל ואם יצטרך לדבר בו גם עפ\"י עומק ההשגה",[["2173","1","<b>דיו\"ד</b>: אוצ\"ל: דיו\"ד)."],["2174","2","<b>שכל הנעלם מכל רעיון</b>: נסמן לקמן קכז, ב."],["2175","3","<b>וראו כל בשר</b>: ישעי' מ, ה."],["2176","4","<b>הביטו אליו</b>: תהלים לד, ו."],["2177","5","<b>ס'</b>: תוקן ע\"פ דפו\"ר. ובמהדורת לעמבערג פ'. וראה לעיל צג, ב הערה פ' שנה."],["2178","6","<b>באד\"ר בר' חזקי'</b>: ראה (זהר) נשא קלב, ב."],["2179","7","<b>וא\"ל רשב\"י נושא עון חמית</b>: באד\"ר שם פתחו ואמרו. אבל כ\"ה גם במאמרי אדה\"ז על פרשיות התורה כאן. אמ\"ב שער הק\"ש סד, ב. מאמרי אדה\"א דברים ח\"א ע' קמח: דר\"ח [דר' חזקי'] א'."],["2180","8","<b>הנבואה. . נו\"ה דז\"א</b>: ראה שער היחודים פ\"א. שער רוה\"ק דרוש א. סידור שער הק\"ש עט, א. אמ\"ב שם עא, ב."],["2181","9","<b>משה. . אור אבא שבנצח דז\"א</b>: ראה לעיל לד, א ובהנסמן לשם. מאמרי אדה\"א נ\"ך ע' קמא."]]],[2800530191,"יצטרך להאריך בדברים כמה ימים כו' עד שיהיה נתפס בהשגת שכל לפי שאינו דומה שמיעה מרחוק לראי' דחכמה מקרוב כמו שהוא באמיתת עצמותו כנ\"ל וזהו מעין בחי' ראייה חושיות ממש שלע\"ל (ולא כדוגמ' בראי' מציא' דבר מה שיאריך בסיפורו שעכ\"פ יגביל מהות הדבר לפי שראייתו במהות מוגבלת כמו הרוא' כרך גדול בכל חלקיו הפרטיים שיש גבול לסיפורו עד שיציירנו בכל פרטיו לפי שראי' זו גם בכרך הגדול מוגבל מהותו אבל בראי' הרוחניות שבעצמות החכמה היא בראי' בלתי מוגבלת ע\"כ לא יוכל להביאו גם בעיון השכל כלל וכמו דוגמא הנ\"ל בר\"י לוריא שראה והשיג ברגע א' מה שהי' צריך לדבר בו פ'<sup data-n=\"2182\">10</sup> שנה שאין זה לפ\"ע כלל ופרט כנ\"ל וד\"ל) (וכמו במ\"ת שראו פב\"פ<sup data-n=\"2183\">11</sup> ראי' חושיות וכן יראה כל זכורך<sup data-n=\"2184\">12</sup> בראי' בבהמ\"ק ראי' רוחניות ועצמיות בנשמות וכן מה שיקביל פני רבו ברגל<sup data-n=\"2185\">13</sup> וכה\"ג שכל זה ראי' עצמית בעצם הדב' שבלתי יוגבל בכל עומק השגת שכל לכוין לאמיתתו כמו שהוא ממש רק בראי' עצמית והוא כמו הביטו אליו כו' וכמו לע\"ל שכולם ידעו אותי כו' וע\"ז א' דוד אמתך אלקי כו' שהוא ע\"י השיר פשוט שבפה שמכוין לאמיתת עצמותו מצד בחי' ראי' רוחניות ועצמיות כו') (ולא כמו שהנשמות נהנין מזיו<sup data-n=\"2186\">14</sup> כו' שאין זה רק על פי השגת שכל משא\"כ ראי' הנשמה בבהמ\"ק או הקבל' אדם פני רבו אע\"פ שהנשמו' מלובשים בגופים הרי כל עצמותו דמקבל רואה בעצם ומהו' המשפיע שא\"א להתקבל בהשג' כלל) ובכל זה יובן בדוגמא עכ\"פ בענין הנ\"ל בקבלת פנימית התורה ע\"י משיח דכתיב בי' ישכיל עבדי ירום ונשא כו' כנ\"ל דהנה כל עיקר ענין פנימית התורה היינו בחי' פנימית ועצמות דח\"ע דתורה כמו שהיא באמיתת עצמותה ממש בלי אמצעות לבוש וכסוי דאור ההשגה דבינה גם בהיותה מקבל' מאין דחכמה כנ\"ל והוא הנק' בחי' ראי' והסתכלות דעצמות החכמה ממש כנ\"ל שא\"א שיבוא לכלל עיון ההשגת שכל וחכמה כו' והוא ענין הסקירה וההבטה במהות ועצמיות הדבר ממש כמו שהוא ע\"ד הנ\"ל בהסתכלות חכמה דר\"ח בתיקון דנושא עון או כהאריז\"ל שראה ברגע א' כו' כנ\"ל ואין זה דומה לבחי' חכמה שהיא נקודה ותמצית המושג עכ\"פ שזה יוכל לבא בהשגה במשך זמן רב עכ\"פ אבל גלוי טעמי התו\"מ ע\"י משיח יהי' בבחי' ראי' דפנימית ועצמות החכמה שלא יתפס ע\"י כלי ולבוש ההשגה דבינה כלל כי המח' ועומק העיון מסתיר ומעלים על אמיתת מהות ועצמות כנ\"ל (וכמו שאמר בעצמות אא\"ס ממש דלית מח' תפיסא בי'<sup data-n=\"2187\">15</sup> ומה שנתפס במחשבה אין זה אמיתת עצמותו) עד אשר גם מה שהנשמות נהנין בג\"ע כו' היינו רק ע\"י אמצעות השגות עמוקות בבחי' בינה שבמל' דאצילות דאור אימא מקננא בכורסייא<sup data-n=\"2188\">16</sup> כו' כידוע אבל לע\"ל והיו עיניך רואות<sup data-n=\"2189\">17</sup> כו' שלא יכנף עוד בלבוש מעלים דהשגת שכל כו' אלא בבחי' ראי' והסתכלות במהו\"ע דאא\"ס ממש כמ\"ש הנה אלקינו זה לנוכח כו' (ומ\"ש בקי\"ס זה אלי<sup data-n=\"2190\">18</sup> כו' היינו רק גלוי ההעל' שבדיבו' העליון שלמט' הרב' מן המח' דבינ' כו' וד\"ל) וזהו כל עיקר ענין קיבול שכר של הנשמות לע\"ל בגלוי טעמי וסודות המצות שיגלה להם משיח וילמדם כולם מגדולם עד קטנם כמ\"ש בו ישכיל עבדי כו' דודאי א\"א לומר שלימוד זה שילמד משיח לישראל יהי' כפי ערך הלימוד",[["2182","10","<b>פ'</b>: תוקן ע\"פ דפו\"ר. ובמהדורת לעמבערג: ס'. וראה לעיל צג, ב הערה פ' שנה."],["2183","11","<b>במ\"ת שראו פב\"פ</b>: ואתחנן ה, ד."],["2184","12","<b>יראה כל זכורך</b>: משפטים כג, יז. תשא לד, כג. ראה טז, טז. וראה גם לעיל מה, ב."],["2185","13","<b>שיקביל פני רבו ברגל</b>: ר\"ה טז, ב. ראה גם מאמרי אדה\"א נ\"ך ע' שפג. וש\"נ. שע\"ת קג, ג ובהנסמן לשם."],["2186","14","<b>שהנשמות נהנין מזיו</b>: ראה ברכות יז, א."],["2187","15","<b>דלית מח' תפיסא בי'</b>: ת\"ז בהקדמה (יז, א)."],["2188","16","<b>אימא מקננא בכורסייא</b>: נסמן לקמן קיב, ב."],["2189","17","<b>והיו עיניך. . שלא יכנף</b>: ישעי' ל, כ."],["2190","18","<b>זה אלי</b>: בשלח טו, ב."]]],[2800530192,"דעכשיו כמו שמלמדים הדבר חכמה שיושג בכי טוב העיון עד שנתפס ומושג ממש במחשבה העיונית וכנשמות בג\"ע כו' שהרי לעתיד נאמ' ולא ילמדו עוד איש את רעהו כי כולם ידעו אותי<sup data-n=\"2191\">1</sup> כו' לפי שתמלא הארץ דעה כמים לים<sup data-n=\"2192\">2</sup> כו' לפי שהלימוד דחכמ' היינו כאשר יבא בהשגה דבינה דוקא וכמו למודי הוי\"ה כו' ונק' אולפנא אאלפך<sup data-n=\"2193\">3</sup> כו' אבל למעלה מבחי' ההשגה דבינה לא שייך לימוד ע\"כ לא ילמדו עוד איש את רעהו כו' מפני שכולם ידעו אותי בבחי' ראי' והכרה ממש שזהו בחי' ראי' והסתכלו' דפנימית ועצמות הדבר אשר לא יכילנו כל רעיון והשגה כלל כנ\"ל וזהו עיקר פנימית וסודות התו' דלעתיד שילמד משיח לישראל שע\"ז אמר ישכיל עבדי כו' פי' ישכיל אינו כמו מקור להשגות שכליים שהרי השגות שכליים המה המסתירים על פנימית ועצמות כו' כנ\"ל אלא פי' ישכיל זה היינו פועל יוצא שימשיך וישכיל בכנ\"י בחי' ראי' דחכמ' העצמי' הנ\"ל שהו' בבחי' ראי' והסתכלו' בטעמי התור' וסודות שלהם כמו שהן ממש מבלי לבוש דהשגו' בבינ' והיינו ישכיל להיות מקור לכל שכל נעלם וסתום מכל רעיון שעכשיו לא באו סודות ורזין דאורייתא רק ע\"י לבוש דבינה כמו בג\"ע וכן גם בצדיקים גדולי' לא נתגלו טעמי מצות כמו לע\"ל וכמ\"ש ישקני מנשיקות פיהו<sup data-n=\"2194\">4</sup> לשון עתיד דטעמי מצו' לא נתגלו עכשיו כמו שהן ממש בלי לבוש כלל רק לעתיד ע\"י משיח דוקא (שלזה נק' מלך ולא כמו רב שמלמד דעת והשגה רק כמו באור פני מלך<sup data-n=\"2195\">5</sup> כו' שישכיל באור הראיה דח\"ע עד שיראו כולם בראיה דפנימית החכמ' שבטעמים וסודות הסתומים לגמרי עד הנה כו' וז\"ש לא ילמדו איש כו' כולם ידעו אותי בראיה ע\"י משיח דוקא שהוא בבחי' פנימית אבא שהוא פנימית ע\"י<sup data-n=\"2196\">6</sup> כידוע וז\"ש והריחו ביראת ה' דמורח ודאין<sup data-n=\"2197\">7</sup> ולא למראה עיניו בראיית עין השכל ולא למשמע אזנו בשמיעה דבינה כו' רק בבחי' הראיה דחכמ' העצמית שבפנימית התענוג כו') וזהו שנאמ' בעדן עין לא ראתה<sup data-n=\"2198\">8</sup> אלקים זולתך כו' שבחי' פנימית העדן סתימאה הנ\"ל עדיין עין לא ראתה כו' משום דעכשיו אין אור החכמ' מאיר בבחי' ראיה הרוחנית דעין השכל כמו שהוא בלא לבוש דחכמ' בבינה והשגה אבל בחי' פנימית העדן הוא בחי' פנימית ועצמות דאור החכמה עילאה כמו שהוא בעצם בלי לבוש כלל והוא אשר עין לא ראת' עדיין גם בג\"ע ובגדולי הצדיקים כו' רק אלקים זולתך יעשה למחכ' לו והוא לע\"ל בימות המשיח דוקא שנא' בו ישכיל עבדי כו' שיתגלה אז על ידו בחי' פנימית העדן הסתום בעצמות ויראו בעין בלי לבוש כלל כמו בעוה\"ב וד\"ל וזהו כימי צאתך מא\"מ<sup data-n=\"2199\">9</sup> אראנו נפלאו' דהיינו מ\"ש בנהר יעברו ברגל<sup data-n=\"2200\">10</sup> בנהר פרת שהוא הנהר היוצא מעדן<sup data-n=\"2201\">11</sup> הנ\"ל שם נשמחה בו בו ממש בפנימית מהותו ועצמותו כמו שהוא בלי הסתר לבוש דהשגת שכל ובינה שהרי אמר לית מחשבה תפיסא ביה כלל משום דבמחשבה אינו נתפס רק בחי' החיצוניות שלו ע\"י השתלשלות דחו\"ב מאין ליש לבד כנ\"ל והוא חיצוניות התורה הנגלות לנו דאורייתא מח\"ע נפקת<sup data-n=\"2202\">12</sup> בגלוי אבל כשיעברו בנהר פרת בעת קיבוץ גליות בימי משיח אז א' אראנו נפלאות פי' נפלאות ריבוי הנפלאות אשר סתום ונעלם בהעלם אחר העלם שנק' סד\"ס דלמת\"ב כלל אראנו שיבאו כל בחי' הנפלאות עליונים הסתומים וגנוזים במהו\"ע",[["2191","1","<b>ולא ילמדו. . אותי</b>: ירמי' לא, לג [בדילוג]."],["2192","2","<b>שתמלא הארץ. . לים</b>: ישעי' יא, ט."],["2193","3","<b>למודי הוי\"ה. . אאלפך</b>: נסמן לעיל לא, ב."],["2194","4","<b>ישקני מנשיקות פיהו</b>: שה\"ש א, ב."],["2195","5","<b>באור פני מלך</b>: משלי טז, טו."],["2196","6","<b>משיח. . פנימית אבא. . ע\"י</b>: ראה גם לעיל פט, א ובהנסמן במ\"מ לשם."],["2197","7","<b>והריחו. . דמורח ודאין</b>: ישעי' יא, ג. סנהדרין צג, ב. ראה הנסמן במאמרי אדה\"א דברים ח\"א ע' יז. נ\"ך ע' תעו."],["2198","8","<b>בעדן עין לא ראתה</b>: ראה ברכות לד, ב. ישעי' סד, ג."],["2199","9","<b>כימי צאתך מא\"מ</b>: נסמן לעיל ט, ב."],["2200","10","<b>בנהר יעברו ברגל</b>: תהלים סו, ו."],["2201","11","<b>פרת. . היוצא מעדן</b>: ראה לעיל פג, ב."],["2202","12","<b>דאורייתא מח\"ע נפקת</b>: נסמן לעיל כג, א."]]],[2800530193,"לידי גלוי והיינו בחי' התגלות פנימי' התורה שהן טעמי מצות שנק' ג\"כ בשם נפלאות כמ\"ש דוד גל עיני<sup data-n=\"2203\">13</sup> ואביטה נפלאות מתורתיך דאוריי' סתים וגליא<sup data-n=\"2204\">14</sup> וע\"י משה רבינו ניתנה התורה הנגלית לנו והנסתרות שנק' נפלאות פלאות חכמ'<sup data-n=\"2205\">15</sup> שבתורה כמו שהיא נמשך ע\"י משיח בהיותו בבחי' פנימית שם מ\"ה דמשה אור החכמה כו' שהוא בחי' פנימית אבא והיינו שאמרו במשה יבא טוב ויקבל טוב<sup data-n=\"2206\">16</sup> כו' דמשה עצמו שנק' טוב טית רבתי<sup data-n=\"2207\">17</sup> שכולו טוב מבחי' עה\"ח שלמעל' מעה\"ד הוא שעתיד לבוא עוד הפעם ליתן התורה שנק' טוב והוא משה הוא משיח<sup data-n=\"2208\">18</sup> כמ\"ש מה שמו מה שם בנו<sup data-n=\"2209\">19</sup> כו' והיינו פנימית התורה טעמי מצות שנק' נפלאות וד\"ל:\n(סא) <b>והנה</b> כמו שמבואר למעלה בענין קבלת התור' הנגלית לנו ע\"י משה הוצרך ה' להעביר ישראל עמו בי\"ס מטעם שיהי' הכנה בנפשם לקבלה זו ע\"י בקיעת המסך שבין אצי' לבריאה<sup data-n=\"2210\">20</sup> בבחי' המל' שנק' ים<sup data-n=\"2211\">21</sup> שיוכל להיו' חיבור וקשר ע\"י תו\"מ בפ\"מ מאצי' לבריא' ומבריאה לאצי' בהעלאות והמשכו' כך ממש בהעברה שני' בנהר פרת בשביל קבלת התורה בפנימית הוא שיהיה הכנה בנפשם עי\"ז דוקא שיהיו בחי' בית קיבול לקבלת התורה בפנימית טעמי המצות בבחי' ראי' והסתכלות דפנימית חכמה הנ\"ל והיינו בהעברה בבחי' נהר שיוצא מעדן שהוא בחי' בינה דאצי' בחי' ה\"א ראשונה דשם הוי' בכלל והיינו מה שהיה ענין קי\"ס בבחי' המל' שהוא בה\"א תתאה כידוע דתרין נוקבין פריש שלמה<sup data-n=\"2212\">22</sup> מלכא כו' אתי מלבנון כלה<sup data-n=\"2213\">23</sup> כו' שהן ב' ההי\"ן דשם הוי'<sup data-n=\"2214\">24</sup> ה\"א תתאה דמל' וה\"א עילאה דבינה וכתיב כאמה בתה<sup data-n=\"2215\">25</sup> כו' דהמל' נק' בת<sup data-n=\"2216\">26</sup> ונק' אימא תתאה<sup data-n=\"2217\">27</sup> ובחי' בינה נקרא אם כמ\"ש כי אם לבינה תקרא<sup data-n=\"2218\">28</sup> כו' והוא בחי' אימא עילאה<sup data-n=\"2219\">29</sup> שנק' נהר<sup data-n=\"2220\">30</sup> שמקבל מעדן ולע\"ל יהיה מסלה לשאר עמו<sup data-n=\"2221\">31</sup> כו' בנהר דבינה עילאה כמו שהיתה ביום עלותו מא\"מ בקי\"ס בה\"א תתאה (והיינו ג\"כ שם הגדולה לאה עולם המח'<sup data-n=\"2222\">33</sup> ושם הקטנה רחל<sup data-n=\"2223\">32</sup> עולם הדבור<sup data-n=\"2224\">34</sup> ) דבשביל קבלת התו' בנסתר שנק' עדן אשר עין לא ראתה עדיין כנ\"ל הוצרך להעביר לישרא' העבר' שנייה היותר עליונ' והוא בנהר העליון דבינה דאצילות וז\"ש עד יעבור עמך ה' בקי\"ס עד יעבור סתם למעלה משם הוי'<sup data-n=\"2225\">35</sup> בהעברה שניה זו בנהר פרת והוא אהי' אשר אהי' דאנא זמין לאתגלא'<sup data-n=\"2226\">36</sup> כו' משום דכל עיקר ההפרש בין ים דמל' לנהר דבינה היינו רק במה שהמל' שהוא עולם הדיבור<sup data-n=\"2227\">37</sup> עלמא דאתגליא אינו נק' גלוי רק שנתגלה בדבור כל הע\"ס דאצילו' שבאו כבר בגלוי מן ההעלם הכלולי' בד' אותיות הוי\"ה והוא מבחי' אור הכתר בחכמה שהוא קוצו ש\"י<sup data-n=\"2228\">38</sup> וחכמה ובינה תרין רעין אין ויש<sup data-n=\"2229\">39</sup> שהן י\"ה<sup data-n=\"2230\">40</sup> עד מדו' ודבור וז\"ש כל הנחלי'<sup data-n=\"2231\">41</sup> הולכי' אל הים היינו גם מדות שבכתר שנגלים בחו\"ב ששם נקראו מדות שבשכל עד מדו' הנולדי' בלב שנק' וי\"ו<sup data-n=\"2232\">42</sup> הכל נמשך ובא בדבו' שנק' ים לכסות עליה' כנ\"ל במשל הבריות שבים למטה וכאשר נהפך ים ליבשה היינו רק שמה שהיה מסתיר הדבור בא לגלוי והיינו גלוי כל אורות עליונים דאצילות לבד אבל העברה שני' בבינה דאצי' היינו בחי' גלוי של כל האורו' עליוני' הסתומי' ונעלמים בעצמו' המאציל דוק' והיינו כמו כל בחי' הנפלאו' דטעמי תורה שבבחי' פנימית ע\"י שהוא ממהות ועצמות התענוג שבעצמות א\"ס שמלובש בבחי' פנימית החכמ' שנק' עדן סתימאה<sup data-n=\"2233\">43</sup> שעין לא ראתה עדיין כנ\"ל הוא שבא לידי גלוי בבינה דאצי' כי הי' בחי'",[["2203","13","<b>גל עיני</b>: תהלים קיט, יח."],["2204","14","<b>דאוריי' סתים וגליא</b>: ראה זהר אחרי עא, ב. עג, א."],["2205","15","<b>פלאות חכמ'</b>: ראה גם לקמן קכז, ב ובהנסמן במ\"מ לשם."],["2206","16","<b>יבא טוב ויקבל טוב</b>: נסמן לעיל פט, א."],["2207","17","<b>דמשה. . טוב טית רבתי</b>: שמות ב, ב ובמנחת שי שם. ראה לקמן צח, ב. מאמרי אדה\"א קונטרסים ע' שצג. וש\"נ. בראשית ע' קלט. וש\"נ."],["2208","18","<b>משה הוא משיח</b>: ראה גם תו\"ח בראשית יד, ריש ע\"ב ובהערה 12."],["2209","19","<b>מה שמו מה שם בנו</b>: משלי ל, ד [ושם: ומה ? נסמן לקמן קלב, ב]. ראה מאמרי אדה\"א ויקרא ח\"א ע' טז. במדבר ח\"א ע' רסט וע' רצה. דברים ח\"א ע' לד ובהנסמן בהנ\"ל."],["2210","20","<b>המסך שבין אצי' לבריאה</b>: נסמן לקמן קטז, א."],["2211","21","<b>המל' שנק' ים</b>: נסמן לעיל סז, א."],["2212","22","<b>דתרין נוקבין פריש שלמה</b>: נסמן לקמן קלד, ב."],["2213","23","<b>אתי מלבנון כלה</b>: שה\"ש ד, ח."],["2214","24","<b>ב' ההי\"ן דשם הוי'</b>: ראה ת\"ז בהקדמה (ו, ב)."],["2215","25","<b>כאמה בתה</b>: יחזקאל טז, מד."],["2216","26","<b>דהמל' נק' בת</b>: ראה פרדס (שער ערה\"כ) שכ\"ג מערכת בת."],["2217","27","<b>דהמל' נק'. . אימא תתאה</b>: נסמן לקמן קמא, ב."],["2218","28","<b>כי אם לבינה תקרא</b>: משלי ב, ג. ראה אוה\"ת משלי (כרך א) ע' תקמז."],["2219","29","<b>אימא עילאה</b>: ראה ע\"ח (שער או\"א) שי\"ד פ\"ח."],["2220","30","<b>שנק' נהר</b>: זהר (אדרא דמשכנא) משפטים קכג, ב."],["2221","31","<b>יהיה מסלה לשאר עמו</b>: ישעי' יא, טז."],["2222","33","<b>לאה עולם המח'</b>: נסמן לקמן קלג, ב."],["2223","32","<b>שם הגדולה לאה. . רחל</b>: ויצא כט, טז."],["2224","34","<b>רחל עולם הדבור</b>: נסמן לקמן שם."],["2225","35","<b>עד יעבור. . למעלה משם הוי'</b>: נסמן לעיל לא, א."],["2226","36","<b>אהי' אשר אהי'. . לאתגלא'</b>: שמות ג, יד. ראה זהר ויקרא יא, א. אחרי סה, א."],["2227","37","<b>שהמל'. . הדיבור</b>: נסמן לעיל פד, ב."],["2228","38","<b>הכתר. . קוצו ש\"י</b>: נסמן לעיל לג, ב."],["2229","39","<b>וחכמה ובינה תרין רעין אין ויש</b>: ראה גם לקמן קכז, א ובהנסמן במ\"מ לשם."],["2230","40","<b>וחכמה ובינה. . שהן י\"ה</b>: נסמן לעיל ו, א."],["2231","41","<b>כל הנחלי'</b>: קהלת א, ז."],["2232","42","<b>מדו'. . וי\"ו</b>: ראה אגה\"ת פ\"ד."],["2233","43","<b>עדן סתימאה</b>: ראה גם לעיל סא, ב ובהנסמן במ\"מ לשם."]]],[2800530194,"ההשגה דבינה שנק' מאמר סתום מסתיר ומעלי' ומכסה על כל האורות הסתומי' שבעצמות שנק' סדכ\"ס כנ\"ל באריכות שהמחשב' והשגה מכסה על נקוד' הפנימי' כו' ויצא לידי גלוי כשיעברו בנהר זה ברגל כמו שהפך ים ליבשה ממש וזהו עד יעבור סתם למעל' משם הוי\"ה מפני שזה הגלוי הוא גלוי אורו' הסתומי' שבעצמו' שלמעלה מע\"ס דאצי' הגלויים שהן ד' אותיות דשם הוי\"ה ע\"ב ס\"ג מ\"ה ב\"ן<sup data-n=\"2234\">1</sup> כו' וע\"כ אמר שם נשמחה בו בו ממש כנ\"ל וכמ\"ש ביום הג' יקימנו<sup data-n=\"2235\">2</sup> ונחיה לפניו ממש וע\"כ יהיה אז קי\"ס טפל לגבי העיקר כנ\"ל באריכות וד\"ל ומעתה אחר כל הנ\"ל יתורץ כל הדקדוקים הנ\"ל על מ\"ש בישעיה<sup data-n=\"2236\">3</sup> והניף ידו על הנהר כו' והכהו לז' נחלים כו' ובקי\"ס אמר לגוזר י\"ס לגזרים שהן י\"ב גזרי'<sup data-n=\"2237\">4</sup> כו' דהנה מ\"ש ישכיל עבדי מבואר למעל' שזהו בבחי' פנימי' העדן סתימא' דעין לא ראת' כו' ישכיל להשפיע לכנ\"י ג\"כ פנימית התורה וזהו ירום ונשא וגבה מאד בהיפך אותיות אדם<sup data-n=\"2238\">5</sup> להיות ידוע דמקור הראשון לתולדות המדות<sup data-n=\"2239\">6</sup> הוא מבחי' אור החכמה שנקרא אב<sup data-n=\"2240\">7</sup> המוליד ונמשך לבינה שנק' אם הבנים<sup data-n=\"2241\">8</sup> כו' וביאור הדבר ידוע שזהו עד\"מ מטפה של האב שיש בכחה כל אברי הולד ומצטייר אח\"כ בבטן האם כו' כך הוא בהתהוות מציאות המדות אוי\"ר והתפארות כו' הרי המה כלולים באור החכמה בהעלם גדול ויוצאי' לגלוי בהשגת שכל דבינ' שנק' יש כידוע בענין מי ברא אלה<sup data-n=\"2242\">9</sup> כו' לפי שבחי' החכמ' הוא בבחי' נקוד' דאין בבחי' ביטול עצמי כח מ\"ה כו' לא ניכר שם עדיין התפעלו' האהבה אך כאשר בא לכלל השגה בבינה ודעת ניכר שם מציאות התפעלות אוי\"ר כו' ונק' מדות שבשכל ממש כמו עיבור הולד במעי אמו שהוא מהות בפ\"ע רק שכלול בבטן אמו וירך אמו הוא כו' וכמו שאנו רואי' בחוש כאשר ישיג במוח הבינ' באיזה התבוננות בגדולת ה' בשעת התפלה הרי מתפעל באהבה במוח עצמו וכן בירא' והכל עדיין במוח ונק' דו\"ר שכליים ממש כידוע ואח\"כ הן יוצאי' מן העלם השכל שבמוח לגלוי התפעלו' הלב באוי\"ר במורגש בלב שזהו כבן הנולד מבטן אמו לחוץ כידוע וכמו כן אנו רואים במדות שבחו\"ב כאשר עוסק בדבר משפט שיטה שכלו לחסד או לדין או בהכרע' מחו\"ג שזהו מדות שבשכל והשגה דבינה שהרי מראה טוב טעם ודעת לזכות וכן מראה להיפך שכל וטעם לדין והרי ניכר מציאות ב' השכליים ההפכיים דחו\"ג הללו במוח הבינה מפני שהוא בחי' גלוי ההשגה בכי טוב כו' אבל בעוד שלא בא לכלל השגת שכל וטעם רק הוא עדיין בהעלם במוח החכמה שנק' אין שזהו הנקודה שכל ותמצית טרם שבא לכלל הבנה בהסבר כנ\"ל לא ניכר שם התחלקות מציאות ב' מיני שכליים דחו\"ג שבשכל כלל אבל משם מקור מציאותם בודאי כטפה דאב המוליד בכחה דוקא כל ציור הולד וד\"ל. אך הנה כל זה במדות שנתהוו מבחי' אין דחכמה שנמשך לבינה אבל למעלה מהמשכה זו דחכמה בבינה לא שייך שם ענין תולדות מציאות המדות מן השכל כלל דלא שייך תולדה רק מאב ואם כמו בחו\"ב המולידים כו' ואע\"פ שאנו רואי' שיש מציאות מדו' כאלה גם ברצון ותענוג שלמעלה מן החכמה כמו אהבה רבה בתענוגים ואהבה שברצון לחסד למעל' מן השכל וטעם כי אין טעם לרצון כלל<sup data-n=\"2243\">10</sup> כידוע וכן לדין כו' הנה אין מדות אלה באי' בדרך תולדה כלל אלא המה מדות עצמיי' הנטועים ומושרשי' בעצם הנפש שנק' בחי' יחידה ומאירים ברצון ותענוג בהתפשטות בבחי' בלתי",[["2234","1","<b>ד' אותיות. . הוי\"ה ע\"ב. . ב\"ן</b>: ראה ע\"ח (שער דרושי אבי\"ע) שמ\"ב רפ\"א."],["2235","2","<b>ביום הג' יקימנו</b>: הושע ו, ב."],["2236","3","<b>בישעי'</b>: יא, טו."],["2237","4","<b>לגוזר. . י\"ב גזרי'</b>: תהלים קלו, יג. נסמן לעיל סח, ב."],["2238","5","<b>מאד בהיפך אותיות אדם</b>: ראה גם לעיל פט, א ובהנסמן במ\"מ לשם."],["2239","6","<b>דמקור הראשון לתולדות המדות</b>: ראה תניא פ\"ג."],["2240","7","<b>החכמה שנק' אב</b>: ראה גם הנסמן לעיל ח, ב."],["2241","8","<b>לבינה שנק' אם הבנים</b>: ראה גם הנסמן לקמן קי, ב."],["2242","9","<b>מי ברא אלה</b>: ישעי' מ, כו. ראה סה\"מ תקס\"ה ח\"ב ע' תקפט ואילך. לקו\"ת במדבר ו, ד."],["2243","10","<b>אין טעם לרצון כלל</b>: נסמן לקמן קכב, א."]]],[2800530195,"מוגבל כלל דהיינו שלא יוגבלו בשכל וטעם כלל כו' והנמשל מכל זה יובן במ\"ש בהעברה שני' בנהר פרת והניף ידו על הנהר והכהו לז' נחלים דוקא דהנה שבע' נחלים אלה הן ז' מדות שבבינה דאצי' שכלולים בנ' שערי בינה<sup data-n=\"2244\">11</sup> דמ\"ט שערים הן זפ\"ז והן כמו מדות שבשכל והשגה הנ\"ל שמוגבלים הם לפי ערך כח המולידם ושרשם הראשון הוא באור אבא שמשפיע לאימא עילא' בחי' בינה אם הבנים כנ\"ל ומבואר למעל' בעיקר ענין העבר' זו בנהר שיוצא מעדן שהוא להיות גלוי ההעלם והכיסוי שלא יכסה ויעלים בחי' ההשגה וטעם לפנימי' ועצמות כו' ע\"כ כאשר העביר בנהר זה הכהו לז' נחלים היינו לז' מדו' שבבינה שלא יעלימו ויסתירו עוד כמו שהן בהשגת שכל והיינו מצד שהאיר מאור הנעל' וסתום דעדן סתימאה הנ\"ל שהוא למעלה הרב' מבחי' החכמ' שנק' אין ליש כנ\"ל ושם הז' מדות הן בבחי' אור א\"ס ממש שמאיר בפנימי' התענוג ורצון כו' וכמבואר למעל' שזהו כל עיקר מעלת העברה שניה בנהר דבינ' מה שהוא גלוי כל אורו' הסתומים ביותר בפנימי' ועצמו' המאציל כו' שיבואו לגלוי כו' ולכך הכהו לז' נחלים ובז' נחלים העבירם ביבשה ברגל בלי לבוש מסתיר כלל וכלל והן בחי' ז' מדות דע\"י וא\"א כו' בלא התלבשות בחו\"ב כלל וד\"ל וזהו ישכיל כו' ירום ונשא וגבה ג' מדות חג\"ת דאבות כנ\"ל אבל הכל במדות שבעצמות אא\"ס שבפנימית ע\"י וא\"א כנ\"ל וע\"כ אמר מאד היפוך אותיות אדם דאדם גי' מ\"ה<sup data-n=\"2245\">12</sup> הוא שרש התהוות מציאו' המדות מחכמ' לבינה כנ\"ל וכמ\"ש מה שמו כו' אבל למעלה מבחי' אדם היינו למעלה מבחי' חכמה דשם מ\"ה להוליד מדות דאדם כו' והוא פנימית ועצמות אור א\"ס שבכתר והיינו בחי' פנימי' ועצמות דחכמה בראיה והסתכלות העצמיו' הנ\"ל וזהו נק' מאד בהיפך אדם שהו' בלי גבול כלל כי א\"א שיבואו בגבול דחו\"ב כנ\"ל והיינו פנימית התור' שיקבלו ע\"י משיח שנא' בה ארוכה מארץ מדה<sup data-n=\"2246\">13</sup> ורחבה מני ים כו' דלא יכילנה ארץ וים עלמא דאתכסייא ועלמא דאתגלייא<sup data-n=\"2247\">14</sup> כו' אפי' ים העליון שהוא נהר שיוצא מעדן שמשוטט בלי הפסק כלל כנ\"ל אבל הנהר עצמו מכסה על מקורו ובהעברה בנהר שיופסק ויוסר הכיסוי דנהר שהוא השגה דבינה אז דוקא יתגלה פנימית התורה שהיא בלי שיעור ומדה כלל ומכ\"ש שלא יכילנה ים התחתון שהוא הדיבור שיש לו הפסק כנ\"ל וכמ\"ש דוד נפלאותיך ומחשבותיך אלינו<sup data-n=\"2248\">15</sup> אגידה ואדברה עצמו מספר כו' וד\"ל אך בקי\"ס שהי' בבחי' הדבור נקרע לי\"ב גזרים דוקא לפי שבדבור נמשכו המדות חג\"ת שבלב להתחלקות ששה בכפליים נגד י\"ב שבטים י\"ב ג\"א<sup data-n=\"2249\">16</sup> בעלמא דדכורא ויב\"ש בעלמא דנוק'<sup data-n=\"2250\">17</sup> כמ\"ש ששם עלו שבטים<sup data-n=\"2251\">18</sup> כו' כנ\"ל מפני שהוא בשביל התורה הנגלית דוקא שיבא לגלוי בת\"ר אלף נש\"י<sup data-n=\"2252\">19</sup> למטה לשמור ולעשות צריך לקרוע לי\"ב דוקא משא\"כ בעלי' המל' כנ\"י בהעבר' שניה בנהר דבינה עילאה הרי עולין למקורן ושרשן שלמעל' מחו\"ב שנקרא או\"א דהיינו למדות שבע\"י שהן ז' נחלים עליונים והן הנק' ימי קדם כמ\"ש אשר נשבעת לאבותינו מימי קדם<sup data-n=\"2253\">20</sup> כמ\"ש במ\"א וד\"ל:\n(סב) <b>ובכל</b> זה יובן<sup data-n=\"2254\">21</sup> מ\"ש הים ראה וינוס כו' ההרים רקדו כאלים<sup data-n=\"2255\">22</sup> כו' דלכאורה מה ענין הרים לכאן דבשלמא הים ראה וינוס לפי שרוח קדים עזה בקע הים<sup data-n=\"2256\">23</sup> כו' אבל ריקוד ההרים מה ענין",[["2244","11","<b>בנ' שערי בינה</b>: ר\"ה כא, ב."],["2245","12","<b>דאדם גי' מ\"ה</b>: נסמן לעיל ס, א."],["2246","13","<b>ארוכה מארץ מדה</b>: איוב יא, ט."],["2247","14","<b>ארץ וים עלמא דאתכסייא. . דאתגלייא</b>: נסמן לעיל לב, ב."],["2248","15","<b>נפלאותיך ומחשבותיך אלינו</b>: תהלים מ, ו [בדילוג]."],["2249","16","<b>י\"ב שבטים י\"ב ג\"א</b>: ראה ס' הבהיר סמ\"ב. זהר במדבר קיח, ב ובביאוה\"ז לשם פה, א ואילך. מאמרי אדה\"א דברים ח\"ב ע' תסז ואילך. וש\"נ."],["2250","17","<b>י\"ב שבטים. . בעלמא דדכורא. . דנוק'</b>: נסמן לעיל מד, ב."],["2251","18","<b>ששם עלו שבטים</b>: תהלים קכב, ד."],["2252","19","<b>בת\"ר אלף נש\"י</b>: ראה שבת פח, א."],["2253","20","<b>אשר נשבעת לאבותינו מימי קדם</b>: מיכה ז, כ. ראה מאמרי אדה\"א ויקרא ח\"ב ע' תשעז וע' תתנא. דברים ח\"א ע' נה ובהנסמן בהנ\"ל."],["2254","21","<b>ובכל זה יובן</b>: להבא להלן ראה הנסמן לעיל בריש הדרוש (ח, ב)."],["2255","22","<b>הים ראה. . ההרים רקדו כאלים</b>: תהלים קיד, ג. ד."],["2256","23","<b>שרוח. . בקע הים</b>: בשלח יד, כא."]]],[2800530196,"לקי\"ס כו' אך הנה אמרו שמעו הרים כו' אלו האבות<sup data-n=\"2257\">1</sup> שנק' הרים כו' והיינו בחי' המדות עליונות חג\"ת שהאבות הן המרכבה למדות חג\"ת<sup data-n=\"2258\">2</sup> כידוע והים הוא בחי' המל' כמ\"ש כל הנחלים הולכים אל הים והנחלים הן המדות שנמשכים לדבור העליון שנק' ים העליון ותחלה אמר שהים שהוא המל' ראה וינוס ואח\"כ גם ההרים שהן המדות רקדו כאלים כו' וד\"ל ולהבין ביאור זה יש להקדים תחלה בתוס' ביאור בענין קי\"ס בז' של פסח<sup data-n=\"2259\">3</sup> דוקא דהנה מבואר בפע\"ח<sup data-n=\"2260\">4</sup> דבז' ש\"פ הוא זמן לידת הנשמות ובשמיני עצרת היה זמן של בחי' הקליטה כו' ומשמ\"ע עד ז' ש\"פ הוא ששה חדשים<sup data-n=\"2261\">5</sup> וכשאדר מעובר הוא ז' חדשים שיולדת לז' כו' ויש להבין איך יתכן ל' לידה במה שהלכו בנ\"י בתוך הים ביבשה ומהו ענין העיבור כו' והנה יש להקדים מ\"ש למען אחי ורעי<sup data-n=\"2262\">6</sup> אדברה נא שלום כו' אחיי ורעיי הן ישראל שנק' אחים וריעי' להקב\"ה כו' והענין ידוע דבחי' מדות דאצי' נק' קוב\"ה שהוא בחי' ז\"א<sup data-n=\"2263\">7</sup> וישראל שרשם במח' כמאמר ישראל עלה במח'<sup data-n=\"2264\">8</sup> אך א\"כ איך יקראו בנ\"י אחים להקב\"ה כו' אך הנה ידוע דהמח' נק' לבוש לשכל ולמדות שמלבשת לאור השכל ומתאחדת עמו וכמ\"כ מלבשת למדות ומתאחדת עמהם דהנה אנו רואים שכל שכל וחכמה בהכרח שמיד יבא בהתלבשות בצירופי אותיות מחשבה כמו גם מחשבה העיונית כאשר יטרוד בעיון ההשכל' א\"א שלא יחשוב אותו באופן צרופים שונים בכלי המוח באותיות מח' ולא ניכר כלל שהאותיות מחשבת שכל זה נפרד במהות בפ\"ע כלל אלא מתאחדים עמו ממש בלי פירוד כלל ביניהם והיו לאחדים ממש כאלו המה עצם אחד מתחלת ההוי' והמציאת וזהו הנק' מחשב' שכל העיונית כאשר טרוד בשכלו בעיון דבר מה הוא נתפס מיד במחשב' בצרופים שונים ובלתי זה אין לו מציאת שכל כלל והנה לכאור' אנו רואים היפך זה ממש דהיינו שהמח' נק' לבוש נפרד לגמרי ממה שיוכל לחשוב דברים בטלים שאינו דבר שכל כלל וגם במח' זו שנתפס אור השכל מיד יוכל לפושטו ולהתמשך באופן צירופים אחרים לגמרי בשנוי גמור מן הקצה כמו הפושט לבוש ולובש לבוש אח\"כ כמו לבוש יחליפם<sup data-n=\"2265\">9</sup> השכל ממח' למח' פושט ולוב' לפי שבאמת יש לשכל עצמו מציאת ומהות בפ\"ע טרם בואו להתלב' באותיות מח' ומ\"מ אנו רואים שאחרי התלבשות השכל במח' מתאחדת המח' עמו בתכלית כנ\"ל הענין הוא דשניהם אמת דאית מח' ואית מח'<sup data-n=\"2266\">10</sup> כו' דמח' זו שמתלבשת לשכל נק' לבו' שפושט כנ\"ל אבל מח' עצמית שקבוע' בנפש מתאחדת עם עצם הנפש ממש ומח' זו נמשכת ונובעת בתמידות וע\"ז אמר ישראל עלה במח' הקדומ' ומשם נמשך אותיות מח' מיוחדים השייכים לכל שכל וחכמ' בפרט שא\"א לו להתפס כ\"א באותן אותיות דוקא דהיינו כאשר נתהווה עצם אור השכל ממקורו נתהווה ונמשך מאותו מקור גם האותיות מח' ששייכים ומיוחדים אליו דוקא והיינו ענין ג' קשרין<sup data-n=\"2267\">11</sup> ישראל מתקשראן באורייתא שהן ת\"ר אלף נש\"י<sup data-n=\"2268\">12</sup> שכ\"א מקושר באות א'<sup data-n=\"2269\">13</sup> מס\"ר אותיות התורה<sup data-n=\"2270\">14</sup> כמ\"ש זה ספר תולדות אדם<sup data-n=\"2271\">15</sup> כו' והיינו משום דאורייתא מח\"ע נפקת והוא בחי' אור אבא שמשם ג\"כ נחצבו נש\"י כמ\"ש כי אתה אבינו<sup data-n=\"2272\">16</sup> כטפה שנולד הולד כו' וס\"ר נש\"י היינו ס\"ר אותיות הכלולים",[["2257","1","<b>שמעו הרים. . האבות</b>: מיכה ו, ב. ראה ר\"ה יא, א. הנסמן לעיל כה, א."],["2258","2","<b>שהאבות. . חג\"ת</b>: נסמן לקמן קלג, ב. וראה גם הנסמן לעיל כה, א."],["2259","3","<b>קי\"ס בז' של פסח</b>: ראה סוטה יב, ב וברש\"י. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' ריט."],["2260","4","<b>בפע\"ח</b>: ראה (שער הלולב) שכ\"ט ספ\"ח. הנסמן במאמרי אדה\"א ויקרא כאן (ע' שפז). דברים ח\"ד ע' א'רעט בשם הע\"ח."],["2261","5","<b>ששה חדשים</b>: כ\"ה בפע\"ח שם. ובמאמרי אדה\"ז תקע\"א כאן ז\"ח. ראה הנסמן במאמרי אדה\"א ויקרא כאן (ע' שפז)."],["2262","6","<b>למען אחי ורעי</b>: תהלים קכב, ח. ראה זהר משפטים קכב, רע\"א. סה\"מ תקס\"ה ח\"א ע' קכח. תקס\"ו ע' קכח. ביאוה\"ז פינחס קיד, ד ואילך. הנסמן במאמרי אדה\"א בראשית ע' שמה."],["2263","7","<b>קוב\"ה. . ז\"א</b>: ראה סידור שער התפילין ז, ג. הנסמן בתו\"ח נח סט, א הערה 1."],["2264","8","<b>ישראל עלה במח'</b>: נסמן לעיל לז, ב."],["2265","9","<b>כמו לבוש יחליפם</b>: ע\"פ תהלים קב, כז. ראה גם לקמן קלו, ב."],["2266","10","<b>דאית מח' ואית מח'</b>: ראה ת\"ז תס\"ט (קט, א)."],["2267","11","<b>ג' קשרין</b>: נסמן לעיל סב, ב."],["2268","12","<b>ת\"ר אלף נש\"י</b>: ראה ביאוה\"ז קה, ב. הנסמן במאמרי אדה\"א ויקרא כאן (ע' שפח)."],["2269","13","<b>שכ\"א מקושר באות א'</b>: ראה מג\"ע אופן קפו. מאמרי אדה\"א במדבר ח\"ג ע' תתפט. דברים ח\"ג ע' תשעט. הנחות תקע\"ז ע' רנב ובהנסמן בהנ\"ל. שע\"ת פג, ד."],["2270","14","<b>מס\"ר אותיות התורה</b>: ראה ז\"ח שה\"ש עד, ד. מג\"ע שם. לקו\"ש (טו\"ב כסלו תשמ\"א) כרך כ ע' 419 בהערה. שו\"ת הצ\"צ חאבה\"ע סרמ\"ט (צה, א)."],["2271","15","<b>זה ספר תולדות אדם</b>: בראשית ה, א."],["2272","16","<b>כי אתה אבינו</b>: ישעי' סג, טז."]]],[2800530197,"באור אבא ומתאחדים שם כמח' העצמית שמתאחדת בעצם כנ\"ל וזהו אורייתא בקוב\"ה דהיינו מוחין דאבא שבז\"א שנמצא ישראל נק' אחים וריעים לקוב\"ה לפי שממקור אחד נמשכו שהוא מאור אבא כו' והן ס\"ר אותיות דתושב\"כ שס\"ר נש\"י מתקשראן שם וד\"ל אך א\"כ למה נק' אחים וריעים דריעים משמע בדומה לו ממש כו' אך הנה מה שנק' ריעים האהובים היינו בשרשם בעצמות אא\"ס שמשם נמשך גם אור החכמה וכמו אמרי לחכמה אחותי את<sup data-n=\"2273\">17</sup> כו' והוא להיות שרשם במחשבה העצמות ממש והחכמה הוא ביו\"ד בחינת שם ע\"ב כו' וה\"א בינה שם ס\"ג<sup data-n=\"2274\">18</sup> אבל מצד עצמו לאו מכל אינון מדו'<sup data-n=\"2275\">19</sup> ושמות כלל כו' וזהו להקב\"ה קדש דחכ'<sup data-n=\"2276\">20</sup> נק' ריעים ולבחי' המדו' שבו מלובש המוחין דאבא נקראו אחי' והוא להיו' שהמחשב' הוא שנתהווה עם המדות ביחד כמו שהמח' מתהווה עם השכל כנ\"ל שהרי אנו רואים בחוש שמיד שחפץ בלבו איזה דבר מה יהרהר במח' ומתאחד מאד הרהור זה עם האהבה והיו לאחדי' אע\"פ שנראה ג\"כ כמו לבוש שיוכל לפשוט ולהרהר באופן אחר כנ\"ל בשכל מ\"מ יש אותיות מחשב' מיוחדים לכל מדה מתחלת התהוותה מן השכל ומפני זה נק' אחים לקוב\"ה שהן המדות שהרי מספר בנ\"י ת\"ר אלף כמו מספר התחלקות הו' מדות דז\"א<sup data-n=\"2277\">21</sup> כו' ונמצא ס\"ר נש\"י שרשם בס\"ר אותיות המחשבה שמתאחד בו' מדו' דז\"א כמו שנש\"י באור אבא נאצלו יחד ששם נק' ריעים או נק' שבטי יה דוקא ובו\"ק דז\"א נק' שבטים סתם שהן י\"ב ג\"א שבו\"ק דז\"א וז\"ש מה שמו הוא מ\"ה דחכמה דאור אבא ומה שם בנו בו\"ק דז\"א שנק' קוב\"ה מוחין דאבא שבז\"א כידוע בענין קדוש וברוך<sup data-n=\"2278\">22</sup> וע\"כ נקרא אחים וריעים אחים בז\"א וריעי' באו\"א וד\"ל (ונמצא הסדר דג' קשרין בב' אופנים הא' דישראל מתקשראן בס\"ר אותיות דחכמ' דתורה שהוא באור אבא שנק' קוב\"ה בקדש העליון דאבא ואורייתא בקוב\"ה היינו משום דאורייתא וקוב\"ה כולא חד<sup data-n=\"2279\">23</sup> שזהו מצד גלוי אור א\"ס בח\"ע כו' וכאשר נמשך למטה יותר היינו מוחין דאבא שבז\"א שנק' קוב\"ה סתם ששם נק' אחים מטעם הנ\"ל והב' למעלה גם מאור אבא והוא שעלו במח' הקדומה וזהו חכמה הקדומה<sup data-n=\"2280\">24</sup> דתורה קדמה לעולם<sup data-n=\"2281\">25</sup> ואוריי' בקוב\"ה בעצמו' אא\"ס הגם דלמת\"ב כלל<sup data-n=\"2282\">26</sup> כו' אבל מח' העצמי' דתורה כתיב בה ואהי' אצלו<sup data-n=\"2283\">27</sup> כו' דהיינו בבחי' סתים דאוריי' וקוב\"ה וגם בבחי' הגליא יש ב' מדריגו' אחים בז\"א וריעי' באו\"א כנ\"ל וד\"ל<sup data-n=\"2284\">28</sup> והנה כ\"ז הוא בבחי' שרש הנשמות דישראל כמו שעלו במח' הקדומה דחכמ' עד מח' שבמדות עליונו' דאצי' שכללותם נק' אחים וריעים להקב\"ה כנ\"ל שהוא בבחי' אלקות ממש דאיהו וחיוהי חד<sup data-n=\"2285\">29</sup> כידוע אך אמנם נשמות דבריאה יש מאין כמו אתה בראת<sup data-n=\"2286\">30</sup> יצרת כו' וכמ\"ש כל הנק' בשמי בראתיו יצרתיו כו' עד נשמ' שבגוף בעוה\"ז דכתיב ביה אף עשיתיו<sup data-n=\"2287\">31</sup> הנה לזה היה תכלית כוונת המאצי' שיהי' נשמה דבריא' בבחי' יש נפרד ממש משום דסוף מעשה עבמ\"ת<sup data-n=\"2288\">32</sup> כידוע<sup data-n=\"2289\">33</sup> כי בהיות הנשמה בבחי' אצי' ולמעלה מעלה הרי היא כלול' ודבוקה באא\"ס בבחי' ביטול והתכללות באין האמיתי כו' דאא\"ס שבאצי' דאיהו וחיוהי חד ומכ\"ש בשרשה הראשון באותיות דחכמה דאצי' ולמעלה מזה כמו שהיא במח' העצמית",[["2273","17","<b>אמרי לחכמה אחותי את</b>: משלי ז, ד [ושם: אמר ? ראה מאמרי אדה\"א בראשית ע' שמט]."],["2274","18","<b>והחכמה. . שם ע\"ב. . ס\"ג</b>: נסמן לקמן קכח, ב."],["2275","19","<b>לאו מכל אינון מדו'</b>: ראה ת\"ז בהקדמה (יז, ב)."],["2276","20","<b>קדש דחכ'</b>: נסמן לעיל כט, א."],["2277","21","<b>בנ\"י. . הו' מדות דז\"א</b>: ראה גם לקו\"ת להאריז\"ל פ' וישב דרוש גלות מצרים."],["2278","22","<b>קדוש וברוך</b>: ראה גם סידור שער התפילין ז, ג ואילך. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' רעו. ח\"ב ע' תמה ואילך. וש\"נ."],["2279","23","<b>דאורייתא וקוב\"ה כולא חד</b>: מובא בתניא (פ\"ד ופכ\"ג) בשם הזהר. ראה הנסמן במאמרי אדה\"א ויקרא ח\"א ע' רפה. אוה\"ת חוקת ע' תשס."],["2280","24","<b>חכמה הקדומה</b>: ת\"ז תס\"ט (קטז, ב)."],["2281","25","<b>דתורה קדמה לעולם</b>: פסחים נד, א."],["2282","26","<b>דמת\"ב כלל</b>: ת\"ז בהקדמה (יז, א)."],["2283","27","<b>ואהי' אצלו</b>: משלי ח, ט."],["2284","28","<b>וד\"ל</b>: אוצ\"ל: וד\"ל)."],["2285","29","<b>דאיהו וחיוהי חד</b>: ת\"ז בהקדמה (ג, ב)."],["2286","30","<b>אתה בראת</b>: ברכת אלקי נשמה [בדילוג]."],["2287","31","<b>כל הנק' בשמי. . אף עשיתיו</b>: ישעי' מג, ז [בדילוג]."],["2288","32","<b>דסוף מעשה עבמ\"ח</b>: ע\"פ פיוט לכה דודי."],["2289","33","<b>כידוע</b>: ניתוסף ע\"פ דפו\"ר."]]],[2800530198,"דעצמות א\"ס ממש דמצד עצמו לאו מכל אינון מדות כלל וא\"כ יש להבין האיך אפשר להיות ירידה גדולה כזו שיהי' כ\"כ שינוי גדול מן הקצה כו' להיות התהוות הנשמה האלקי' ממש בבחי' בריאה מוגבלת מאין ליש ממש שהרי יותר משאין ערוך<sup data-n=\"2290\">1</sup> לנברא עם הבורא אין ערוך לנאצל עם עצמו' א\"ס ב\"ה כמ\"ש במ\"א וד\"ל אך הנה הענין הוא דזה השינוי הגדול ממהו' דעצמו' אלקו' להיות בריאה מוגבלת הוא בא ע\"י בחי' עיבור הנשמו' בבטן המל' שמצד שהן בבחי' עיבור במל' דאצי' תחלה אח\"כ כשנולדין ויוצאין לחוץ הן במציאות התהוות בריאה יש נפרד כו':\n(סג) <b>אך</b> להבין ענין העיבור במל' דאצי' מהו הנה יובן עפ\"י הנ\"ל בקי\"ס ובהעברה שני' בנהר פרת שהן ב' ההי\"ן דשם הוי' אימא תתאה ואימא עילא' כנ\"ל דהיינו בחי' הדבור שנק' ים שהוא בחי' המל' סופא דכולא הרי הוא בחי' כיסוי והעלם להעלים ולהסתי' האור הגנוז בו כמו הרצון ושכל ומדו' כמו שהן עצמן במוחא ולבא כו' המה בבחי' האין אמיתי דאור המאציל שבאו\"א וז\"א דאצי' כו' וכאשר באין בדבור שהן צירופי אותיות בהבל הפה העליון שם מתעלמין בלתי ניכר מהות' העצמי ומה שנגלי' מתוך הדבור זהו כמו אור הנראה מתוך המסך ולבוש המכסה ומעלים עצם האור כמו שהוא וז\"ש באורך נראה אור<sup data-n=\"2291\">2</sup> אור של תולדה כנ\"ל וכמו שאנו רואים גלוי רצון ושכל או אהבה שבאה מתוך הבל הדבור שהוא בשינוי המהו' לגמרי מכמו שהרצון ואהב' היא בעצם מפני שהדבור כיסהו והעלימו בתוכו וה\"ז ממש כעיבור הולד בבטן אמו שמתכס' ונעלם בבטן ולא נראה כלל ואח\"כ יוצא לגלוי כו' שע\"י העלמו בבטן יצא בשינוי מהות כי בהיותו בבטן הי' כלול באמו ואוכל מה שאמו<sup data-n=\"2292\">3</sup> כו' וע\"ד דוגמא בנשמת אדה\"ר הכללית נאמר ויפח באפיו נשמת חיים<sup data-n=\"2293\">4</sup> הרי הי' אור נשמ' זו כלול' תחל' בהבל ורוח שבפה העליון וע\"י שנפח באפיו הוא שיצ' לגלוי בשינוי מהו' להיות נשמ' דבריא' יש מאין בגופו של אדה\"ר כו' דמאן דנפ' מתוכו נפח<sup data-n=\"2294\">5</sup> הרי הית' בבחי' עיבו' והעל' תחל' ומחמת זה יצא בהבל שנפח באפיו בבחי' יש ודבר מה בחי' נפרד לעצמו כולד הנולד מבטן כו' ועד\"ז יובן בשרש הנשמות למעלה כמו שאמרו אוצר אחד יש ששמו גוף<sup data-n=\"2295\">6</sup> ששם כל הנשמות בבחי' עיבור והעלם ויוצאים בבחי' לידה לבא בהתלבשות בגופים ואין משיח בא<sup data-n=\"2296\">7</sup> עד שיכלו כל הנשמות מן האוצר הזה כו' והענין הוא דשרש הנשמה באצי' היה במוחין דאבא שמלובשים במדות דז\"א שנקרא אדם דאצי' בבחי' דכר וכתיב ביה אור זרוע לצדיק<sup data-n=\"2297\">8</sup> עליון שנמשך אור זרוע מבחי' יסוד ז\"א בבחי' המ\"ד כו' ונקלט האור הזרוע זה במל' והוא בחי' העיבור באוצר ששמו גוף בחי' נוק' להיות שם בהעלם וכסוי גדול זמן ז' או ט' חדשים עד שיוצאת הנשמ' בדרך תולד' מאין האלקי לבחי' יש גמור כו' והיינו ע\"ד הנ\"ל בנשמת אדה\"ר בכלל וגם כמו שאנו רואים בכל נשמה אלקית בפרט שקודם שנמשכ' בעוה\"ז בגוף כמאמר ג' שותפי' הן<sup data-n=\"2298\">9</sup> אב ואם כו'<sup data-n=\"2299\">10</sup> והקב\"ה נותן בו נשמה והוא מ\"ש נשמה שנתת בי<sup data-n=\"2300\">11</sup> אתה בראת כו' היינו שהית' כלולה בבחי' עיבור במל' דעשי' שנק' אוצר וגוף בבחי' יחוד זו\"נ דעשי' ובהיות אור נשמה זרוע מבחי' יסוד ז\"א דעשי' צדיק עליון הית' בבחי' אין האלקי ממש",[["2290","1","<b>יותר משאין ערוך</b>: ראה גם מאמרי אדה\"א קונטרסים ע' רפו ואילך. לעיל סט, א."],["2291","2","<b>באורך נראה אור</b>: תהלים לו, י."],["2292","3","<b>ואוכל מה שאמו</b>: נדה ל, ב."],["2293","4","<b>ויפח באפיו נשמת חיים</b>: בראשית ב, ז."],["2294","5","<b>דמאן דנפ' מתוכו נפח</b>: מובא בשם הזהר בתניא רפ\"ב. אגה\"ת מהדו\"ק ע' תקט. אגה\"ק סט\"ו. ובשם חז\"ל במאמרי אדה\"ז אתהלך לאזניא ע' קה. ראה גם פרדס שער (עשר ולא תשע) ש\"א פ\"ה. הנסמן בלקוטי הגהות לתניא שם."],["2295","6","<b>אוצר. . ששמו גוף</b>: ראה ע\"ז ה, א וברש\"י ותוס' שם. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' עז. לקו\"ש (י\"ט כסלו) כרך ה ע' 434 בהערה. סה\"מ תקס\"ה ח\"ב ע' תשעה. מאמר ד\"ה דור לדור מכ\"ק אדה\"א (קה\"ת, תשנ\"ב) ע' 16."],["2296","7","<b>ואין משיח בא</b>: נסמן בהערה שלפנ\"ז. ראה גם מאמרי אדה\"א הנחות תקע\"ז ע' עז ואילך."],["2297","8","<b>אור זרוע לצדיק</b>: תהלים צז, יא."],["2298","9","<b>ג' שותפי' הן</b>: ראה קידושין ל, ב. נדה לא, א."],["2299","10","<b>כו'</b>: כ\"ה גם בדפו\"ר."],["2300","11","<b>נשמה שנתת בי</b>: ברכת אלקי נשמה [בדילוג]."]]],[2800530199,"ובהעלמ' בבטן מל' דעשי' אח\"כ יצא במהו' יש נפרד להתמשך בגוף גשמי כאשר גזר אומר עליה שתומשך למט' כמו שאמר הקב\"ה נותן בו נשמה אור נשמ' שכבר נברא' יש מאין ממל' דעשי' והרי כה\"ג הן נשמות דיצי' ונשמות דבריא' כמ\"ש בראתיו יצרתיו אף עשיתיו וכמ\"ש חי ה' אשר עשה לנו את הנפ' הזאת<sup data-n=\"2301\">12</sup> שהוא בחי' נפש דעשי' ממל' דעשי' וכן עד\"ז יצר נשמות דיצי' וברא נשמות דבריא' כו' וז\"ש בראת יצרת נפחת בי רק שבהתלבשות הנשמ' בגוף גשמי בעוה\"ז נקרא בשם נפיחה כמו ויפח באפיו בגופו של אדה\"ר כנ\"ל וד\"ל. וא\"כ הרי אנו רואים עכ\"פ שיוכל להיות שינוי המהות כ\"כ מן היותר רוחני ועליון שהי' הנשמ' תחל' בהתכללות דאין אלקי ממש בבחי' אור זרוע לצדיק עליון שזהו בחי' יסוד ז\"א דבריאה או דיצי' ועשי' כו' ובבוא הנשמ' האלקי' בגוף אע\"פ שיש בה מוחין ומדות בדביקות בהתפעלות אלקות בתכלית העילוי כמו נשמות גדולי הצדיקים כנשמת משה והאבות בגופים אע\"פ שהיו בחי' מרכבה ממש ונביאים אין זה ערך כלל וכלל למהות אור נשמתם כמו שהיו למעל' בשרשם בבחי' אור זרוע לצדיק ביסוד ז\"א דאצי' וכה\"ג ועד\"ז יובן בק\"ו בנשמות הקטנות ביותר בחי' נפש דעשי' שאין ערך כלל לדמות התפעלות ודביקות הנפ' הזאת שבגוף בעוה\"ז גם באוי\"ר אמיתית לגבי מהות ועצם דביקותה הנפלא' כשהית' צרור' בצרור החיים בבחי' אור זרוע כו'. וגם בהיות' כלול' בבחי' עיבור והעלם בבטן המל' דעשי' כולד בבטן אמו שכלול בה בתכלית ואוכל מה שאמו אוכלת כו' דירך אמו הוא<sup data-n=\"2302\">13</sup> וכמ\"כ הנשמ' בהיות' צרור' בהעלם במל' דעשי' הרי היא בבחי' אין האלקי בתכלית מושלל מכל בחי' יש ודבר מה כו' וכמו שאמר אליהו חי ה'<sup data-n=\"2303\">14</sup> אשר עמדתי לפניו כו' הרי מ\"ש עמדתי משמע שכבר עמד והוא טרם בא אור נשמתו בגוף בעוה\"ז ופי' עמיד' זו ל' עכב' שנתעכב שם הרב' והיינו שהי' אור נשמתו כלול' במל' דאצי' בבחי' עיבור זמן רב והוא עיבור דיב\"ח כמ\"ש בס' הקבל' להאריז\"ל<sup data-n=\"2304\">15</sup> שמשום זה שהי' נשמת אליהו בעיבור דיב\"ח ע\"כ גם גופו הי' קדו'<sup data-n=\"2305\">16</sup> ומובדל בערך משאר בנ\"א כו' והרי עכ\"פ ודאי שגם שהי' אליהו נביא קדוש אין לזה ערך ודמיון לכמו שהי' אור נשמתו דבוק' בעצם אור המל' דאצי' שאמ' ע\"ז אשר עמדתי לפניו לפניו ממש ומ\"ש ברשב\"י שאמ' בי' אחידא בי' להיטא (כמו דוד שאמר בה' תתהלל נפשי<sup data-n=\"2306\">18</sup> כמ\"כ בהלו נרו<sup data-n=\"2307\">19</sup> כו') משום דבחד קטירא אתקטר<sup data-n=\"2308\">17</sup> כו' לפי ששרש נשמתו אור הזרוע מבחי' יסוד ז\"א בנוק' כמו שהיה היחוד קודם חטא עה\"ד שלא נשתנה האור למהות יש גשמי כמו בקין כשנולד אמרה קניתי איש את ה'<sup data-n=\"2309\">20</sup> ממש וכה\"ג וכך היה במשה כשנולד שאמר ותרא אותו כי טוב<sup data-n=\"2310\">21</sup> הוא בטית רבתי שהוא מעה\"ח שלמעלה מעה\"ד כו' ורשב\"י היה ניצוץ משה<sup data-n=\"2311\">22</sup> וכך יש בכל דור יחידי סגולה אך אליהו היה גם גופו עד\"ז כמשי\"ת בע\"ה)<sup data-n=\"2312\">23</sup> (וכ\"ז בחי' יוסף שהוא צ\"ע יסוד ז\"א<sup data-n=\"2313\">24</sup> ושרש נשמת משה ביסוד אבא<sup data-n=\"2314\">25</sup> כידוע):\n<b>אך</b> הנה עדיין יש להבין מפני מה יבא שינוי המהות בנשמ' ע\"י העיבור שהוא ההעכב' בבטן המל' דאדרב' לכאור' הרי היתה שם צרור' בצרור החיים בבחי' אלקות ממש בביטול גדול והתכללות ביותר ואדרב' ודאי זה גורם בחי' העילוי ברוחניו' דאין האלקי ביותר ולמה נהפוך הוא שעי\"ז דוק' נשתנ' ממהו' למהות להיות בבחי' הישות",[["2301","12","<b>חי ה'. . הזאת</b>: נסמן לעיל סט, ב."],["2302","13","<b>דירך אמו הוא</b>: גיטין כג, ב."],["2303","14","<b>שאמר אליהו חי ה'</b>: מלכים-א יז, א [בדילוג]. יח, טו [בדילוג]. מלכים-ב ה, טז [באלישע ועד\"ז שם ג, יד]. ראה מאמרי אדה\"א הנחות תקע\"ז ע' רב. וש\"נ. שע\"ת ח\"א מו, ג. לקו\"ש (ויצא) כרך כה ע' 147 בהערה."],["2304","15","<b>אליהו. . עיבור דיב\"ח כמ\"ש בס' הקבל' להאריז\"ל</b>: ראה מאמרי אדה\"א ויקרא ח\"א ע' רסה. וש\"נ. ח\"ב ע' תקלה בשם הע\"ח. שע\"ת שם. תו\"ח תולדות קמח, ד ובהערה 53."],["2305","16","<b>גופו הי' קדו'</b>: ראה גם מאמרי אדה\"א דברים ח\"ב ע' תקנד. וש\"נ. דרושי חתונה ח\"א ע' קיד. תו\"ח ויצא קעח, סע\"ב ואילך."],["2306","18","<b>בה' תתהלל נפשי</b>: תהלים לד, ג."],["2307","19","<b>בהלו נרו</b>: איוב כט, ג."],["2308","17","<b>בי' אחידא. . דבחד קטירא אתקטר</b>: נסמן לעיל פה, ב."],["2309","20","<b>קניתי איש את ה'</b>: בראשית ד, א."],["2310","21","<b>ותרא אותו כי טוב</b>: שמות ב, ב. נסמן לעיל צה, ב."],["2311","22","<b>ורשב\"י הי' ניצוץ משה</b>: ראה מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקפז. מאמרי אדה\"א נ\"ך ע' שס. תו\"ח ויצא קעח, ג ובהנסמן בהנ\"ל."],["2312","23","<b>בע\"ה)</b>: גם בדפו\"ר לא נסמן התחלת החצע\"ג."],["2313","24","<b>יוסף. . יסוד ז\"א</b>: ראה ע\"ח (שער הצלם) שכ\"ו פ\"ג. מאמרי אדה\"א דברים ח\"ג ע' תתקעה. וש\"נ."],["2314","25","<b>משה ביסוד אבא</b>: ראה לקו\"ש (שמות) כרך ו ע' 244 ואילך."]]],[2800530200,"דבריא' בע\"ג כנ\"ל וכן מובן ממ\"ש אליהו אשר עמדתי לפניו בבחי' עיבור במל' שהי' שם בבחינת הביטול לאין האלקי בתכלית כו' הענין הוא דגם זה אמת שבבחינת העיבור שם נכלל אור הזרוע דנשמה האלקי' בבטן המל' בתכלית העילוי אבל זה עצמו גורם שבלידה יולד במהות יש ודבר מה בבחי' בריאה מוגבלת כו' ויש להקדים תחלה ענין הקליט' שהוא בש\"ע שאו' מוריד הגשם<sup data-n=\"2315\">1</sup> שהוא בחי' מ\"ד דז\"א מי החסדי' העליוני' שנקלט ברחם הנוק' כידוע שזהו פי' דעצרת ל' קליט'<sup data-n=\"2316\">2</sup> וכמו הקליט' דחטה הזרועה שנפשטת מכל גסותה וחומר' ובאה לכלל בחי' אין הרוחני דכח הצומח כו' כך אור העליון דנשמ' שנזרע מאור הזרוע לצ\"ע יסוד ז\"א כנ\"ל נקלט בבטן המל' היינו מה שיבא לכלל ביטול והתכללות למעלה באלקות שהוא בחי' המל' שהוא בשם אלקי' וידוע שזהו בחי' או\"ח ביטול היש לאין בתכלית מלמט' למעלה להפשיט מכל יש ודבר כו' אבל אור שם הוי' דז\"א הוא בחי' או\"י שהוא המשכה דבחי' אין האלקי מלמעלה למטה כמו שהוא בביטול עצמי דשם מ\"ה דחכ' שמשם מקור המשכ' מ\"ד זה כו' שהוא ממוח אבא כמו כי אתה אבינו כנ\"ל וזהו גשם נדבות דבחי' מ\"ד זה תניף אלקי'<sup data-n=\"2317\">3</sup> שם ב\"ן<sup data-n=\"2318\">4</sup> דממתיק לגבורו' דאו\"ח דמ\"ן דנוק' וזהו עיקר סיבת הקליטה דאור הזרוע דמ\"ד במ\"ן כמ\"ש אשה כי תזריע<sup data-n=\"2319\">5</sup> אשה מזרעת תחלה<sup data-n=\"2320\">6</sup> כו' וכמ\"כ בכנ\"י הוא בחי' גלוי קליטת אור האלקי בחי' האין וביטול בעצם שנמשך בכל נשמ' ונפש ורוח שהן בחי' מקבל שיש בה בחי' הביטול יש לאין בבחי' או\"ח דמ\"ן אל אישך תשוקתך<sup data-n=\"2321\">7</sup> כו' כמו ברוח תשובה ורוח אוי\"ר כו' שעול' מלמט' למעל' כו' ובחי' הקליט' היינו שנקלט ונתקשר בו בחי' שם מ\"ה ע\"י יחודו בבחי' שם ב\"ן שהוא ביטול דאו\"ח יחדיו ידובקו והיו לאחדים (וכמו\"כ מ\"ש בחד קטירא אתקטרנא שהוא בבחי' מ\"ד ומ\"ן דאו\"א שבמשה ומשיח כמשי\"ת) והוא שרש כל תולדה שנולד בציור רמ\"ח אברים כולד גשמי שאחר הקליטה היטב יבא לכלל צמיח' והתפשטות בציור אדם כמוח ולב ואיברים וכמו החטה אחר קליטתה יתלבש בה כח הצומח הרוחני להצמיחה בהתפשטות רב כו' כך אחר בחי' קליט' העליונ' הרוחנית בנשמ' מאור הזרוע כנ\"ל יתחיל לצמוח רוח האדם בציור כלים מוח ולב עד המעשה בתו\"מ בפו\"מ שהוא בחי' נו\"ה כו' וכמו ציור הנשמה כמו שהיא בגוף במוח ולב כו' בהתפעלות מוחין ומדות גשמיים כנ\"ל אע\"פ שאין לזה ערך לרוחניות הנשמה בהיות' בבחי' עיבור בבטן המל' כנ\"ל מ\"מ הרי אמר בצל' אלקים<sup data-n=\"2322\">8</sup> כו' רק שצלם אדם בעיבור הוא בבחי' הרוחניות והוא תכלית הדקות וההעלם דאין הרוחני ובבואה בבחי' לידה בגוף יש בה ציור כזה בבחי' הגשמה והיינו ענין קליטה דשמ\"ע שמזה יבא גלוי התולדה בזש\"פ בקי\"ס כמשי\"ת וד\"ל ונמצ' מובן שבכלל העיבו' יש ב' הפכי' א' בקליט' ועיבור שהו' ביטול היש בתכלית וכן בכל ט\"ח שע\"י בחי' ה\"ג דמ\"ן דנוק' יש בו בולד ביטול והתכללות בבחי' אין כמ\"ש הולד במעי אמו ראשו בין ברכיו<sup data-n=\"2323\">9</sup> שהוא תלת גו תלת<sup data-n=\"2324\">10</sup> כו' שמוחין ומדות שלו הכל באי' לכלל העלם ואין הרוחני ולא בגלוי כלל כמו שאמר שמלמדין אותו כל התורה<sup data-n=\"2325\">11</sup> שזהו ודאי בבחי' ההעלם ומקיף הרוחני כו' והב' היפך זה ממש והוא מה",[["2315","1","<b>בש\"ע שאו' מוריד הגשם</b>: משנה ריש תענית. שו\"ע אדה\"ז הל' תפלה רסקי\"ד. ראה גם סה\"מ תקע\"א כאן. מאמרי אדה\"א ויקרא כאן ע' שצא. (וראה גם) דברים ח\"ד ע' א'שנה ואילך."],["2316","2","<b>דעצרת ל' קליט'</b>: ראה פע\"ח (שער הלולב) שכ\"ט פ\"ח. מאמרי אדה\"א ויקרא כאן (ס\"ע שצ ואילך). דברים שם. הנחות תקע\"ז ע' שלט ובהנסמן בהנ\"ל."],["2317","3","<b>גשם נדבות. . תניף אלקי'</b>: תהלים סח, י."],["2318","4","<b>אלקי' שם ב\"ן</b>: נסמן לקמן קלג, ב."],["2319","5","<b>אשה כי תזריע</b>: תזריע יב, ב."],["2320","6","<b>אשה מזרעת תחלה</b>: נדה לא, א."],["2321","7","<b>אל אשך תשוקתך</b>: בראשית ג, טז."],["2322","8","<b>בצל' אלקים</b>: בראשית א, כז. נח ט, ו."],["2323","9","<b>ראשו בין ברכיו</b>: נדה ל, ב."],["2324","10","<b>תלת גו תלת</b>: נסמן לקמן קל, ב."],["2325","11","<b>שמלמדין אותו כל התורה</b>: נדה שם."]]],[2800530201,"שע\"י שאוכל מה שאמו אוכלת בט\"ח דרך טיבורו<sup data-n=\"2326\">12</sup> הפתוח כו' מזה נתגדלו ונתפשטו אברי הולד וכמו מן האודם דמ\"ן דנוק' מתהווה גידול בשר<sup data-n=\"2327\">13</sup> האברים יום יום והוא מה שנהפך לדם מן המאכל שאמו אוכלת מתגדל דם<sup data-n=\"2328\">14</sup> והבשר וגידים<sup data-n=\"2329\">15</sup> דולד וכך כל ענין העיבור שהוא רק גידולו בבחי' יש ודבר בציור רמ\"ח אברי' גשמיי' וזהו הכל דוק' מבחי' המ\"ן דנוק' שעושה בו הגשמה זו כו' והיינו דוקא ע\"י בחי' העיבור שהוא מסיבת עכיבתו בבטן בהעלם דבחי' אין הרוחני מזה דוקא יבא לכלל גידול והתפשטות בהגשמה בט\"ח עד שיולד במהות יש בפ\"ע כו' וזהו כמו דבר מהיפוכו שהעיבור בהעלם והתכללות באין הוא דוקא הגורם להיות התפשטו' ישותו בט\"ח ובלידה וכך יובן בבחי' עיבור העליון דנשמות בבטן המל' דהעכבת הנשמה בביטול לאין האלקי בבטן המל' הוא עצמו הגורם להיות מציאות התפשטות' בציור רמ\"ח אברי' בליד' כו' כמו החטה אחר קליטתה תצמיח בהתפשטות כנ\"ל וד\"ל:\n(סד) <b>ולהבין</b> זה בתוס' ביאור הנה יש להבין תחלה מה שמצינו סתירה לענין הנ\"ל דלכאור' מובן לפי הנ\"ל דשהיית הנשמה בבטן המל' עושה בה בחי' יש והרי בנשמ' אליהו מפני שנתעכב בעיבור במל' יב\"ח הי' גם בגופו בחי' הביטול לאין האלקי עד שעלה בגופו השמי'<sup data-n=\"2330\">16</sup> כמלאך כו' דמזה משמע להפך שהמל' עושה בחי' אין יותר דכל שמתעכב שם יותר יהי' בו בחי' הביטול ביותר כו' אמנם הענין הוא דשניהם אמת ויש להקדים לזה בבחינת המל' שיש בה ב' הפכים האחד בבחינת האור והכלי שבה הכל הוא בבחי' אין יותר מכל הספי' זולתה והוא להיות שהמל' ל\"ל מגרמה כלום<sup data-n=\"2331\">17</sup> שהוא כמו הדבור בצרופי אותיות שאינו מהות ומציאת ממש רק בחי' ההתגלות של כל דבר יש ודבר מה שמתגלה בדבור כמו המדות חו\"ג שהמה מהות מציאות ממש והדבור מגלה אותן וכן מהות השכל ומהות הרצון מתגלים בדבו' אבל גוף הדבור אינו בחי' יש ומהות דבר כלל ע\"כ אור המל' בבחי' האין והבטול יותר מכל האורות עליונים כו' וכידוע בדוד שהיה בבחי' המל'<sup data-n=\"2332\">18</sup> היה בו בחי' הבטול ביותר אך זהו בבחי' בטול היש לאין שהוא בטול הכלי מצד בטול האור כמו בטול החומר לצורה לפי שבאור הוא בבחי' האין ביות' וע\"כ נק' המל' דל<sup data-n=\"2333\">19</sup> כמו הדל שרוחו נשברה ועיניו מצפות לקבל כך בחי' המל' בחי' מקבל מכל האורו' עליונים כידוע וזהו ענין עליית המל' בבחי' או\"ח תמיד כמ\"ש עולת תמיד<sup data-n=\"2334\">20</sup> כו' וכמו אלקים אל דמי לך<sup data-n=\"2335\">21</sup> קארי תדיר כו' ונמצא באור וכלי יש במל' בחי' הבטול ביותר מכל הספי' ובטול הכלי שמצד עצמה הוא יותר מבטול שבה מצד בטול האור כמשל נר הדולק גם שכליון הפתיל' מצד הסתלקות האור אבל כליון זה שבפתילה יותר מכפי ערך הביטול שע\"י האור כו' כדוגמא מי שיש בגופו הכנעה וביטול בהתעוררו' תשוב' ברוח נשבר' יותר משיהי' בו הכנעה וביטול לאין האלקי ע\"י האור דנשמ' עצמה שמתעורר' כו' וד\"ל ולפעמים מצינו בהיפוך ממש בבחי' המל' שהאור והכלי שבה הוא דוקא בבחי' יש כמו בבחי' הדיבור עצמו שהרי הדיבור יש בו חומר וצור' ושניהם המה עושי' בחי' יש מורגש במציא' דוקא כי אין מהות החסד או הדין בא בגלוי",[["2326","12","<b>שאוכל. . דרך טיבורו</b>: נדה שם."],["2327","13","<b>האודם. . בשר</b>: נדה לא, א."],["2328","14","<b>שאמו. . דם</b>: שאילתות דר\"א יתרו שאילתא נו. וראה גם בשאילת שלם ובהעמק שאלה שם."],["2329","15","<b>שאמו. . וגידים</b>: נסמן לעיל פא, ב."],["2330","16","<b>שעלה בגופו השמי'</b>: ראה מלכים-ב ב, יא. מאמרי אדה\"א נ\"ך ע' רלא. קונטרסים ע' שעב ובהנסמן בהנ\"ל."],["2331","17","<b>שהמל' ל\"ל מגרמה כלום</b>: נסמן לקמן קמב, א."],["2332","18","<b>בדוד. . המל'</b>: ראה פרדס (שער ערה\"כ) שכ\"ג מערכת דוד. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתקט."],["2333","19","<b>המל' דל</b>: נסמן לעיל כד, ב."],["2334","20","<b>עולת תמיד</b>: פינחס כח, ו. ראה זהר (רע\"מ) פינחס רנו, ב. מאמרי אדה\"א דברים ח\"ד ע' א'תמז. קונטרסים ע' רפה ובהנסמן בהנ\"ל."],["2335","21","<b>אלקים אל דמי לך</b>: תהלים פג, ב. ראה זהר (היכלות) פקודי רנו, ב. תרומה קמ, רע\"א. וישלח קעח, ב. לך עז, ב. פו, ב."]]],[2800530202,"יש לדבר מה כ\"א בדיבור וכן השכל או רצון וכאשר בא דבר מלך בדיבור יבא לידי מעשה והוא עיקר המלוכה שהיא בבחי' יש ודבר (וכמו ודבר דבר<sup data-n=\"2336\">1</sup> שהמל' נק' דבר מטעם זה) וזהו הטעם מה שבעיקר השם נק' ספי' זו בשם מל' דוקא לפי שהמלוכה עיקרה בחי' יש והתנשאות על זולתו וזהו בחי' האור שבה וכ\"ש בחי' הכלי שבה שהוא התפשטות ההתנשאות להיות מלך על עם וכמ\"ש ה' מלך גאות לבש<sup data-n=\"2337\">2</sup> כו' שנק' לבוש גאות והוא התלבשות המל' בעולמות כידוע וד\"ל וצ\"ל דשניהם אמת דיש במל' מבחי' האין ומבחי' היש ב' הפכי' במקום א' כו' (וראי' לזה בכלל הוא מה שמצינו שלפעמים עולה המל' עד פנימית הכתר כמו בנעילה<sup data-n=\"2338\">3</sup> דיו\"כ כו' ולפעמים יורדת המל' עד למט' מטה בסוף העשי' וכמו החירק שנעשה חולם<sup data-n=\"2339\">4</sup> וכמ\"ש כתועפות ראם<sup data-n=\"2340\">5</sup> כו' וד\"ל) והיינו לפי ששר' המל' בקו האמצעי<sup data-n=\"2341\">6</sup> עול' עד פנימית הכתר<sup data-n=\"2342\">7</sup> דנעוץ סופן בתחלתן<sup data-n=\"2343\">8</sup> כו' דכתר מל' איהו כתר עליון<sup data-n=\"2344\">9</sup> ובכתר יש ג\"כ ב' הפכים<sup data-n=\"2345\">10</sup> אלה דפנימי' שבו עולה ונכלל בעצמות והחיצוני' נעש' ראש לנאצלים וכך הוא באור המל' פנימי' שבה עול' בבחי' או\"ח בביטול והתכללות ונק' בחי' מקבל כנ\"ל וחיצוניות שבה נעשה ראש לבי\"ע ונק' משפיע בחי' או\"י ונק' מל' מטרוניתא<sup data-n=\"2346\">11</sup> בחי' יש כו' (וכידוע בפי' אמת ואמונה דאיהו אמת ואיהי אמונה<sup data-n=\"2347\">13</sup> כל זאת ל' נוק' לקבל ואח\"כ נעשה משפיע לעולמות וזהו וקיי' עלינו<sup data-n=\"2348\">12</sup> ל' זכר ומה שהיא בחי' מקבל למעל' ממה שהיא בחי' משפי' עד\"מ התלמי' לפני רבו ושר לפני המלך שביטולו לפני רבו יותר נעל' ממה שהוא נעשה ראש אח\"כ כו' וכך הוא באור הכת' דמה שאור צח אוכם<sup data-n=\"2349\">14</sup> לגבי עה\"ע יותר גבוה ממה שהוא ראש לנאצלי' כו') וזהו אני ראשון בחי' הכתר ואני אחרון<sup data-n=\"2350\">15</sup> בחי' המל' דסופן כתחלתן ותחלתן כסופן כו' ובזה יתורץ מה שנמצא ב' הפכי' במל' דוקא ולא בשאר ספי' זולתה דשניהם אמת ואינם סותרים זא\"ז כלל וד\"ל אך הנה עדיין אין בזה מתישב לנכון ענין הנ\"ל מה שהמל' עוש' בחי' יש בציור הולד באברים ומצינו היפוך זה בנשמת אליהו כנ\"ל דודאי א\"א לחלק ולומר דמצד בחי' האור דמל' שהוא בבחי' האין יותר ע\"כ הי' נשמת אליהו בביטול גדול ומצד בחי' הכלי שבה נהפוך הוא שעוש' בחי' יש כמו לעשות הולד בהגשמ' כו' שהרי מבואר למעלה בב' הפכים שבמל' אין ויש שהוא בין באור בין בכלי ואדרבה בכלי יש יותר ביטול היש כו' ואם מפני שדרך כלל עכ\"פ יש במל' ב' הפכים מבחי' אין ומבחי' יש ושניהם אמת כנ\"ל שבזה לא יתורץ על נשמת אליהו שהי' בבחי' האין וביטול ביותר משאר הצדיקים מאחר שענין הקליטה דאור הזרוע כו' הוא באמצעות הכלי דנוק' דוקא והוא בית הרחם שקולט הטפה כו' וכל שמתעכב הולד בבטן יותר יותר יש בו הביטול וכל שאינו מתעכב ט\"ח נקרא נפל כמו ענין הנפילים היו בארץ<sup data-n=\"2351\">16</sup> כו' (ומבואר במקום אחר שהנפילים הן מבחינת פסולת מ\"ד<sup data-n=\"2352\">17</sup> שפולטת הנוק' אבל בני האלקים הן אשר נשלמו בעיבור ט\"ח שלימים כו') הרי אין זה רק כאשר יש במל' מבחי' האין בכלי יותר מבאור אבל בהיות בחי' ההיפוך במל' שהיא בבחי' יש כנ\"ל הרי בכלי שבה הוא עיקר הישו' היפך האין כהתלבשות המל' בעולמות כנ\"ל א\"כ הי' צ\"ל להיפך שכל שמתעכב יותר בקליטה ועיבור יהיה בו ההגשמ' והישות יותר ובנשמת אליהו היה להיפוך",[["2336","1","<b>ודבר דבר</b>: ישעי' נח, יג."],["2337","2","<b>ה' מלך גאות לבש</b>: תהלים צג, א."],["2338","3","<b>המל'. . הכתר. . בנעילה</b>: ראה גם לקמן קמג, ב ובהנסמן במ\"מ לשם."],["2339","4","<b>המל'. . החירק. . חולם</b>: ראה לעיל כד, ב ובהנסמן לשם."],["2340","5","<b>כתועפות ראם</b>: בלק כד, ח. ראה גם לעיל שם ובהנסמן לשם בהערה ותרם."],["2341","6","<b>המל' בקו האמצעי</b>: נסמן לעיל שם."],["2342","7","<b>בקו האמצעי. . הכתר</b>: נסמן לקמן קכה, א."],["2343","8","<b>דנעוץ סופן בתחלתן</b>: ראה ס\"י פ\"א מ\"ז."],["2344","9","<b>דכתר מל'. . עליון</b>: נסמן לעיל כד, ב."],["2345","10","<b>ובכתר. . ב' הפכים</b>: ראה גם ע\"ח (שער דרושי אבי\"ע) שמ\"ב פ\"א."],["2346","11","<b>מל' מטרוניתא</b>: ראה תניא רפנ\"ב. אגה\"ק סכ\"ה (קלט, א). הנסמן במ\"מ ללקו\"ת שה\"ש יח, ב."],["2347","13","<b>דאיהו אמת ואיהי אמונה</b>: ראה זהר בלק קצח, ב."],["2348","12","<b>אמת ואמונה. . וקיי' עלינו</b>: תפלת ערבית. ראה מאמרי אדה\"א נ\"ך ע' כג. וש\"נ."],["2349","14","<b>שאור צח אוכם</b>: נסמן לעיל עז, א."],["2350","15","<b>אני ראשון. . ואני אחרון</b>: ישעי' מד, ו."],["2351","16","<b>הנפילים היו בארץ</b>: בראשית ו, ד."],["2352","17","<b>שהנפילים. . פסולת מ\"ד</b>: ראה גם לעיל פב, א. מאמרי אדה\"ז אתהלך לאזניא ע' צח. תקס\"ה ח\"ב ע' תשנו ואילך. תקע\"א כאן. שע\"ת ח\"א מו, ג. תו\"ח בראשית כו, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תקלה וע' תקסב. דברים ח\"ד ע' א'תקח. קונטרסים ע' רלד."]]],[2800530203,"שהי' בתכלית הביטול ולא עוד אלא שגם גופו החומרי הי' בבחי' הביטול לאין כמלאך וגופו ודאי מבחי' המ\"ן דנוק' שעושה ההגשמה באברי הולד ועכ\"ז הי' גופו טס באויר גם בעוה\"ז כמ\"ש עובדי' רוח ה' ישאך<sup data-n=\"2353\">18</sup> כו' כמאמר מיכאל בפריח' אחת שט העולם כולו וגבריאל בב' עד אליהו בארבע<sup data-n=\"2354\">19</sup> כו' וזה מעל' ומדריג' שלא הי' בגופו של משה וגם לא בגופו של אדה\"ר קודם החטא שהי' עקבו מכה' גלגל חמה<sup data-n=\"2355\">20</sup> מ\"מ לא הי' גופו פורח כמלאך כו' (ואמנם באמת ידוע<sup data-n=\"2356\">21</sup> ששרש נשמת אליהו בבחי' ב\"ן שהוא רק בחי' ביטול היש לאין לבד ע\"כ דוקא בבחי' ביטול דגופו היה בו יותר גם מבמשה שגם שהי' נשמת משה גבוה ממנו כי משה בשרשו בשם מ\"ה אי\"ן העצמי והוא בבחי' או\"י היפך או\"ח דב\"ן דאליהו גי' ב\"ן<sup data-n=\"2357\">22</sup> אבל בגוף היה אליהו למעל' מבחי' משה כו' וד\"ל) אמנם באמת הנה עיקר ענין ב' הפכים הנ\"ל במל' היינו להיות שהן ענין אחד ממש והא בהא תליא והוא בחי' ה\"ג דנוק' כידוע שיש ב' מיני ה\"ג ברחם הנוק' הא' לצורך עצמה והוא בבחי' העלאת מ\"ן דאו\"ח כמו ואל אישך תשוקתך הרי התשוק' זו ברשפי אש להכלל בדכורא היינו מבחי' ה\"ג שבה שעולים למעל' וכמו אלקים אל דמי לך כנ\"ל וז\"ש אש תמיד תוקד<sup data-n=\"2358\">23</sup> על המזבח וכן למען יזמרך כבוד<sup data-n=\"2359\">24</sup> ולא ידום ונק' אשה אש ה'<sup data-n=\"2360\">25</sup> כו' ובכנ\"י היינו מה שיש בכל אחד התעוררות תשוק' לידבק באלקות בלי הפסק ושינוי בכל אחד לפי ערכו מצד שרש הנשמות במל' בבחי' מ\"ן שבה וכידוע בפי' עלי באר<sup data-n=\"2361\">26</sup> שכל הנשמות עולין בהעלאות מ\"ן ביסוד דנוק' שנק' בארה של מרים<sup data-n=\"2362\">27</sup> כו' וזהו באר בידך אפקיד רוחי<sup data-n=\"2363\">28</sup> כו' וכל הנשמות צרורים שם בצרור החיים וכל שנקלט שם יותר יותר יש בנשמ' זו תוקף העלי' והביטול בתכלית (והוא נקוד' ההתקשרות ברוב עוז ותעצומות וכמו שאמר רשב\"י בחד קטירא אתקטרנא כו' אף שהי' מבחי' מ\"ד דדכורא כמ\"ש מאן פני האדון כו' דכר מן<sup data-n=\"2364\">29</sup> כו' אבל הי' נקלט ומקושר ביותר) (וכמו ביוסף דכתיב אנחנו מאלמים אלומים כו' קמה אלומתי<sup data-n=\"2365\">30</sup> כו' שהעלאות מ\"ן שלו הי' מן העומק ביותר היינו ביטול העצמות ביותר כו' כמשל הזורק בחץ ע\"י קלע כל שמחזיר את ידו למט' יותר יותר יזרוק לגוב' כו') ומזה יבא ג\"כ ענין הביטול והתכללות לאין שבולד בט\"ח כנ\"ל שהוא דוקא מבחי' הגבורות דמ\"ן כו' כנ\"ל וד\"ל והב' בחי' ה\"ג שבנוק' לצורך השפעה לעולמות שאז נק' המל' חסד ח\"ס דלי\"ת<sup data-n=\"2366\">31</sup> וכמ\"ש והוכן בחסד כסא<sup data-n=\"2367\">32</sup> כי אמרתי עולם חסד יבנ'<sup data-n=\"2368\">33</sup> וכה\"ג שהרי מאחר שהמל' מחי' ומהו' את כולם מאין ליש בהכרח שיש בה מבחי' החסדים עליונים שנק' מים היפך הגבו' דאו\"ח ממש וכמ\"כ מזה יבא גידול והתפשטות הולד שזהו דוקא מבחי' החסדים שמתפשטים כידוע וזה פלא לכאורה מאין יבא בחי' החסדים האלה במל' אם בעצם הרי אין בה רק בחי' הגבו' דמ\"ן כנ\"ל אך הענין הוא כידוע בפי' אין<sup data-n=\"2369\">34</sup> צור כאלקינו<sup data-n=\"2370\">35</sup> ובענין ההופכי הצור אגם מים<sup data-n=\"2371\">36</sup> דגבורות דנוק' בתשוקה כנ\"ל נהפכו לחסדים והיינו מחסדים דמ\"ד דדכורא הוא שממתיק לגבורות דמ\"ן דנוק' עד שנהפכו הגבו' עצמן לחסדים והוא ההופכי הצור דגבורות לאגם מים דחסדים כו' ומזה בא סיבת הגדלת והתפשטות האברים בט\"ח כמ\"ש בזהר בלק<sup data-n=\"2372\">37</sup> ע\"פ מראש צורים כו' מסטרא דאימא אתמתח כו' וד\"ל (וכמ\"ש במ\"א<sup data-n=\"2373\">38</sup> שזהו כמו מים ששותה אחר",[["2353","18","<b>רוח ה' ישאך</b>: מלכים-א יח, יב [ושם: ורוח]."],["2354","19","<b>מיכאל. . אליהו בארבע</b>: ראה ברכות ד, ב."],["2355","20","<b>עקבו מכה' גלגל חמה</b>: ראה ויק\"ר פ\"כ, ב. זהר (רע\"מ) קדושים פג, ריש ע\"ב. מאמרי אדה\"א ויקרא ח\"ב ע' תרפו. וש\"נ. תו\"ח בראשית לב, סע\"א ואילך ובהערה 15."],["2356","21","<b>ואמנם באמת ידוע</b>: ראה הנסמן בהערה ד\"ה גופו הי' קדו' לעיל צח, ב."],["2357","22","<b>דאליהו גי' ב\"ן</b>: ראה פע\"ח (שער הק\"ש) ש\"ח פ\"ח. מאמרי אדה\"א ויקרא ח\"ב ע' תקלז. וש\"נ. תו\"ח ויצא קעח, ג ובהערה 33."],["2358","23","<b>אש תמיד תוקד</b>: צו ו, ו."],["2359","24","<b>למען יזמרך כבוד</b>: תהלים ל, יג."],["2360","25","<b>אשה אש ה'</b>: ראה זהר בראשית מח, ב. ביאוה\"ז נח ז, ב."],["2361","26","<b>עלי באר</b>: חוקת כא, יז. ראה גם לעיל פב, א."],["2362","27","<b>בארה של מרים</b>: ראה גם מאמרי אדה\"א דברים ח\"ב ע' תעא. אמ\"ב שער הק\"ש לב, ב. לעיל פב, א."],["2363","28","<b>באר בידך אפקיד רוחי</b>: נסמן לעיל פב, א."],["2364","29","<b>מאן פני האדון. . דכר מן</b>: זהר בא לח, א. תשא לד, כג. ראה גם סה\"מ תקס\"ד ע' קו."],["2365","30","<b>ביוסף. . קמה אלומתי</b>: וישב לז, ז."],["2366","31","<b>חסד ח\"ס דלי\"ת</b>: ראה גם לקמן קמב, א ובהנסמן במ\"מ לשם."],["2367","32","<b>והוכן בחסד כסא</b>: ישעי' טז, ה."],["2368","33","<b>כי אמרתי עולם חסד יבנ'</b>: תהלים פט, ג."],["2369","34","<b>אין</b>: כ\"ה בדפו\"ר. ובמהדורת לעמבערג: כי אין."],["2370","35","<b>אין צור כאלקינו</b>: שמואל-א ב, ב [ושם: ואין ? ראה מאמרי אדה\"א ויקרא ח\"א ע' כט. וש\"נ. נ\"ך ע' כד. וש\"נ]. ראה ביאוה\"ז בלק קג, ג."],["2371","36","<b>ההופכי הצור אגם מים</b>: תהלים קיד, ח. נסמן לעיל פב, א."],["2372","37","<b>בזהר בלק</b>: רג, ב. בלק כג, ט."],["2373","38","<b>וכמ\"ש במ\"א. . אכל ולא שתה</b>: שבת מא, א. ראה מאמרי אדה\"א בראשית ע' קטו. שמות ח\"א ע' קפב. ויקרא ח\"א ע' קלט ובהנסמן בהנ\"ל. תו\"ח תולדות קמח, ג."]]],[2800530204,"האכיל' שהמאכל נהפך לדם ומים ממשיכים כל חיות הדם הזה לכל אבר להגדיל חיותו ע\"כ אכל ולא שתה אכילתו דם לבד כו' כך מבחי' מ\"ד לבד לא הי' נמשך ומתפשט אברי הולד רק ע\"י המ\"ן שנהפך לחסדים להמשיך חיות כל אבר בריבוי התפשטות) והיינו למעלה בחי' ה\"ג של צורך העולמות להחיות רוח שפלים<sup data-n=\"2374\">1</sup> בחסדים דוקא כנ\"ל וד\"ל ונמצא דשניהם אמת דה\"ג עצמן שהן בבחי' או\"ח אל אישך כו' הוא שנהפכו למי חסדים להיות ראש ומשפיע לבי\"ע וזהו ענין הנ\"ל בב' הפכים דמל' דאין ויש הנ\"ל שהוא בחי' מקבל תחל' ואח\"כ משפיע כו' וד\"ל ובזה יתורץ ענין הביטול דאליהו גם בגופו כמו בנשמתו דאע\"פ שהגבו' דאו\"ח ביב\"ח יותר נמשך בהתהפכות לחסדים בבחי' יש יותר אבל בזה נבדל נשמת אליהו שהי' גם בבחי' היריד' דאו\"ח בהתפשטות ליש יותר גם כן בבחינת הביטול הגדול בלי שינוי כלל והוא להיותו מאותן נשמות שיהיו לע\"ל בימי משיח שלא הי' כמוהם כלל דהיינו שגם בבחי' היש שלהם הם כמו בבחי' האין ממש וכמשי\"ת ב\"ה וכמו כן נשמת חנוך דכתיב ביה ויתהלך חנוך<sup data-n=\"2375\">2</sup> את האלקים כו' והוא פנחס והוא אליהו<sup data-n=\"2376\">3</sup> ודוגמא לזה הי' בלידת קין שנאמר בו קניתי איש את ה' ממש אך הי' בו נפיל' והוא כל בחי' התוהו שצריך תיקון כידוע משא\"כ באליהו<sup data-n=\"2377\">4</sup> וחנוך<sup data-n=\"2378\">5</sup> וד\"ל:\n(סה) <b>ומעתה</b> יובן בתוס' ביאור ענין הנ\"ל בבחי' העיבור וקליטה איך שדוקא ע\"י הביטול והתכללות דבחי' אין הוא עצמו הגורם להיות אח\"כ בחי' התפשטות והגשמה דציור הולד והא בהא תליא דוקא דהיינו כמו ענין הנ\"ל בב' הפכי' דמל' אין ויש דהא בהא תליא דוקא וכמו שהה\"ג בהסתלקות הן עצמן שנהפכו לחסדים בבחי' יש (וכדוגמא זו היה בתיבת נח<sup data-n=\"2379\">6</sup> שההעלם ואין דתיבה עשה היש הגלוי כו') ויובן זה עוד ע\"פ המבואר במ\"א ע\"פ בצאת ישראל ממצרים<sup data-n=\"2380\">7</sup> ממיצר הגרון כו' מצר מ\"י כו' דהנה ישראל עלה במח' שבראש שהן מוחין דחב\"ד שכלולים שם כל ס\"ר נש\"י בס\"ר אותיות דאבא כנ\"ל וזה היה דורו של משה ת\"ר אלף בבחי' חכ' שבראש בציור קומת אדם כו' ומבואר במ\"א בענין יצ\"מ ומסעות שבמדבר עד ביאתם לארץ ישראל ארץ טובה ורחבה כו' שיש בזה ג' יציאות ובקיעות מן המיצר שנק' בקיעת הפרסא הא' בחי' בקיעת הפרסא שבין אור הכתר לחכמה שבראש שזהו הנק' קרומא דאוירא<sup data-n=\"2381\">8</sup> כו' והוא מ\"ש והחכמה מאין תמצא<sup data-n=\"2382\">9</sup> מאין דכתר שבא בדילוג המדריגה בשינוי המהות כמו מאין ליש ע\"י מסך דמל' כו' ועד\"מ המשכיל שכל חדש שתחלה מתעלם ומתעכב בכח השכל ההיולי בבחי' העלם ואי\"ן והעמדה והעכבה זו הוא ע\"י בחי' הקרומא כו' ואח\"כ בוקע הקרום ואז נמשך התהוות השכל החדש ליש ודבר מה כאו' הנולד ע\"י מסך שנק' אור של תולדה<sup data-n=\"2383\">10</sup> הארה דהארה כו' כך ע\"י העיכוב דשכל בכח המשכיל שלמעלה מן השכל הוא כמו עיבור הולד בבטן כו' הוא הגורם שבוקע ונולד אור החכמה מאין ליש ואם לא העיכוב והתכללות זו לא הי' בא אור החכמה בשינוי מהות יש וראיה לזה מסייג לחכמה שתיקה<sup data-n=\"2384\">11</sup> שע\"י השתיקה דוקא עולה השכל בכח השכל בבחי' עיבור והעלם והוא הגורם יריד' אור שכל חדש מכח השכל כמו שתיק רב<sup data-n=\"2385\">12</sup> כו' וכך הי' ביצ\"מ שהי' הגלות בבחי' עיבור כו' דכתיב אנכי ארד עמך<sup data-n=\"2386\">13</sup> כו'",[["2374","1","<b>להחיות רוח שפלים</b>: ישעי' נז, טו."],["2375","2","<b>ויתהלך חנוך</b>: בראשית ה, כב. כד."],["2376","3","<b>והוא פנחס והוא אליהו</b>: ראה ת\"י וארא ו, יח. מאמרי אדה\"א דברים ח\"ב ע' תנ. וש\"נ. לקו\"ש פינחס (כרך יח) ע' 346. וש\"נ. (כרך כח) ע' 343."],["2377","4","<b>התהו. . באליהו</b>: ראה גם תו\"ח מקץ ריז, ב."],["2378","5","<b>תהו. . וחנוך</b>: ראה תו\"א שמות נא, ג. מאמרי אדה\"א נ\"ך ע' תסט. וש\"נ."],["2379","6","<b>בתיבת נח</b>: ראה גם סה\"מ תקס\"ז ע' קלה."],["2380","7","<b>בצאת ישראל ממצרים</b>: תהלים קיד, א. ראה גם מאמרי אדה\"א דברים ח\"א ע' מו ואילך. וש\"נ. הנחות תקע\"ז ע' כז ואילך."],["2381","8","<b>הפרסא. . קרומא דאוירא</b>: ראה זהר (אד\"ר) נשא קכח, ב. מאמרי אדה\"א בראשית ע' ח. וש\"נ. לקמן קכה, א."],["2382","9","<b>והחכמה מאין תמצא</b>: איוב כח, יב. ראה זהר (רע\"מ) משפטים קכא, סע\"א. מאמרי אדה\"א ויקרא ח\"ב ע' תנח. דברים ח\"ג ע' תשעט ובהנסמן בהנ\"ל. תו\"ח בראשית ז, ד ובהערה 48."],["2383","10","<b>אור של תולדה</b>: ראה מאמרי אדה\"ז על פרשיות התורה ח\"א ע' שמט ובהנסמן במ\"מ לשם."],["2384","11","<b>מסייג לחכמה שתיקה</b>: ראה גם לקמן קכח, א ובהנסמן במ\"מ לשם."],["2385","12","<b>שתיק רב</b>: ביצה ו, א. ראה גם לעיל לז, א."],["2386","13","<b>אנכי ארד עמך</b>: ויגש מו, ד."]]],[2800530205,"אנכי בחי' כתר<sup data-n=\"2387\">14</sup> ויצאו מן המיצר הזה שהוא בחי' הפרסא שבין כתר לחכמה כו' וד\"ל והב' בקיע' המיצר דגרון שנק' מיצר מ\"י כו' כנ\"ל והענין הוא דאחר גלוי אור החכמה בראש במוחין דחב\"ד מאין דכתר ליש במצי' שכל ודעת כו' כאשר נמשך אור השכל ודעת בלב א\"א להיו' ג\"כ דילוג גדול כזה ממהות למהות כמו שמן האין דכתר לחכמה הנ\"ל אם לא שיהיה תחלה בבחי' עיבור והעלם ועיכוב שנתעלמו ונתעכבו המוחין דחב\"ד והוא ע\"י מיצר הגרון כמו שאנו רואים שהשכל יסתלק מיד שיבא לכלל התפעלו' בלב והוא בהעל' ומסך המבדיל שנק' מיצר הגרון דבינ' אח\"כ בוקע ויוצא אור המוחין במדות שבלב ונעשה השכל במהות מדות כמו ע\"י מסך שנשתנה ממהות למהות וזהו פי' בצאת ישראל שהוא ישראל סבא מדות שבשכל עצמו כמו חסד ודין דחכמה<sup data-n=\"2388\">15</sup> שנובע ממקור החכמה שנק' זקן שקנה חכמה<sup data-n=\"2389\">16</sup> ויוצא ע\"י מסך דמיצר הגרון כו' להתמשך בבחי' מוחין למדות שבלב זהו יציאת יש\"ס מן המיצר דבינה אחר העיכוב והעלם ועיבור דמדות שבשכל במיצר זה כו' והיינו בקיעת פרסא הב' שבין השכל והמדות וזהו עיקר יצ\"מ לקבלת התו' שהוא להמשיך מוחין במדות וכמ\"ש ותור' שם בישראל<sup data-n=\"2390\">17</sup> כו' וזהו עיקר בחי' לידת הנשמות דישראל בקי\"ס שהן תולדות המדו' שיוכלו לקבל התורה כו' וד\"ל והג' הוא בקיעת פרסא הג' לצאת מן המיצר שבחזה שבלב אל הדבור שגם המדו' מתעלמים בהעל' ועיבור בחזה ויוצאים בבקיעה לחוץ והוא שרש הדבור עלמא דאתגליא שנעשה בשינוי המהות לגמרי כי המדות שבלב שנראין ונגלי' בדבור הן במהות נבדל ביש בפ\"ע כאור הנראה ע\"י מסך והיינו ענין המסעות שבמדבר שעי\"ז באו לא\"י ארץ טובה ורחבה שזהו הדבור בחי' המל' כאשר מתפשטת לאורך ורוחב בכל ע\"ס שבה באורות וכלים והוא תכלית השלימות משום דנעוץ תחלה דכתר בסוף כו' והוא בזמן בנין בהמ\"ק דשלמה דקיימא סיהרא<sup data-n=\"2391\">18</sup> כו' וד\"ל ואמנ' יש עוד פרסא והוא חצר הכבד שמפסיק בין הלב לאברי המזון עד הירכיי' שבמסך זה נשתנה מרוחניות החיות שבבחי' מדו' ודבור שנק' רוח ממלל'<sup data-n=\"2392\">19</sup> עד הגשמ' הקרביי' וכליות שנק' נו\"ה<sup data-n=\"2393\">20</sup> עד הירכיים שנק' תרין שוקין ג\"כ יש הפסק גדול בין הגוף לתרין ירכין כו' עד הפרק התחתון דעקבי הרגלים שהן עקבות משיחא נשמות שבדורות אלה<sup data-n=\"2394\">21</sup> שבודאי יש שינוי גדול בין חג\"ת לנו\"ה דקרביים שמבררי' השפע וכליות יועצות<sup data-n=\"2395\">22</sup> לבר מגופא כידוע שהירכין הן משמשי' וטפלי' לגוף וע\"כ נק' נו\"ה בדי ערבות<sup data-n=\"2396\">23</sup> שאין בהם טעם וריח<sup data-n=\"2397\">24</sup> ולא מראה<sup data-n=\"2398\">25</sup> דכל ג' אלה מורי' על עצם המוחין ומדות חג\"ת ובנו\"ה נפסק בחי' המהות מוחין לגמרי ומכ\"ש בפרק התחתון דעקביי' שהן נשמות השפלות ביותר דעקב דמשיח עכשיו ועכ\"ז הרי נעוץ תחלתן בסופן דוקא בסוף הכל שהוא העקב דוקא כידוע שיש כח וקיום ברגל מה שאין בראש עד שמעמיד לראש ועיקר הגבור' ברגל דוקא וזהו בצדקה תכונני<sup data-n=\"2399\">26</sup> במעשה המצות בפו\"מ בנצחון בעלמא שאין בו טעם וריח כו' אז יהיה גלוי עיקר כל השלימות דחכמ' שבראש שהי' בימי משה והוא ביאת משיח דוקא בכלות הנשמות מן האוצר ששמו גוף<sup data-n=\"2400\">27</sup> עד העקביים כו' וזהו לך ה' הנצח זה בנין בהמ\"ק<sup data-n=\"2401\">28</sup> דלע\"ל שיהיה נצחי וכן דוד מ\"י חי וקיים<sup data-n=\"2402\">29</sup> לפי שגלות דעתה הוא בירכין וכד מטי רגלין ברגלין<sup data-n=\"2403\">30</sup> היינו מ\"ש ועמדו רגליו<sup data-n=\"2404\">31</sup> ד אז יאיר מלמעלה ממקו' החכ' שבראש שהוא",[["2387","14","<b>אנכי בחי' כתר</b>: ראה זהר (רע\"מ) פינחס רנו, ב."],["2388","15","<b>ישראל סבא מדות. . דחכמה</b>: ראה גם לקמן קי, ב ובהנסמן לשם."],["2389","16","<b>זקן שקנה חכמה</b>: נסמן לקמן קלב, ב."],["2390","17","<b>ותור' שם בישראל</b>: תהלים עח, ה."],["2391","18","<b>דקיימא סיהרא</b>: ראה זהר ויצא קנ, א. ויחי רכה, ב. רמג, א. יתרו פה, א. שמיני מ, ב. תזריע מו, א. שמו\"ר פט\"ו, כו."],["2392","19","<b>רוח ממלל'</b>: ת\"א לבראשית ב, ז."],["2393","20","<b>וכליות שנק' נו\"ה</b>: נסמן לקמן קלד, א."],["2394","21","<b>עקבות משיחא נשמות שבדורות אלה</b>: ראה גם מאמרי אדה\"א דברים ח\"א ע' עו. קונטרסים ע' תיח. הנחות תקע\"ז ע' רג ובהנסמן בהנ\"ל."],["2395","22","<b>וכליות יועצת</b>: ברכות סא, א."],["2396","23","<b>נו\"ה בדי ערבות</b>: ראה לקמן קלג, ב ובהנסמן במ\"מ לשם."],["2397","24","<b>ערבות. . טעם וריח</b>: ויק\"ר פ\"ל, יב."],["2398","25","<b>ולא מראה</b>: כ\"ה גם בדפו\"ר."],["2399","26","<b>בצדקה תכונני</b>: ישעי' נד, יד."],["2400","27","<b>האוצר ששמו גוף</b>: נסמן לעיל צח, א."],["2401","28","<b>לך ה' הנצח. . בהמ\"ק</b>: דהי\"א כט, יא [ושם: ה'. ?. והנצח]. ברכות נח, סע\"א [ושם: והנצח זו ירושלים וההוד זו בית המקדש]. ראה גם מאמרי אדה\"א במדבר ח\"ה ע' א'תתעא."],["2402","29","<b>דוד מ\"י חי וקיים</b>: נסמן לעיל יא, א."],["2403","30","<b>וכד מטי רגלין ברגלין</b>: נסמן לעיל סז, ב."],["2404","31","<b>ועמדו רגליו</b>: זכרי' יד, ד."]]],[2800530206,"גלוי משיח ע\"י העברה בנהר שיוצא מעדן סתימאה כמשי\"ת שזהו למעל' מדורו של משה (והיינו מ\"ש ההרים תרקדו<sup data-n=\"2405\">1</sup> ל' להבא שהן מדות שבכתר שנק' הרי קדם<sup data-n=\"2406\">2</sup> כמשי\"ת ב\"ה) ובכ\"ז יובן בתוס' ביאור ענין הנ\"ל איך שע\"י בחי' ההעלם ועיכוב בעליון ע\"י מיצר ומסך הנק' עיבור הוא עצמו הגורם להיות בקיעת אור בשנוי המהות ביש ודבר בפ\"ע כמובן מענין ג' וד' פרסות הנ\"ל בכתר וחכמה ומדות ודבור כו' עד נו\"ה דעקביים ואשר כ\"ז רק בשביל שיהיה מציא' היש היותר אחרון דנעוץ תחלתן בסוף הכל דוק' וכמ\"ש ויהי נועם ה' עלינו<sup data-n=\"2407\">3</sup> בימי משיח משום דמעש' ידינו כוננהו דוקא כו' וכן אמר סוף דבר כו' את האלקים ירא כו' כי זה כל האדם<sup data-n=\"2408\">4</sup> וכך יובן גם בהתהוות גוף בהגשמה ע\"י עיבור והעלם דאין הוא למעליות' שאז דוקא יקרא אדם וכך הוא במצו' שנק' רמ\"ח אברים בגשמיות בזה נעוץ מתחל' כל התחלו' וכמ\"ש כי זה כל האדם דלעיל' וד\"ל:\n(סו) <b>ומעתה</b> יש להבין עיקר ענין קי\"ס שהוא בחי' הלידה דנשמות אחר בחי' העיבור והעלם בתחלה כנ\"ל (והוא מ\"ש עד יעבור אותיות עיבור<sup data-n=\"2409\">5</sup> ויש בפי' עיבור זה לשון העבר' כפשוטו שהוא הגילוי דלידה וב' פעמי' יעבור היינו ב' מיני עיבור ולידה א' במל' שנק' ים<sup data-n=\"2410\">6</sup> והוא ה\"א תתאה והב' בעיבור ולידה שבבינה שהוא נהר שיוצא מעדן דלע\"ל שע\"ז אמר יעבור סתם כמשי\"ת) והנה בחי' לידה למעלה יובן ע\"ד דוגמא מלידה הגשמית למטה שנפתח הרחם ע\"י כח גדול שנק' חבלי לידה<sup data-n=\"2411\">7</sup> כמ\"ש כמו הרה תקריב ללדת<sup data-n=\"2412\">8</sup> כו' וכדי שיפתח הרחם ע\"י החבלי' הרי ידוע שצריך לזה כח גדול דהיינו ביתר מכפי המדה דוקא וכמו וכח אין ללידה<sup data-n=\"2413\">9</sup> כו' שאם לא יתעורר בה כח ועוז רק כפי המדה לא תוכל להוליד רק בהתעוררות כח גדול למעלה מגדר כחה הראשון כו' וכך הוא למעלה כידוע בענין קול ה' יחולל אילות<sup data-n=\"2414\">10</sup> דאילה רחמה צר<sup data-n=\"2415\">11</sup> ומקשה לילד ונפתח בעזר עליון כמ\"ש בדברי רז\"ל וזהו גם בכל יולדת שמקשה לילד זהו כמו יחולל אילות יחולל לשון פתיחה וחלל כו' וזהו עיקר ענין קי\"ס ג\"כ שהוא כמו בחי' הקריעה ופתיחה ברחם הנוק' להוליד כו' והיינו בבחי' מל' שנק' ים שכלולים בה נש\"י בבחי' עיבור שיפתח לילד כו' שזה א\"א כ\"א ע\"י המשכת כח גדול ביתר מכפי מדה הראשונה כנ\"ל והיינו ע\"י המשכ' כח ועוז גדול במל' מאור היותר עליון שנמשך מעצמות המאציל שלמעלה מכפי המדה הראשונה בסדר ההשתלשלות ליתן כח ועוז במל' בשביל בחי' לידת הנשמות שיצאו מבחי' העיבור והעלם דאין לבחי' יש ומציא' בריא' בע\"ג בפ\"ע ונק' נשמות דבריאה מאין ליש כמו אתה בראת<sup data-n=\"2416\">12</sup> כו' וזאת ההארה והכח הגדול שנמשך במל' בשעת בחי' לידה היינו מבחי' הגבורות עליוני' שבקדמון לכל<sup data-n=\"2417\">13</sup> כו' והוא מ\"ש ויולך ה' את הים<sup data-n=\"2418\">14</sup> ברוח קדים עזה דוקא רוח קדים זה הוא נמשך מקדמונו ש\"ע<sup data-n=\"2419\">15</sup> קודם שנאצל עולם האצי' כו' (כידוע בענין השער הפונה קדים<sup data-n=\"2420\">16</sup> כו' וכמו ומקדם אשר<sup data-n=\"2421\">17</sup> כו') וכל ענין הרוח קדים עזה הזה הוא אשר נמשך ובא בתוקף הגבו' שבעצמות כל הלילה בבחי' המל' שנק' ים העליון",[["2405","1","<b>ההרים תרקדו</b>: תהלים קיד, ו."],["2406","2","<b>מדות שבכתר שנק' הרי קדם</b>: ראה גם מאמרי אדה\"א דברים ח\"א ע' פט. ח\"ג ע' תתקעו. תו\"ח לך צ, ד. לקמן קו, א."],["2407","3","<b>ויהי נועם ה' עלינו</b>: תהלים צ, יז [בדילוג]."],["2408","4","<b>סוף דבר. . כל האדם</b>: קהלת יב, יג."],["2409","5","<b>עד יעבור אותיות עיבור</b>: נסמן לעיל פו, ב."],["2410","6","<b>במל' שנק' ים</b>: נסמן לעיל סז, א."],["2411","7","<b>חבלי לידה</b>: ע\"פ הושע יג, יג."],["2412","8","<b>כמו הרה תקריב ללדת</b>: ישעי' כו, יז."],["2413","9","<b>וכח אין ללידה</b>: מלכים-ב יט, ג. ישעי' לז, ג."],["2414","10","<b>קול ה' יחולל אילות</b>: תהלים כט, ט."],["2415","11","<b>דאילה רחמה צר</b>: ראה ב\"ב טז, ב. זהר בשלח נב, ב. ויקהל ריט, ב. פינחס רמט, ב."],["2416","12","<b>אתה בראת</b>: ברכת אלקי נשמה."],["2417","13","<b>שבקדמון לכל</b>: נסמן לעיל נא, א."],["2418","14","<b>ויולך ה' את הים</b>: בשלח יד, כא."],["2419","15","<b>קדים. . מקדמונו ש\"ע</b>: ראה גם הנסמן לעיל נה, ב."],["2420","16","<b>השער הפונה קדים</b>: ראה יחזקאל מג, א. ד. מד, א. מו, א. ראה תו\"א ויקהל פז, ד. סידור שער הר\"ח ריב, א. לקו\"ת תצא לו, ב. ברכה צז, ב ואילך. ד\"ח שער התפלה סח, סע\"ג. פיה\"מ ספל\"ח (כב, ד). ספקכ\"ג (פ, ג). מאמרי אדה\"א נ\"ך ע' תס."],["2421","17","<b>ומקדם אשר</b>: ישעי' מו, י. ראה לעיל נה, ב. לקמן קיח, א. אמ\"ב שער הק\"ש כא, א ואילך."]]],[2800530207,"כדי לקרוע את הים שהוא בחי' הלידה כנ\"ל שיצאו נש\"י בגלוי ביבשה שנק' עלמא דאתגליא מאין ליש ממש שהן נשמות דבריאה כנ\"ל וד\"ל וזהו שאמר בזהר עמ\"ש מה תצעק אלי<sup data-n=\"2422\">18</sup> בעתיקא תליא<sup data-n=\"2423\">19</sup> פירש בפנימית ע\"י שהוא פנימית ועצמות המאציל שנק' קדמונו ש\"ע בחי' כתר הכללי דאבי\"ע שמקיף ד' עולמות בכללות ששם אצי' ועשי' שוין ממש כידוע וזהו בחי' רוח קדים עזה שמשם נמשך להיות למעלה מסדר השתלשלות דהעלם וגלוי היינו שיהפך הים ליבשה שמההעלם עצמו יבא לגלוי שנק' בקיעת וקריעת הפרסא והמסך כנ\"ל שזהו עיקר בחי' הלידה הרוחניות למעלה שיומשך מאין האלקי להיות בבחי' יש שלא ע\"י מסך המבדיל כלל שזהו אור האצי' כמו שהוא יומשך במהות בריא' בע\"ג ואע\"פ שגם לפי סדר ההשתל' נמשך מאצי' לבריא' ומבריא' ליצי' אך זהו ע\"י הבדלת המסך דוק' שנק' הארה דהאר' משא\"כ בקי\"ס שהי' הכנה למ\"ת ומצות בפו\"מ שזהו בחי' גלוי אצי' כמו שהוא בבי\"ע בכל דור ודור עד ימוה\"מ וד\"ל והנה באמת יש להבין זה הענין מדוע לא יוכל להיות התהוות הנשמו' בע\"ג שלא ע\"י קריעה ובקיעה בי\"ס אדרבה על ידי מסך ופרסא דוקא כמ\"ש באורך נראה אור<sup data-n=\"2424\">20</sup> וכברייתו של עולם<sup data-n=\"2425\">21</sup> ברישא חשוכא דוקא ואם בשביל גלוי אלקו' דאצי' ממש בנש\"י ע\"י תו\"מ ומס\"נ בק\"ש וכה\"ג למה הוצרך לקי\"ס דוק' וע\"י רוח קדים כו' והנה יש להקדים לזה ענין א' והוא עד\"מ מבשרי אחזה כו' בהיות שכל סדר מע\"ב בי' מא' ולמעלה היינו בחי' ע\"ס<sup data-n=\"2426\">22</sup> דאצי' מתחלת הרצון עד הדבור שהוא בחי' המל' כידוע זהו מובן ע\"ד דוגמ' באדם התחתון שבצלם אלקים עשהו כו' שהרצון בנפש האדם אנו רואי' שהוא בגדר המשכה והתפשטו' עכ\"פ מעצם הנפש שנק' יחידה ואע\"פ שהוא בגדר התפשטות והמשכ' מ\"מ התפשטותו בלתי מוגבלת כמו עצם הנפש ממש שהרי יכול אדם למסור כל נפשו שיהי' כרצונו כמלך שמפקיר כל עצמו כדי שישאר על נצחון שלו כמו שרצה ולפ\"ע עצם כח הנפש כך יהי' גבור' כח הרצון בהתפשטות שלו גם בלא נצחון ואמנם גם זה ידוע שהרצון יתחלף והוא תלוי בעצם הנפש שימאס ברצון כו' וה\"ז מכריח שיש מקור לרצון בעצם וגם במקור לרצון יהי' שינוי מעצם הנפש לפעמי' יומשך מקור לרצון חסד ולפעמי' להיפוכו וא\"כ מוכרח לומר שבעל הרצון מושלל גם מהיות בחי' מקור לרצון ועוד זאת גם ברצון עצמי ממש שאין שינוי במקורו כלל כרצון עצמי דאב לבן גם הוא ישונה כי עצם הנפש יחליף גם רצון פשוט מהיפוך להיפוך כאברהם שכבש רצונו העצמי לבנו יחידו ונהפך לאכזר מפני רצון קונו כו' ומכ\"ש בהארת הרצון בחכ' שזהו הנק' טעם לרצון שבודאי עצם הרצון למעל' מן השכל וטעם כי אין טעם לרצון כלל<sup data-n=\"2427\">23</sup> ומה שיש טעם לרצון אינו מהו' ועצם הרצון רק הלבש' וצמצו' עצם הרצון היינו שמסתלק ומתעל' כל מהו' ועצם הרצון כמו שהו' ומתכווץ ומתצמצ' בעצמו בדב' הטעם ההוא שיוכל לומ' מזה הטעם אני רוצ' לחס' כמו השוחד יעור<sup data-n=\"2428\">24</sup> כו' כר\"י שהביאו לו שוחד<sup data-n=\"2429\">25</sup> התחיל הרצון העצמי להתצמצ' בשכל וטעם לומ' אי בעי טעין הכי כו' וא\"כ כל עיקר הרצון שלמעלה מן הטעם נשאר בהעלם בלתי גלוי כלל רק הרצון שמלובש בשכל וטעם לבד שהו' דילוג הערך מאד מעצם מהותו כו' וכך הוא",[["2422","18","<b>מה תצעק אלי</b>: בשלח יד, טו."],["2423","19","<b>בעתיקא תליא</b>: זהר בשלח מח, א. נב, ב. ראה גם לעיל לז, א."],["2424","20","<b>באורך נראה אור</b>: תהלים לו, י."],["2425","21","<b>וכברייתו של עולם</b>: שבת עז, ב [כגי' רש\"י]."],["2426","22","<b>בי' מא'. . ע\"ס</b>: נסמן לעיל סא, א."],["2427","23","<b>אין טעם לרצון כלל</b>: נסמן לקמן קכב, א."],["2428","24","<b>השוחד יעור</b>: פ' שופטים טז, כ. ראה גם שע\"ת ח\"א ט, ג ובהנסמן במ\"מ לשם."],["2429","25","<b>כר\"י שהביא לו שוחד</b>: כתובות קה, ב. ראה גם לקמן קכז, ב."]]],[2800530208,"ממש בבעל הרצון בהיותו נבדל ומושלל גם מהיות מקור לרצון אפי' לרצון פשוט ועצמי שהרי יכול להחליפנו ג\"כ כנ\"ל וא\"כ מה שבעל הרצון בא לכלל מקור לרצון ורצון גלוי זהו צמצום והעלם כל אמיתית מהותו ורק אפס קצהו בדילוג הערך מאד הוא שבא לכלל רצון לרצון אם רצון עצמי או רצון סתם כו' וד\"ל ונמצא שבא בעל הרצון בצמצ' ושיעור ברצון והרצון בא בשיעור ומדה מצומצמת מאד בשכל וטעם לרצון כו' וכך יובן גם בירידו' אור השכל וטעם במדו' דהיינו מה שיחייב השכל יוליד התפעלות המדו' חו\"ג וכה\"ג ה\"ז ג\"כ בא ע\"י צמצום והעלם עיקר מהות השכל והטעם בעצם ורק בחי' האחרונה שבו מאיר במדו' כמו שהרצון צמצם כל כח עצמו ומהותו ורק חצוניו' שבו בא ונתלבש בשכל כנ\"ל וכך יובן ג\"כ בירידת אור המדו' שבלב באותיו' המח' שנק' הרהורי לבו דודאי כל עיקר עצם ומהות התפעלות המדות נשאר בהעל' בלב ורק אפס קצהו נמשך בהרהור ומח' וכך ממש הוא ביריד' האור דמח' בדבור דודאי א\"א כלל שיוכל עצם ומהות המח' כמו שהיא לבוא בגלוי בדבור אלא רק בשיעור ומדה מצומצמת לבד וכל עיקר עצם המח' נשאר סתום ונעלם במח' כו' וזהו שנק' הדבו' מאמ' פתוח והמחש' נק' מאמ' סתום<sup data-n=\"2430\">1</sup> ואם הי' כל עצם המח' בא לגלוי בדיבו' למה נק' המח' מאמר סתום א\"ו<sup data-n=\"2431\">2</sup> שנשאר עצם המח' סתו' לבלתי נגלה בדבו' כלל וכן במדו' שבלב נשאר שלא בא במח' כו' וכך בשכל ורצון ולמע' מן הרצון מאחר שכל עליון צמצם כח עצמו ורק אפס קצהו נמשך בתחתון שזהו הנק' השתלשלות דעו\"ע כו' כידוע וד\"ל (ונמצא מובן עוד בזה דמאחר שחיצוניו' שבעליון נעשה פנימית בתחתון הרי פנימית שבתחתון נשאר בהעלם בעליון הימנו כמו עיקר תמצית ופנימי' הדבור נשאר במח' בהעלם שהרי אנו רואים בבחי' פנימית הדבור הוא דלא קאים אדעתי' דרביה<sup data-n=\"2432\">3</sup> כו' כי א\"א להבין פנימית ותמצית הדבור להיותו נשאר בהעלם המח' בבחי' מאמר סתום וכך גם פנימית המחשבה א\"א שיתגלה באותיות המחשב' ונשאר סתום במדות שבלב כמו הרהורי לבו הנ\"ל שא\"א שיגול' במחשב' כמו שהוא בלב ע\"כ ממילא מובן שגם במחשבה והרהור הלב ודאי נשאר הפנימית דמחשב' בלב וכן במדות שבלב הפנימית ותמצית המדה שלא יכיל הלב נשאר סתום במוח הבינה והחכמ' וכך הוא גם במוחין דחו\"ב לגבי הרצון דהפנימית שבטעם ושכל נשאר בהעלם עצם הרצון שלמעלה מן הטעם לגמרי וכך הוא גם ברצון עצמו דמה שיש בו מן הפנימית ועצמות נשאר בכח ומקור הרצון שהוא בעל הרצון עצמו וזהו בחי' מח' עילאה דרצון שנשאר סתום בעצמות בעל הרצון שממנו נמשך בחי' רעוא דכ\"ר עילאין גם רצונות העצמיים כנ\"ל וד\"ל) אך הנה כאשר צריך להיות בחי' גלוי ההעלם דמח' שנק' מאמר סתום בדבור בודאי כך בא גלוי העלם המדות שבלב במח' ועד\"ז מן השכל במדו' בא גלוי העל' השכל במדו' וכן מן הרצון נמשך גלוי העל' הרצון בשכל עד בעל הרצון עצמו הוא שנמשך העל' פנימי' כח הרצון עצמו שנשא' סתו' בעצמו בא לגלוי ברצון כו' זהו למעל' מסדר השתל' דרצון ושכל ומדו' ומו\"ד הנ\"ל וד\"ל. וזהו עיק' ענין קי\"ס שנבקע בחי' ההעלם דים לגלוי דהיינו מה שנשאר סתום בתחלה במח' בבחי' עלמא דאתכסיא כנ\"ל הוא עצמו שבא להיות בבחי' גלוי דיבשה כו' וכמ\"ש",[["2430","1","<b>הדבו' מאמ' פתוח. . סתום</b>: ראה גם לעיל לב, סע\"ב. הנסמן לקמן קלט, א."],["2431","2","<b>א\"ו</b>: אלא ודאי."],["2432","3","<b>דלא קאים אדעתי' דרביה</b>: ראה ע\"ז ה, ב."]]],[2800530209,"הפך ים ליבשה כנ\"ל ובודאי עד\"ז נמשך מבחי' העלם המדות עליונות דאצי' במח' וכמ\"כ מחו\"ב דאצי' במדו' וכמ\"כ מהרצון ותענוג העליון בחו\"ב נגלה כמו שהוא ולא נשאר בהעלם וצמצום מן השכל כלל וכך גם הרצון ותענוג הבא בגלוי אחר צמצום והעלם מקו' הרצון והתענוג שנק' רצון קדום עד גם רצון הפשוט שבעצמו' ממש גם הוא בא בגלוי מבעל הרצון שבו העלם כל עצמות מקור הרצון כו' ולא נשאר הרצון פשוט בהעלם העצמות כלל וכלל וד\"ל ולפ\"ז הרי יובן מזה איך שנס דקי\"ס גדול מכל הנסים ונפלאות שביצ\"מ שהי' הכל רק בשינוי אופן ההשתלשלות דע\"ס דאבי\"ע אבל לא למעל' מכל עיקר ומקור תחל' ההשתלשלות מבעל הרצון עצמו כו' משא\"כ בקי\"ס הי' האור מעצמות המאציל כמו שהוא ממש טרם שיבא לכלל מקור לרצון פשוט ועצמי שבו בהעלם (וכמו שהי' קודם שנאצל<sup data-n=\"2433\">4</sup> כו' שהי' הוא ושמו בלבד<sup data-n=\"2434\">5</sup> היינו טרם ששיער בעצמו בכח להיות בא בפועל שזהו מהעלם וגלוי דגליף גליפו<sup data-n=\"2435\">6</sup> בטה\"ע כידוע וזהו ברוח קדים מקדמונו ש\"ע ממש וד\"ל) ולא כמו שהי' במע\"ב דכתיב יקוו המים<sup data-n=\"2436\">7</sup> מתחת השמים כו' ותראה היבשה שזהו כמשל הסתלקות עצם המחשב' ונשאר בהעל' ואז ותראה היבשה עלמא דאתגליא שהוא עולם הדבור דבשביל גלוי הדבור הוצרך להיות צמצום והעלם המח' אבל קי\"ס הי' גלוי העלם עצם המחשב' בדבור כנ\"ל שבהכרח הי' גלוי העלם העצמות עד רום המעלות והיינו גם בפנימית ועצמות התענוג והרצון הפשוט שבעצמות ממש במהו\"ע אא\"ס נתגלה כמו שהוא ולא ע\"י צמצום והעלם אור כלל וכלל ע\"כ ממילא בא בגלוי כל עצמות הרצון הקדום לפנימית התענוג ורצון דבחי' א\"א וע\"י וכמ\"כ מבחי' ע\"י וא\"א לאו\"א ומאו\"א למדות דז\"א וממדו' למח' ומן המח' בדבור דהיינו מה שיצא כל העלם עצם המחשב' לגלוי בדבור ונעש' ממא' סתום עצמו מא' פתוח וד\"ל וזהו ענין רוח קדים עזה שנמשך בתגבורת גדולה שיהי' מהעלם גלוי עד רום המעלות וזהו עיקר ענין קי\"ס שיבקע בחי' ההעלם שבעילה לעלול שלא כפי ההדרגה בהשתלשלו' דעו\"ע מאין ליש עד העצמו' ממש וד\"ל:\n(סז) <b>וזהו</b> בצאת ישראל ממצרים מצר מ\"י כו' ההרים רקדו כאלים כו' דהנה מבואר למעל' בפי' מיצר מי דגרון כו' שישראל עלה במח' הקדומה שלמעלה מן החכמ' שבראש כו' והי' בזה ג' בקיעות מלמעל' למט' דרך ג' מיני פרסא הא' בין כתר לחכמ' בכלל שנק' קרומא דאוירא כו' שהוא היציא' מן המיצר והעלם דאין דכתר שיבא לידי גלוי חכמ' כמ\"ש והחכמ' מאין כו' וזה היה דורו של משה כו' כנ\"ל והב' ממיצר הגרון דבינ' למדות שבלב שיומשכו המוחין דחו\"ב במדות כו' שזהו עיקר יצ\"מ לקבל התור' במדות כו' והג' לצאת מן המיצר דחזה הלב אל גלוי הדבור באורך ורוחב גדול שזהו כניסתם לארץ טובה ורחב' כנ\"ל אך כ\"ז הנה בא בשינוי המהות קודם הבקיעה דפרסא שהיה ע\"י צמצום והעלם המסך ופרסא שבין כתר לחכמ' ובין מוחין למדות ובין מדות לדבור אבל אחר הבקיע' דג' מיני פרסא אלה הרי יצא כל בחי' העלם שבעליון לתחתון כמו שהוא ממש עד רום המעלו' בלי העלם וצמצום כלל וכלל וא\"כ גם במקורא דכולא<sup data-n=\"2437\">8</sup> שהוא בעל הרצון שהוא מקור הראשון גם לאור הכתר",[["2433","4","<b>קודם שנאצל</b>: ראה עבודת הקדש לר\"מ בן גבאי חלק היחוד פ\"ב."],["2434","5","<b>שהי' הוא ושמו בלבד</b>: נסמן לעיל יב, א."],["2435","6","<b>ששיער בעצמו בכח. . דגליף גליפו</b>: ראה הנסמן לקמן קטז, ב. מאמרי אדה\"א נ\"ך ע' רל."],["2436","7","<b>יקוו המים</b>: בראשית א, ט."],["2437","8","<b>במקורא דכולא</b>: לשון הזהר בראשית לג, א."]]],[2800530210,"בכלל יצא מהעלם עצמותו כנ\"ל והיינו כל בחי' פנימית ועצמות הרצון והתענוג שבעצמות אא\"ס ממש כמו שהוא בא לידי גלוי בפנימית א\"ק וע\"י וא\"א עד בחי' המל' שהוא הדיבור שיצא בו כל העלם המח' כו' מאחר דנעוץ סופן בתחלתן ותחלתן בסופן וא\"כ באמת יש להבין מהו ענין יתרון מעלת העברה שניה בנהר פרת שהוא בחי' נהר היוצא מעדן סתימאה דעין לא ראתה עדיין כ\"א לימה\"מ ועוה\"ב כנ\"ל שזהו ג\"כ רק בחי' גלוי העלם העצמות ממש שנקרא סדכ\"ס דלמת\"ב כו' וכבר היה זה בקי\"ס בגלוי העלם עצם המחשב' שבדיבור שממילא ודאי היה זה ממקורא דכולא ברום המעלות שזהו בחי' רוח קדים עזה מקדמונו ש\"ע ממש והיינו הך ולמה יהי' קי\"ס כמו טפל לגבי עיקר כנ\"ל וכמ\"ש עד יעבור סתם שלמעל' הרב' מעד יעבור הוי' דקי\"ס הגם שאמר זה אלי כנ\"ל באריכות דלכאו' אין הפר' ביניהם כלל וכלל לפי המובן מכל הנ\"ל בעיקר ענין קי\"ס שאינו רק גלוי ההעלם העצמות כו' וד\"ל אך הנה מבואר למעל' בעיקר ענין בקיעת הג' פרסות הנ\"ל מדורו של משה עד דורו של משיח שהוא בא בשנוי המהות דוקא להיות בבחי' יש ודבר מה וזהו לשבח ולמעל' דוקא להיות בבחי' אדם ברמ\"ח אברים כו' וכמו דורו של משה שהיו ת\"ר אלף בבחי' חכמ' שברא' ויצאו מן המיצר והעלם דאין דכתר כו' הרי היו נשמות בגופים שזהו בבחי' יש וסיבת בחי' העיבור וההעלם תחל' הוא שגרם להיות בבחי' יש והא בהא תליא דוקא כנ\"ל וכך הוא בצאת ישראל ממיצר הגרון להיות המוחין בבחי' מדות כו' היינו שיהיו ראויים לקבלת התו' בנגלה בפו\"מ דוקא להבדיל בין טמא כו' וכמ\"כ מסעות שבמדבר הי' רק שיכנסו לא\"י לעשות תו\"מ בפו\"מ עד שהי' המל' בשלימות בע\"ס באו\"כ בזמן בהמ\"ק ראשון עד חורבן בית שני שגלות זה האחרון הוא בנו\"ה דירכיים<sup data-n=\"2438\">1</sup> עד עקבות משיחא עתה זהו כמו בחי' פרסא הד' דחצר הכבד כו' שנעוץ תחלתן בסופן דוקא והוא בבחי' נצח דעקב הרגל שמעמיד לראש כו' ואז דוקא יהי' גלוי משיח שהוא שרשו בתחלת הכל וכמ\"ש בני כו' היום ילדתיך<sup data-n=\"2439\">2</sup> כו' הרי אמר בו ג\"כ בחי' לידה כו' שזהו עד\"מ הולד הנולד שהוא במציאת יש ודבר בפ\"ע כו' והוא יהיה באמת תכלית השלימות דאדם כמ\"ש בו וגבה מאד<sup data-n=\"2440\">3</sup> כו' וזה יבא רק מסוף הכל דעכשיו שבדור האחרון שהוא נשמות שבגוף שבעקביים שלו בבחי' יש נפרד לגמרי רק בקבלת עומ\"ש במעשה לבד וכמו במצות הצדקה בפו\"מ שכוללת הכל וזהו ומעשה ידינו כו' כנ\"ל וד\"ל ומעתה יובן דרך כלל שכל עיקר ענין העברה שניה דלע\"ל בנהר פרת יהי' ג\"כ ע\"ד קי\"ס ממש שהוא בבחי' לידה כמ\"ש אני היום ילידתיך כו' אך יהי' זה במעל' ובמדריג' היותר עליון והוא בנהר שיוצא מעדן סתימא' שיבקע זה הנהר ויתגלה בו מפנימית ועצמות אא\"ס ממש שבפנימית עדן סתימא' דסדכ\"ס כו' והענין הוא ע\"ד הנ\"ל בגלוי העלם עצם המחשבה בדבור ים האחרון כך יהי' בנהר הקדמוני שהוא בחי' המחשב' עילא' סתימא' שמבואר למעל' שהמחשב' מעלי' לאור השכל העצמי כו' ודאי כך הוא עד רום המעלות גם במחשב' הקדומ' והוא גם הרצון הפשוט (דרצון נקרא מחשב'<sup data-n=\"2441\">4</sup> כידוע) שבעצמות הרי א' לית מח' ת\"ב כלל<sup data-n=\"2442\">5</sup> אפי' מח'",[["2438","1","<b>בנו\"ה דירכיים</b>: ראה ת\"ז תי\"ג (כט, א) ובהנסמן בניצוצי זהר שם."],["2439","2","<b>בני כו' היום ילדתיך</b>: תהלים ב, ז. ראה סוכה נב, א. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'תקט. תו\"ח נח נח, ב ובהערה 27."],["2440","3","<b>וגבה מאד</b>: ישעי' נב, יג."],["2441","4","<b>דרצון נק' מחשב'</b>: ראה מאמרי אדה\"א דברים ח\"ב ע' שע. וש\"נ. הנחות תקע\"ז ע' רפה וע' דש."],["2442","5","<b>לית מח' ת\"ב כלל</b>: ראה ת\"ז בהקדמה (יז, א)."]]],[2800530211,"ורצון העצמי כו' ויהי' בו ענין הקריע' ובקיע' ג\"כ כמו בקי\"ס במחשבה לדיבור היותר אחרון ואע\"פ שגם בקי\"ס הי' ההאר' מן העצמות ממש כנ\"ל ברוח קדים אבל הי' עיקר הגלוי רק בהעלם דמח' בדיבור בשביל קבלת תו\"מ בפו\"מ משא\"כ לע\"ל יהי' כמו זה בעצמות הרצון ומח' הקדומ' שיהי' בו גלוי ההעלם דמהו\"ע אא\"ס ממש ויהי' בבחי' ליד' שהוא בבחי' גלוי יש ודבר מה דוקא וכמ\"ש להנחיל אוהבי יש<sup data-n=\"2443\">6</sup> ממש אך יהי' זה בבחי' פנימית סודות התור' שזהו פנימית התענוג שבעצמות ממש שנקרא עדן סתימאה שיתגלה בבחי' יש ודבר דוקא היינו בבחי' אדם כמו עתה בקיום רמ\"ח מ\"ע בפו\"מ בנגלה כך ממש יהיה בדורו של משיח שיהי' בית קיבול לקבל אא\"ס כמו שהוא בפנימית עדן בבחי' יש ודבר דוקא וכמ\"ש אני היום ילידתיך והיינו בבחי' ליד' לנשמות חדשות<sup data-n=\"2444\">7</sup> לגמרי שלא הי' בדורו' הראשונים שמאדה\"ר ואבו' ומשה ונביאי' כו' ע\"כ ילמוד עמהם פנימית התורה בטעמי מצות כנ\"ל וכמ\"ש ישכיל עבדי<sup data-n=\"2445\">8</sup> כו' וגבה מאד ולכך יהי' קי\"ס לעתיד כמו טפל לגבי העיקר וכמ\"ש כימי צאתך מא\"מ<sup data-n=\"2446\">9</sup> אראנו נפלאות שלמעל' שיבואו למטה בבחי' יש דוקא וזהו עד יעבור סתם עם זו קנית למטה בבבחי' אדם נשמות בגופי' רק שיהיו קדושים וטהורים לגמרי וכמ\"ש ואת רוח הטומאה אעביר<sup data-n=\"2447\">10</sup> כו' וכתיב כי תהיו ארץ חפץ<sup data-n=\"2448\">11</sup> ממש כידוע וד\"ל (ובפרט אחר תחה\"מ דכתיב יקימנו ונחי' לפניו<sup data-n=\"2449\">12</sup> ממש כידוע וד\"ל):\n(סח) <b>וזהו</b> ההרים רקדו כאילים<sup data-n=\"2450\">13</sup> כו' דהנה מבואר בענין והכהו לז' נחלים ולא לי\"ב גזרים כו' לפי שלעתיד בהעברה שניה יהיה בבחי' בינה ה\"א עילא' דנש\"ב היינו ז' מדות שבשכל שנמשכים מאבא כמו התפעלות המדות בחו\"ג ב' שכליים הפכיים שמקורם בנקודת חכמה שנק' אין ונמשך לבינה בהשגה וטעם כו' אבל למעל' מאין דחכמה לא שייך שם ענין תולדות המדות מאו\"א כו' אלא המדות שברצון ותענוג כאהב' בתענוגים כו' המה נטועים בבחי' עצמיות ממש בלתי מוגבלים בשכל וטעם כלל כו' ולמעלה היינו ז' מדות דפנימית ע\"י שנחשב מעצמות המאציל כו' והיינו ז' נחלים ז' מדות שבעצמות למעלה מבחי' מ\"ה דאדם כו' וזהו מ\"ש ההרים רקדו כו' דהנה ידוע שהרים הן בחינת המדות<sup data-n=\"2451\">14</sup> עליונות דאצילות חג\"ת (וגבעו' הן נה\"י<sup data-n=\"2452\">15</sup> ) ויש ב' מיני מדות א' מדות דז\"א שמקבל מאו\"א כו' בחי' אדם (כמ\"ש מה שמו אדם קדמא' דאור אבא מה שם בנו<sup data-n=\"2453\">16</sup> בחי' מדות דז\"א) וכמו מדות שבלב שנמשכי' ממדות שבבינ' שמקורם באור אבא כנ\"ל והן אורו' מוגבלים בכלים דוקא כמו אור החסד מוגבל בכלי גם במקורו בחו\"ב יש גבול להתפשטותו כשכל המטה כלפי חסד שהוא בגדר גבול להיותו נמשך בדרך תולדה מאין דחכמ' כו' ומדות אלה נק' בזהר טורי נהורא<sup data-n=\"2454\">17</sup> כי החכמ' נקרא אור<sup data-n=\"2455\">18</sup> ומדות שנולדים מן החכמ' נק' טורי נהורא דחכמתא וטעם שנק' המדות בשם הרים דוקא ידוע לפי שההר הוא בחי' צומח שבדומם<sup data-n=\"2456\">19</sup> כי מוגבה ההר בגוב' על שטח הארץ ועול' למעל' כך המדות לגבי הדבור נקרא בחי' צומח שבדומם כי אין באותיות הדבור וגם באותיות מחשב' שום ענין",[["2443","6","<b>להנחיל אוהבי יש</b>: משלי ח, כא."],["2444","7","<b>משיח. . ליד' לנשמות חדשות</b>: ראה הנסמן לעיל ס, א."],["2445","8","<b>ישכיל עבדי</b>: ישעי' נב, יג."],["2446","9","<b>כימי צאתך מא\"מ</b>: מיכה ז, טו."],["2447","10","<b>ואת רוח הטומאה אעביר</b>: זכרי' יג, ב."],["2448","11","<b>כי תהיו ארץ חפץ</b>: מלאכי ג, יב [בדילוג]."],["2449","12","<b>יקימנו ונחי' לפניו</b>: הושע ו, ב."],["2450","13","<b>ההרים רקדו כאלים</b>: תהלים קיד, ד."],["2451","14","<b>שהרים. . המדות</b>: ראה זהר (סבא) משפטים קט, ב. בסמוך בפנים. מאמרי אדה\"א שמות ח\"ב ע' תיב. וש\"נ."],["2452","15","<b>וגבעו' הן נה\"י</b>: ראה זהר שם ובהגהות מהרח\"ו. מאמרי אדה\"א ויקרא כאן ע' שצו. לקו\"ת צו כאן טז, ד."],["2453","16","<b>מה שמו. . מה שם בנו</b>: משלי ל, ד [ושם: ומה ? נסמן לקמן קלב, ב]."],["2454","17","<b>טורי נהורא</b>: נסמן לקמן קכז, ב."],["2455","18","<b>החכמ' נקרא אור</b>: נסמן לקמן שם."],["2456","19","<b>שההר. . צומח שבדומם</b>: ראה מאמרי אדה\"א דברים ח\"ב ע' תרסד-ה. וש\"נ. שע\"ת ח\"ב ל, א. תו\"ח בראשית כ, א ובהערה 3."]]],[2800530212,"צמיחה והתפשטות יתירה מכמו שהן כאבן ועפר דומם שלא יצמח כלל כו' אבל המדות שבלב מתפשטים בגוב' ורום למעל' מן הדומם כו' וע\"כ נק' האבות הרים<sup data-n=\"2457\">1</sup> כמאמר' כאברהם שקראו הר<sup data-n=\"2458\">2</sup> מצד מדרגתו באהבה שבלב כידוע וע\"כ נק' טורי נהורא כהרים הגבוהים שנראין בים שגם בים העמוק המה נראי' מצד גובהם למעל' והיינו להיות שהמדות שרשם באור החכמ' דאין דחכמ' הוא מקורם ע\"כ הן נראים בגוב' גם בים העליון וזהו שאמר ההרים רקדו כו' והן ההרים שבים גם שהן גבוהים ביותר היה בהן בחי' הביטול בתכלית שהוא הריקוד והים הוא המחש' ראה וינוס לגמרי שנבק' לגזרי' וההרי' שהן המדות שבמחשבה רקדו כו' והרים אלה שבים שהוא במחשבה הן למעל' מהרים שעל שטח הארץ שהן מדות שבדבור בערך מעלת המחשבה על הדבור וכשהעלם המחשב' עצמה בא לגלוי כנ\"ל זהו הים ראה וינוס לגמרי שנעשה בבחי' גלוי דיבשה כנ\"ל וההרים שבים גם הם רקדו כאילי' אבל לא נסו ונתבטלו לגמרי אלא היה בהן בחי' הביטול שלא בהדרג' והוא הריקוד שהוא למע' מן הדע' והיינו שיצאו מבחי' הכלי' המוגבלי' שלה' והמדריג' הב' במדות שנקרא הרים הן הרים הגבוהים שבים היותר נעלים בגובה עד שאינן נראין בראשם כלל וכאלו עולין עד השמים ממש ונק' טורי חשוכא<sup data-n=\"2459\">3</sup> שאין אור השמש מאיר שם מצד עוצם גובהן לשמים והיינו כמו הרי אררט דכתיב ותנח התיבה<sup data-n=\"2460\">4</sup> בחדש הז' על הרי אררט שהן מדות העליונו' ביותר שלמעל' מאור החכמ' דאין אור החכמ' מגיע לשם כלל והן מדות שבפנימית הכתר כמו בפנימית הרצון התענוג העצמי כו' שאינן בבחי' תולדה כלל רק בחי' מדות עצמיות שלא יוגבלו בשכל וטעם כלל ולפעמים יהי' עליית המל' לטורי חשוכא הללו כמו בעליי' המל' בנעילה<sup data-n=\"2461\">5</sup> דיו\"כ בפנימית ע\"י כו' שז\"ש ותנח התיבה בחדש הז' בחדש תשרי<sup data-n=\"2462\">6</sup> על הרי אררט שהן ימי קדם דבחי' א\"ק<sup data-n=\"2463\">7</sup> שלמעל' גם מן גלוי האה\"ר שבתענוג ורצון כו' וד\"ל (וגם עליי' דבינ' לעתיד יהיה על הרים הגבוהים האלה שהן ז' מדות דפנימית ע\"י כנ\"ל בענין ז' נחלי' כו' וז\"ש ותנח התיב' דתיבת נח הוא בבחי' פנימית בינה<sup data-n=\"2464\">8</sup> כדוגמא דלע\"ל כידוע ומבואר במ\"א וד\"ל) (וגם לפעמים המל' עולה לשם בשביל מזון כמ\"ש בזהר דאזלת לטורי חשוכא ומשם ארחת מזונא כו' וגם איילתא<sup data-n=\"2465\">9</sup> שמקש' לילד נמשך משם כח כו' כמו בקי\"ס שנמשך רוח קדים מהרי קדם אלה) וב' מיני מדות אלה שנק' טורי נהורא וטורי חשוכא הוא ההפרש בין בחי' התקון לבחי' התהו דמדות דשם מ\"ה דחכמה שהוא בחי' התקון נק' טורי נהורא ומדות שבכתר שלמעל' מן החכמ' הן מדות דתהו נק' טורי חשוכא ע\"ש בחי' ההעלם דאור הכתר שהוא למעל' מבחי' אור דחכמ' כנ\"ל והכל ענין א' והנה בכאן מדבר במדות דתיקון דחכמ' שנק' טורי נהורא דהיינו מדות דאצי' שהאבות הן המרכב'<sup data-n=\"2466\">10</sup> לחג\"ת דאצי' כו' כידוע אך מ\"ש מה לך הים כו' ההרים תרקדו כו' מדבר במדות דבחי' התהו שגם המדות העליונות דכתר רקדו בבחי' ביטול שלא בהדרג' לפ\"ע מדרגתם בבחי' הכתר וד\"ל ולהבין זה יש להקדים תחל' ענין הריקוד הזה להיות ידוע",[["2457","1","<b>נק' האבות הרים</b>: נסמן לעיל כה, א."],["2458","2","<b>כאברהם שקראו הר</b>: ראה פסחים פח, א. מאמרי אדה\"ז תקס\"ג ח\"א ע' קכו ואילך. דרך מצותיך יט, ב. מאמרי אדה\"א דברים ח\"ב ע' תרסו. וש\"נ. דרושי חתונה ח\"א ע' רטו."],["2459","3","<b>טורי חשוכא</b>: נסמן לקמן קכז, ב."],["2460","4","<b>ותנח התיבה</b>: נח ח, ד [בדילוג]. נסמן לעיל כד, ב הערה הרי."],["2461","5","<b>בעליי' המל' בנעילה</b>: ראה גם לקמן קמג, ב ובהנסמן במ\"מ לשם."],["2462","6","<b>ותנח התיבה. . בחדש תשרי</b>: ראה גם לקמן קכז, ב ובהנסמן במ\"מ שם."],["2463","7","<b>ימי קדם דבחי' א\"ק</b>: ראה גם אמ\"ב שער הק\"ש כא, א. פיה\"מ פפ\"ז (נה, סע\"א). מאמרי אדה\"א דברים ח\"ב ע' שצ."],["2464","8","<b>דתיבת נח. . פנימית בינה</b>: ראה גם מאמרי אדה\"ז אתהלך לאזניא ע' נח. מאמרי אדה\"א בראשית ע' צה. תו\"ח נח מו, א ובהערה 5."],["2465","9","<b>דאזלת לטורי חשוכא. . איילתא</b>: ראה זהר פינחס רמט, ב."],["2466","10","<b>שהאבות הן המרכב'</b>: ראה גם לקמן קלג, ב ובהנסמן במ\"מ לשם."]]],[2800530213,"בענין עליות העולמות מידי שבת<sup data-n=\"2467\">11</sup> וחדש מג\"ע לג\"ע כו' וכעליות נשמות ומלאכי' דעשי' שעולין בכל שבת<sup data-n=\"2468\">12</sup> מג\"ע התחתון דעשי' לג\"ע העליון דיצי' וכן מיצי' לבריא' ומבריא' לאצי' וכך עד רום המעלות הכל הוא בהדרגה דוקא שהוא ע\"י בחי' ביטול והתכללות דתחתון בעליון כמו מעשי' ליצי' ומיצי' לבריא' כו' שנק' הילוך כהולך ברגל שהולך ועולה מלמט' למעל' מנמוך לגבוה בהדרג' דוקא כמ\"ש ילכו מחיל אל חיל<sup data-n=\"2469\">13</sup> כו' והיינו שהולכים הנשמות בעילוי ממדריג' למדריג' יותר עליונ' כמו נשמות שנהנין מזיו השכינ' בג\"ע דעשי' עפ\"י צמצום כלי השגתם בבינ' שבמל' דעשי' שמאיר בג\"ע הוא שעולי' להנות מזיו השכינ' שבג\"ע דיצי' בבחי' בינה שבמל' דיצי' וזהו ענין עילוי גדול כמו מנה\"י לחג\"ת ע\"ד דוגמא שכל שבעשי' שהוא השג' שכל נמוך מאד שאינו רק לענין המעש' לבד ועולה להשיג השג' עליונ' יותר והוא שכל המורכב במדות אוי\"ר שנבדל בערך הרב' יותר וכמו בהשג' האלקות שמזה יתפעל למעש' לבד להיות סומ\"ר בפ\"מ אין לו ערך להשג' אלקי' שמתפעל מזה באוי\"ר בלב וכן מהשג' זו שמלוב' באוי\"ר יעלה להשג' עליונ' יותר והוא בהשג' דמוחין חו\"ב עצמן וזהו דמיון לג' מדריגו' דנר\"ן שהן בי\"ע שכל א' נכלל בעליון הימנו שבחי' נו\"ה נכלל בחג\"ת וחג\"ת בחב\"ד מפני שיש בכלל מאתים מנה<sup data-n=\"2470\">14</sup> כו' וכמ\"כ ענין עליו' הנשמות מהשגתם בג\"ע דעשי' שעולי' להשג' האלקי' בג\"ע דיצי' במעל' עליונ' יותר והוא מוחין שבמדות ומשם להשג' עליונ' יותר והוא עד בחי' אור בינה שבמל' דאצי' עצמ' שזהו אימא דמקננא בכורסייא<sup data-n=\"2471\">15</sup> בעולם הבריא' לנשמות ומלאכים דבריא' ונמצא שנשמות ומלאכים דעשי' כאופני' עולין ועומדי' במדריג' נשמות ומלאכי' דיצי' כחיות הקדש שביצי' וחיות דיצי' עולין במדריגת שרפי' דבריא'<sup data-n=\"2472\">16</sup> וממילא מובן דנשמות ומלאכי' דבריא' עולים באצי' כו' וד\"ל אך הנה כ\"ז נק' עלי' בלשון הילוך כמ\"ש ילכו מחיל כו' שהוא הולך ועולה עפ\"י ההשג' דוקא דהיינו מהשג' להשג' יותר עליונ' אבל לעולם לא יעלה יותר מבחי' ההשג' רק שההשג' עצמ' היא בעילוי גדול והענין הוא דהשג' הראשונ' נתבטל' לגמרי ובא לכלל השגה עליונה יותר שא\"א שיבא לכלל עילוי ההשגה אם לא שיבוטל השגה הראשונה כידוע בענין העמוד<sup data-n=\"2473\">17</sup> שבג\"ע שבו עולין כו' אך גם בעלותו להשג' עליונה יותר הוא עכ\"פ בבחי' גדר וגבול השג' והיינו שבחי' הביטול שלו יותר עליון מצד השג' עליונ' יותר ע\"ד דוגמא ביטול שבא מצד השגת שכל מצומצם בעשי' לבד אין לו ערך לגבי ביטול עליון שמצד השגת שכל שבמדות אוי\"ר דודאי אין ערך להמבטל עצמו רק במעש' למבטל עצמו במדות שבלב וכמ\"כ אין ערך לביטול שבמדות לביטול שבמוחין עצמן כו' וד\"ל:\n(סט) <b>אך</b> יש עלי' והילוך שאינו בא בהדרגה עפ\"י עילוי הביטול שמן ההשגה עליונה יותר אלא הוא עלי' שלמעלה מן הדעת והשגה לגמרי כי כל ענין הילוך שבא בהדרגה היינו שהביטול והעלי' הוא ע\"פ ההשגה עכ\"פ אבל כאשר יעלה בכח שלמעלה מן ההשגה אז תקרא עלי' זו שלא בהדרגה כלל והוא הנק' ריקוד כמו ההרים רקדו כו' שבקי\"ס שזהו העלי'",[["2467","11","<b>עליות העולמות מידי שבת</b>: ראה ע\"ח (שער פנימיות וחיצוניות) ש\"מ דרוש ג. ח. טו. מאמרי אדה\"א ויקרא ח\"ב ע' תקסו וע' תשסה. נ\"ך ע' קמח ובהנסמן בהנ\"ל."],["2468","12","<b>וכעליות נשמות. . בכל שבת</b>: נסמן לעיל לד, א."],["2469","13","<b>ילכו מחיל אל חיל</b>: תהלים פד, ח."],["2470","14","<b>שיש בכלל מאתים מנה</b>: ב\"ק עד, א."],["2471","15","<b>אימא דמקננא בכורסייא</b>: נסמן לקמן קיב, ב."],["2472","16","<b>דעשי' כאופני'. . שרפי' דבריא'</b>: ראה מאמרי אדה\"א ויקרא ח\"א ע' מד. דברים ח\"ג ע' תתקמז. קונטרסים ע' תקלה. ובהנסמן בהנ\"ל."],["2473","17","<b>בענין העמוד</b>: ראה תו\"א מג\"א ק, סע\"ב. וש\"נ. מאמרי אדה\"א נ\"ך ס\"ע תעו. וש\"נ."]]],[2800530214,"שלא בהדרגה כלל וכלל וד\"ל והענין של הריקוד הוא רק שעלי' בריקוד הוא העלי' שלמע' מן הדעת וההשגה לגמרי עד\"מ הריקוד הגשמי שמרקד ברגל כאשר יגבה רגליו נזקף ראשו הגבה למעלה משיעור קומתו שזה מורה היות הביטול בכח שלמעלה מן הדעת שבראשו כמו בדוד שהיה מפזז ומכרכר<sup data-n=\"2474\">1</sup> כו' וכה\"ג והוא בבחי' ביטול כל עצמותו לגמרי שלמעלה גם מבטול הפנימי דכח מ\"ה (שהו' כמו הריקוד בשמחת בית השואבה<sup data-n=\"2475\">2</sup> כו') ולמעלה גם מבטול הרצון שבטול זה בא דרך פרט ברצון לבד אבל עצמיות הבטול היינו בבחי' יחידה שבנפשו (ודוגמא האמיתי' הוא כריקוד לפני הכלה<sup data-n=\"2476\">3</sup> כמ\"ש במ\"א) ואע\"פ שאמר ההרים רקדו כאילים שזהו כמו רקוד האיל שהוא למטה מן הדעת דכל ריקוד הבהמה וכן התינוק שקופץ ומרקד זהו רק מחמת חסרון הדעת מפני שבלא דעת הוא ע\"כ ירקד אך זהו עצמו ענין הריקוד שלמעלה מן הדעת דהיינו כאשר יגיע לכלל ביטול עצמי שלא יכילנו הדעת ה\"ז עולה למעלה מדעתו ושכלו (כמו דוד היה מפזז כו' מפני שהיה בטל במציאות ממש) (וכמו הנביאים שהיו מתבטלים ממציאותם<sup data-n=\"2477\">4</sup> בהגיע הנבואה כו') ונמצא דבטול שלמטה מן הדעת הוא ענין א' עם הבטול שלמעלה מן הדעת והא בהא תליא דמחמת שמתבטל בכח כל עצמותו שלמעלה מכלי הדעת עד שעובר על דעתו ע\"כ בא לכלל ריקוד כבהמה שלמטה מן הדעת וכריקוד בעת שמחת לבו בחתונתו וכה\"ג שמעוצם התפעלות שמחת הנפש עצמה שלמעלה מהגבלת השכל והדעת ע\"כ ירקד ברגל כתינוק קטן וכבהמה בלא דעת כלל בתנועות משונות ביותר ועד\"ז הוא מ\"ש כאן ההרים רקדו כאילים שלמטה מן הדעת מפני שהיה הבטול בכח העצמות שלמעלה מן הדעת כו' והיינו מפני שיצאו האורות מבחי' הגבלת הכלים דהיינו מכלי המוחין דחב\"ד שבמדות עליונות הנ\"ל שזהו הנק' בטול ועלי' כלפי מעלה שלא בהדרגה כלל כנ\"ל וד\"ל וזהו ענין עלי' דהרים עליונים בזמן יצ\"מ כמ\"ש בצאת ישראל ממצרים<sup data-n=\"2478\">5</sup> דוקא אז ההרים רקדו בבטול גדול שלמעלה מן הדעת בביטול עצמי שזהו ממש הביטול שלמטה מן הדעת כאילים המרקדים כו' וכמו וירקידם כמו עגל<sup data-n=\"2479\">6</sup> כו' (ודוגמא לדבר זה הוא מה שאמר דוד<sup data-n=\"2480\">7</sup> ואני בהמות<sup data-n=\"2481\">8</sup> הייתי עמך ב' בחי' בהמה א' בהמה שלמטה מן הדעת והב' בהמה רבה שלמעלה מן הדעת והיינו הך דהא בהא תליא כנ\"ל וד\"ל) וזהו בצאת ישראל ממצרים כו' ההרים רקדו בחי' טורי נהורא דבחי' התיקון שזהו שהמדות שמקבלים מן הדעת נעשו בבחי' ביטול שלמטה מן הדעת כאילים כו' וכמ\"כ בבחי' הרים העליונים שנק' הרי קדם<sup data-n=\"2482\">9</sup> והן טורי חשוכא בחי' מדות שבפנימית הכתר ג\"כ רקדו בבחי' ביטול עצמי שהוא ביטול שלמעלה מן הדעת כנ\"ל וא\"כ לכאורה היינו הך ממש מאחר שביטול שלמטה מן הדעת עם הביטול שלמעלה מן הדעת הכל א' ממש כנ\"ל אך הענין הוא דיש הפרש גדול בזה והוא דביטול דמדות דתיקון היינו שיצאו מכלל הדעת שמתפשט במדות ונעשה בביטול שלמטה מן הדעת והוא ענין היציאה דאור מן הכלי כמו האהבה שבלב",[["2474","1","<b>בדוד שהיה מפזז ומכרכר</b>: שמואל-ב ו, יד. טז."],["2475","2","<b>הריקוד בשמחת בית השואבה</b>: סוכה נא, א (במשנה)."],["2476","3","<b>כריקוד לפני הכלה</b>: ראה גם מאמרי אדה\"א דברים ח\"ג ע' א'קכב. דרושי חתונה ח\"א ע' רסב."],["2477","4","<b>הנביאים שהיו מתבטלים ממציאותם</b>: נסמן לעיל מה, א."],["2478","5","<b>בצאת ישראל ממצרים</b>: תהלים קיד, א."],["2479","6","<b>וירקידם כמו עגל</b>: תהלים כט, ו."],["2480","7","<b>שאמר דוד</b>: כ\"ה בכ\"מ ? ראה מאמרי אדה\"א ויקרא ח\"א ע' י. נ\"ך ע' תלב ובהנסמן בהנ\"ל. שע\"ת ח\"ב סח, ג. תו\"ח בראשית יב, א ובהערה 2."],["2481","8","<b>ואני בהמות</b>: תהלים עג, כב [בדילוג]. ראה תניא פמ\"ו. מאמרי אדה\"א ויקרא ח\"א ס\"ע רמב ואילך. דברים ח\"ג ע' תתצו. קונטרסים ע' תיג ובהנסמן בהנ\"ל."],["2482","9","<b>הרי קדם</b>: נסמן לעיל קב, א."]]],[2800530215,"שנק' או\"כ יצא' מהגבלתה ונעשה בלא דעת כאהבה טבעית כבהמה וכן היראה כו' אבל הביטול דמדות שבכתר היינו שיצאו מהגבלת' באור הכתר והוא למעלה מן הדעת שברצון שמטה המדות חו\"ג שברצון ותענוג שנמצא עלו המדות שבכתר בעצמות ממש והוא בחי' הביטול העצמי ממש ועכ\"ז<sup data-n=\"2483\">10</sup> ביטול שלמטה מן הדעת מגיע בביטול זה שלמעלה מן הדעת עליון שבכתר ויובן זה ע\"פ המבואר במ\"א עמ\"ש דז\"א בעתיקא עצמו אחיד<sup data-n=\"2484\">11</sup> כו' שזהו למעלה גם ממזלות דנוצר חסד שרש מוחין דאו\"א כו' דהנה ב' מיני מדות יש א' שנולדים מן השכל דוקא והוא בחי' חו\"ב שנק' או\"א המולידים המדות כנ\"ל והב' מדות טבעיים שנולדו בבטן האם והוא כמו שבטבע תולדה יאהוב הטוב וישנא הרע שזה יש גם במדות דבהמה ואנו רואים שגם מדות שנולדים מן השכל יופסקו ויבואו לכלל בחי' התפעלות טבעיות כמדות דבהמה עד שלא יעצור אותם השכל כלל ואין לזה שינוי ותמורה והפסק להיות שרש המדות טבעיות שבאו בדרך תולדה בבטן בולד כשהיה מקופל כו' בעצמות הנפש ממש שנק' יחידה והוא למעלה הרבה ממדות שבתענוג ורצון כידוע והנמשל מזה יובן למעלה שז\"ש<sup data-n=\"2485\">12</sup> דז\"א שהן המדות דאצי' שמקבלים מאו\"א שרשו בעתיקא עצמו שהוא פנימית ג\"ר דע\"י שלמעלה ממדות שבע\"י וא\"א וגם למעלה ממו\"ס שהוא בחי' הדעת שמחלק לחו\"ב להתמשך בשערות והן מזלות דנוצר חסד שממנו יונק אור אבא כו' כמו מדות דיחיד' שבנפש באדם למטה וד\"ל (וז\"ש מה תצעק אלי שהוא ז\"א בעתיק' עצמו תליא במדות שבעצמות אא\"ס שבפנימית ע\"י כו' והיינו שלא ירד האור דרך השתלשלות דכתר באו\"א אלא כמו שהוא בעצמות ממש כו') וז\"ש ואני בהמות בהמה שלמטה מן הדעת שבטבעיות שרשו בבהמה רבה שהן מדות שבעצמות שלמעלה מן הדעת דתענוג ורצון כו' עד רום המעלות וד\"ל והרי יובן מזה דבטול שלמטה מן הדעת הוא מגיע בבטול שלמעלה מן הדעת אך עכ\"ז יש הפרש בין ביטול הרים דתקון שאינו רק לצאת מהגבלת הדעת שבמדות להיות בבטול כבהמה שלמטה מן הדעת ממש (ובאמת כאשר אדם בר דעת נעשה כבהמה בלא דעת כמ\"ש ואני בהמות יותר נעלה מבטול שבתענוג ורצון שבעצם הוא למעלה מבחי' אדם כי ידוע דאדם אדמה לעליון<sup data-n=\"2486\">13</sup> כו' וד\"ל) ובהיפך<sup data-n=\"2487\">14</sup> מזה ממש יהי' במשיח דכתיב בי' ישכיל עבדי ושרשו בעצמו' אא\"ס שבמדות העצמיי' שלמעלה מבחי' אדם כמ\"ש מאד ועכ\"ז יהי' דוקא בבחי' אדם לפי שעכשיו בחי' אדם הוא בא בבחי' הגבלה דמוחין דאו\"א בז\"א בקטנות וגם א\"א הוא בבחי' צמצום מעצמות ולע\"ל יבואו כל אורות דע\"ס שבעצמות ממש בבחי' אדם שהוא בלי גבול כלל כמ\"ש בו בני כו' היום ילדתיך כמו שהוא במהו\"ע ממש וז\"ש בו וגבה מאד וע\"כ יהיה ממש בטבעית אצלו כל מה שיש למעלה באורות דקו\"ח בע\"ס דאצי' שהיו האבות ומשה מרכבה לשם רק ברוחניות ולא בגשמיות וטבעיות ממש וד\"ל) וזהו הים ראה וינוס שנתבטל ממציאותו וירד למטה להיות מן",[["2483","10","<b>ועכ\"ז</b>: תוקן ע\"פ דפו\"ר. ובמהדורת לעמבערג: ועפ\"ז."],["2484","11","<b>דז\"א בעתיקא עצמו אחיד</b>: ראה זהר (אד\"ז) האזינו רצב, א. ראה ביאוה\"ז תשא נד, ב. מאמרי אדה\"ז על מארז\"ל ע' שכג. מאמרי אדה\"א ויקרא ח\"א ע' רמא. וש\"נ. תו\"ח בראשית יא, ד ובהערה 7."],["2485","12","<b>שז\"ש</b>: אוצ\"ל: שז\"ס."],["2486","13","<b>דאדם אדמה לעליון</b>: ראה עבודת הקדש ח\"א פי\"ז ואילך. הנסמן במאמרי אדה\"א בראשית ע' קסב. דברים ח\"א ע' קכב. תו\"ח בראשית יח, ג."],["2487","14","<b>ובהיפך</b>: אוצ\"ל: (ובהיפך."]]],[2800530216,"ההעלם גלוי דיבשה כנ\"ל אבל ההרים שהן המדות רקדו למעלה בבטול שלמטה מן הדעת כאילים גם הרים דתהו עלו ורקדו בביטול שלמעלה מן הדעת מפני שבמדות שהן עצמיים לא שייך ניסה לגמרי רק שמתבטלים מגדר הגבלתם ועולין למעלה שלא בהדרגה מרגל לראש כא' כמו הריקוד כנ\"ל וכל זה שהים ראה וינוס וההרים רקדו כאילים כו' היינו כמו שמפרש הטעם מלפני אדון חולי ארץ<sup data-n=\"2488\">1</sup> מלפני אלוה יעקב דוקא והוא בהיות שנגלה בקי\"ס מאור עצמות המאציל ממש שלפניו העלם וגלוי שוין כנ\"ל ע\"כ נתבטל הים וההרים בביטול שלא בהדרגה כלל כביטול הנר בפני האבוקה שעולה ונכלל בטבע עצמית ליכלל במקורו כו' וד\"ל:\nסליק שער האמונה",[["2488","1","<b>מלפני אדון חולי ארץ</b>: תהלים קיד, ז."]]],[2800530217,"<h2>שער היחוד </h2>\nא) <b>הנה</b><sup data-n=\"2489\">1</sup> כבר מבואר באריכות בקונטרס<sup data-n=\"2490\">2</sup> מיוחד<sup data-n=\"2491\">3</sup> בפרטי אופני ההתפעלות במוח ולב ומחשבה שנולד מן ההתבוננות לפי סדר ה' מדריגות נרנח\"י כו'. ומעתה יש לבאר היטב במהות גוף ענין ההתבוננו' מה היא בעצם ובמה יתבונן. והנה מהות ההתבוננות בעצם הוא ענין ההסתכלו' החזקה בעמקות הענין ולעמוד עליו הרבה עד שיבין אותו על בוריו בכל חלקיו בפרטי פרטיות והוא בחי' פנימיות בינה הנק' בלשון הגמרא בשם עיון כמו שאמר<sup data-n=\"2492\">4</sup> במס' סוכה הא למגרס והא לעיוני<sup data-n=\"2493\">5</sup> פי' הגירסא הוא רק הבנת הדבר בהשקפ' ראשונה שהולכת ונובעת במהירות בלתי עכוב והעמדה כלל כידוע עד\"מ המביט בעינו על דבר מה ואינו מתבונן כלל על הדבר<sup data-n=\"2494\">6</sup> באיכותו ומהותו בכל חלקיו הפנימי' וחיצונים רק דרך מעביר בעלמא שבמשך זמן ודאי ישכח עליו לגמרי וגם לא יוכל לספר לזולתו רק כלליות ענין אותו הדבר שראה בהעברת העין ולא בטביעת עין כלל וכן העברת<sup data-n=\"2495\">7</sup> עין השכל באיזה סברא בהשקפה ראשונה בלתי עכוב והעמדה לעיין בו היטב ולא ידע בסברא זו לתכליתה כלל. כי הנה ג' דברים הוא שיש בכל דבר מושכל. עומק ואורך ורוחב<sup data-n=\"2496\">8</sup>. הרוחב הוא בחי' הסבר המושכל לכל צד בפרטי' הרבה כרוחב הנהר ולא דברים כהווייתן לבד כנהר קצר. ואורך הוא עוצם ירידות ההשכלה להלביש את המושכל במשלים שונים עד להביאו בהשגות התינוק קטן כו' כנהר שהולך ומתמשך לאורך (וכמ\"ש באריכות בכתבים<sup data-n=\"2497\">9</sup> בענין אורך היריעה<sup data-n=\"2498\">10</sup> כו') והעומק הוא כעומק הנהר שמשם מתרחב ובעצמו אינו רחב כלל אבל הוא עיקר עצם הנהר (הנק' שטרוים) שהוא עיקר מרוצת הילוכו ממקורו ומים שע\"ג בגובה ולצדדי העומק טפלים אליו שאינן רק בחי' התגברות התפשטותו בלבד לצדדי' ברוחב ובגובה ובאורך ההילוך כו' כך עומק המושכל הוא בחי' עצם נקודתו כמו שהוא ונק' עומק המושג שכל מה שנתפשט בהסבר ההשגה לכל צד ברוחב גדול בכמה פרטי' וכן לאורך בעוצם הירידה וגם בחי' הגובה למעלה להשכיל ממנו עוד למעלה ממנו הרבה (עד בחי' עומק רום כמו התגברות המים למעלה מעלה בזמן המבול<sup data-n=\"2499\">11</sup> שכזה יהיה לימה\"מ ברוחניות בשנת ת\"ר לחיי נח כמ\"ש בזוהר דאתפתחו מבועין דחכמתא<sup data-n=\"2500\">13</sup> כו' והיינו מעיינות תהום החכמה שיתגברו למעלה מעלה ויכסו כל ההרים<sup data-n=\"2501\">14</sup> כו' וארובות השמים נפתחו<sup data-n=\"2502\">12</sup> כו'<sup data-n=\"2503\">15</sup> להמשיך מן המים שמעל השמים הנקרא עומק רום שתלוי בעמ\"ת<sup data-n=\"2504\">16</sup> כי נעוץ תחב\"ס<sup data-n=\"2505\">17</sup> כמו העמק שאלה או הגבה למעלה<sup data-n=\"2506\">18</sup> כו' וכמ\"ש בכתבים ) הכל נמשך מעצם עומק נקודתו כמו שהוא נובע מן החכמה הנקר' אין<sup data-n=\"2507\">19</sup> וכמ\"ש ונהר יוצא מעדן<sup data-n=\"2508\">20</sup> כו' שהבינה נק' נהר והחכמ' נק' מעיין<sup data-n=\"2509\">21</sup> כידוע והוא הנק' עיון שעומד ע\"ד המושכל ומעיין בו הרבה מאד שהוא העיכוב היפך המהירו' דהיינו כדי לבא לעומקו של המושכל כמו שהוא בעצם פנימיותו ותוך תוכו דוקא כמו המסתכל על דבר מה בעינו ולא בהעבר' בעלמא אלא בפקוח וטביע' עינו בעיכוב גדול עד שיודע אותו היטב בכל חלקיו הפנימים ותוך תוכו כו' והוא הנקר' התבוננות בנו\"ן הכפול<sup data-n=\"2510\">22</sup> דוקא דהיינו שמתבונן ומעיין בו הרבה וכמו שפרש\"י בעיוני לעמוד על הדבר להבינו על בוריו<sup data-n=\"2511\">23</sup> כו'. ונמצא בחי' העיון הזה הוא רק בחי' כלי לבחי' ההעמק' דבינה עצמה כי לכאור' בחי' העיון הזה נק' העמקת הדעת בל' העולם ואינו כן דהעמקת הדעת היינו בחי' כלי לבד לבוא לעומ' של הענין ממש ולמעלה מזה הוא נק' מעמיק שמגיע למעלה גם מן החכמה עצמה שהגם שהחכמ' היא",[["2489","1","<b>הנה</b>: לפרק זה ראה מאמר ד\"ה וכה\"ע רואים בסה\"מ תרמ\"ז ע' תכה ואילך."],["2490","2","<b>בקונטרס</b>: קונטרס ההתפעלות ? נדפס במאמרי אדה\"א קונטרסים ע' נא ואילך. וראה גם שם ע' קפו ואילך."],["2491","3","<b>בקונטרס מיוחד</b>: ברוב הכת\"י [אגהוזחטיב יג]: בקונטרס במכתב מיוחד. הו: ליתא תיבת בקונטרס. ח: במכתב בקונטרס [כנראה נתחלפו התיבות]. י: בקונטרס באריכות [וכנראה שגם בכת\"י זה נתחלפו התיבות]."],["2492","4","<b>שאמר</b>: טו: שאמרו."],["2493","5","<b>במס' סוכה. . לעיוני</b>: ראה שם כח, סע\"ב."],["2494","6","<b>על הדבר</b>: טו: בהדבר."],["2495","7","<b>העברת</b>: אז: הבנת ובשאר הכת\"י כבפנים. וראה להלן ברשימות הכת\"י אודות כת\"י א."],["2496","8","<b>עומק ואורך ורוחב</b>: ראה גם סה\"מ פר\"ת ע' צט."],["2497","9","<b>בכתבים</b>: הציון לדא\"ח בשם כתבים ? מובא כמ\"פ בקונטרס זה ? ראה בסמוך בפנים. לקמן קט, ב. קי, א. קיב, א-ב."],["2498","10","<b>בענין אורך היריעה</b>: ראה ביאוה\"ז פקודי נח, סע\"ג ואילך."],["2499","11","<b>התגברות המים. . המבול</b>: נח ז, יח-כ."],["2500","13","<b>דאתפתחו מבועין דחכמתא</b>: ראה זהר וירא קיז, א. וראה גם תו\"ח נח סא, ב ובהערה 21. עט\"ר ע' נה. לקו\"ש [נח] כרך טו ע' 42."],["2501","14","<b>ויכוסו כל ההרים</b>: נח ז, יט."],["2502","12","<b>בשנת ת\"ר. . מעיינות תהום. . וארובות השמים נפתחו </b>[: גזיג: פתחו]: נח ז, יא."],["2503","15","<b>כו'</b>: בדפוס ראשון ובהכת\"י בכ\"מ בקונטרס זה כו'. אמנם במהדורת טשערנאוויץ שינה והדפיס גו' (במקום תיבת כו'). ותוקן כאן וכן להלן בכ\"מ כו' כבדפו\"ר."],["2504","16","<b>עומק רום שתלוי בעמ\"ת</b>: נסמן לעיל י, א."],["2505","17","<b>נעוץ תחב\"ס</b>: ראה ס\"י פ\"א מ\"ז."],["2506","18","<b>העמק שאלה. . למעלה</b>: ישעי' ז, יא. ראה לעיל ל, ב. מאמרי אדה\"א נ\"ך ע' קנד. וש\"נ."],["2507","19","<b>החכמה הנקר' אין</b>: ראה ת\"ז רתמ\"ב. מאמרי אדה\"א בראשית ע' ב. וש\"נ."],["2508","20","<b>ונהר יוצא מעדן</b>: בראשית ב, י."],["2509","21","<b>שהבינה נק' נהר. . מעיין</b>: ראה סידור שער בהמ\"ז קד, א. סה\"מ תקס\"ח ח\"א ע' רב. ח\"ב ס\"ע תרט ואילך. לקו\"ת שה\"ש לט, ב. לעיל צ, א ובהנסמן במ\"מ לשם."],["2510","22","<b>התבוננות בנו\"ן הכפול</b>: [אג: הכפל]: ראה גם מאמרי אדה\"א דברים ח\"ב ע' תלה."],["2511","23","<b>שפרש\"י. . על בוריו</b>: ראה רש\"י סוכה שם ד\"ה ומשנן בסוכה."]]],[2800530218,"בחי' האין ממש של המושכל קודם שבא לכלל עומק נקוד' המושג שבבינה כמעיין לגבי נהר כנ\"ל אבל בחי' העמקה בשרש של המושכל שרשה מגיע בשרש הממשיך לנביעת מעיין דחכמה כו' ונק' עמקי החכמה או תעלומות חכמ'<sup data-n=\"2512\">24</sup> כי כמו שיש עומק ואורך ורוחב בבינה שנק' יש כנ\"ל כך יש עומק ואורך ורוחב במעיין דחכמה שנק' אין ועומק המעיין היינו תחיל' שרש מחצבו בעומקו שמשם מתפשט נביעתו למעלה עד שבוקע ויוצא טיפין טיפין בגלוי מהעלמו ותכלית העלמו הוא תכלית עמקו למטה כמו מעיינות תהום נבקעו דארעא חלחולי מחלחלא<sup data-n=\"2513\">25</sup> כו' בגידין שיש להם עומק ראשון ובזה נאמר והחכמה מאין מהעלם החכמה הנק' עומק החכמ' והחכמה הוא המצאת שכל החדש שיוצא כברק כו' כידוע ומקור מחצבו בהעלם עומקו הוא עיקר עצמיות ותוך תוכו כנ\"ל בביאור ענין עומק המושג דבינה שאינ' רק העומק של ההשגה דבינה המורגש בבחי' יש בהבנת דבר מה בסברא נגלית שעומק של הסבר ההשג' הוא בחי' אין של היש דהשגה בלבד ואין לו ערך לגבי אין דחכמה טרם שבא לכלל השגה כלל גם לא בבחי' העומק שבה שהוא תמציתה ואמנם עומק המושג נק' שער הנו\"ן דבינ' גם שנמשך מאין דחכמה ליש (כמו מעיין יוצא מבית ק\"ק תחלתו כקרני חגבים<sup data-n=\"2514\">26</sup> כו' וכה\"ג) שרשו מגיע בעומק דחכמ' הנ\"ל וכנרא' בחוש שכל מעמיק רק בעומק המושג הוא ממציא למקו' ושרש המושכל להמציא בחי' חדשו' דאור החכ' בבינ' והוא הנק' מעמי' ל' מפעי' שמפעיל לעומ' דחו\"ב (ולפ\"ז מ\"ש הבן בחכ' וחכם בבינ'<sup data-n=\"2515\">27</sup> שמבואר בכתבי' דהיינו ע\"ב דס\"ג חכם בבינה<sup data-n=\"2516\">28</sup> שהוא רק להבין דבר חידוש אחר מתוך המושג דבינה שזה אינו אלא ע\"י בחי' העיון הנ\"ל שהוא המברר כל חלקיו על בוריו ונק' בינ' שבבינ' ואח\"כ יוכל להוליד ולהתחכם להמציא הבנה והשגה חדשה אבל רק בהשגה זו עצמה שנק' חכמה שבבינה אבל כתר דבינה הוא עומק המושג הנ\"ל המגיע שרשו בעומק החכמה כנ\"ל. והבן בחכמה היינו ס\"ג דע\"ב שהוא כח ההסבר בחכמ' עצמ' שיוכל להביאו בפני' מסבירות הרבה והוא למעלה מן ההשגה דבינה עדיין ומה שאמרו נבונים לא אשתכחו<sup data-n=\"2517\">29</sup> שהוא המבין דבר מתוך דבר<sup data-n=\"2518\">30</sup> דוקא היינו מצד שרש כח זה דהבן בחכמה שמגיע בעומק דחכמה הנ\"ל ע\"כ יוכל להבין דבר חכמה אחרת לגמרי מתוך דבר חכמה זאת שזהו למעלה במדריגה מן החכם דהיינו מגופה של המצאות החכמה זו מאין שאינו מבין ממנה חכמה ושכל אחר (ומ\"מ מה שבהשגה דבינה מבין השגה חדש' מתוך ההשגה זו שרשה בהבן דחכמה שמבין דבר מתוך דבר רק שזה בהעלם מקור השכל כו' וד\"ל). ונמצא סדר המדריגות כך הם בחי' עיון הנ\"ל לעמוד על בורי' כו' נק' בינה שבבינה להבחין תכלית ההבחנה בפנימיות וחיצוניו' וגם מזה יוכל להיות בחי' האורך להוריד ההשגה בלבושי' רבי' עד שתתגשם להשגו' התינוק כנ\"ל אבל לא בחי' הרוחב בהסברים שוני' לכל צד כו' ואח\"כ מבחי' חכמה שבבינה להמציא חדשות בהשגה א' כנ\"ל הוא הנק' רוחב וממנו כח דבינה שבבינ' העושה בחי' אורך אבל שיעור האורך והרוחב דחו\"ב שבבינ' הוא תלוי בבחי' עומק המושג שנק' כתר דבינה וכנרא' בחוש שלפ\"ע העומק כך יהי' ערך הרוחב והאורך בכל השגת דבר מה וד\"ל). ולפ\"ז מה שקוראי' העולם העמקת הדעת אין זה גופה של העמקה כמו עומק המושג דבינה שלזה לא יש שייכות לדעת אך הדעת הוא בחי' התקשרות<sup data-n=\"2519\">31</sup> הרגשתו<sup data-n=\"2520\">32</sup>",[["2512","24","<b>תעלומות חכמ'</b>: איוב יא, ו. ראה גם לקמן קכז, ב. תו\"ח בראשית יז, ד ובהערה 21."],["2513","25","<b>דארעא חלחולי מחלחלא</b>: חגיגה כב, א."],["2514","26","<b>מעיין. . כקרני חגבים</b>: ראה יומא עז, סע\"ב."],["2515","27","<b>הבן בחכ' וחכם בבינ'</b>: ס\"י פ\"א מ\"ד."],["2516","28","<b>חכם בבינה</b>: ראה גם סה\"מ תרמ\"ו ע' כב."],["2517","29","<b>נבונים לא אשתכחו</b>: עירובין ק, ב."],["2518","30","<b>המבין דבר מתוך דבר</b>: חגיגה יד, א. ראה גם תו\"ח לך פב, א ובהערה 5."],["2519","31","<b>הדעת. . התקשרות</b>: ראה תניא פ\"ג. פמ\"ב. מאמרי אדה\"א נ\"ך ע' צז. וש\"נ."],["2520","32","<b>הדעת. . הרגשתו</b>: ראה תניא ספמ\"ו. הנסמן במאמרי אדה\"א הנחות תקע\"ז ע' רנו."]]],[2800530219,"במושג ביותר והוא שמביא לידי בחי' העמקה במושג אחר בחי' העיון הנ\"ל שהוא רק כמו בחי' כלי לעומק ההשגה כנ\"ל. וגם בדעת יש אורך ורוחב ועומק כמו יש מי שדעתו קצרה ויש שדעתו ארוכה ויש שדעתו רחבה ולא ארוכה ודעת חזק או דעת קל כנשים<sup data-n=\"2521\">1</sup> שדעתן קלות<sup data-n=\"2522\">2</sup> הוא בלתי עומק הדעת וממילא דעתו קצרה כו' והפרש זה בין קלי הדעת לעומקי הדעת בין גדול לקטן ידוע שהתינוק שדעתו קל היינו שאין בו כח המרגיש והתקשרות כלל לדבר זה שמבין או רוצה בו רק בחיצוניות מאד ע\"כ יתפתה להיפוכו משא\"כ הגדול שדעתו עמוק' באותו דבר שמבין או רוצה בו הוא הנק' העמקת הדעת שממילא נמשך אורך הדעת ורוחב הדעת כנ\"ל בבינה וסימן להעמק' הדעת הוא אשר נראה כענין צמצום וכיווץ כלי המוח לעוצם עומק התקשרותו במושכל (בל\"א ער איז דרינן פר נומען פר קוועצט שטארק זייער ביז עס<sup data-n=\"2523\">3</sup> איז זייער מצומצם רק בתנוע' אחת<sup data-n=\"2524\">4</sup> וסקירה אחת לבד כו') שמזה דוקא בא עצם עומק השגה ע\"י העיון דבינה שהוא היפך הצמצום והכיווץ שהרי העיון דבינה גם שעומד ומעוכב בצמצום וכיווץ בתחלתו אבל מיד מתפשט לרוחב הרבה בכל פרטי חלקיו בהבחנת פרטיות הרבה כידוע משא\"כ הצמצום והכיווץ דהעמקת הדעת אדרבה הוא רק הצמצום שהוא הקיבוץ והאסיפה מכל כח שכלו להתקשר רק במושכל זה שזה היפך בחי' התפשטו' העיון בהרחבת ענין המושכל (בל\"א דער קלעפ מיט דעם אריין לייגין זיך גאר כו') ואמנם ע\"י העמקת הדעת בא לידי עמקות המושכל עד שרשו בעמקי החו\"ב (עד בחי' דעת עליון דמזווג חכמ' לבינה כמ\"ש למעלה בענין עומק המושג דבינה והיינו דדעת גנוז בפומא דאימא<sup data-n=\"2525\">5</sup> כו' וכמו שאמרו משה שהוא הדעת<sup data-n=\"2526\">6</sup> זכה לבינה<sup data-n=\"2527\">7</sup> שהוא שער הנון כי הא בהא תליא וכמה שכתוב בכתבים בכמה דוכתי וד\"ל):\n(ב) <b>והנה</b> ידוע שיש בבינה עצמה ב' מדרגות בינה ותבונה<sup data-n=\"2528\">8</sup> וענין התבונ' הוא בחי' התפשטות אור הבינה (כמ\"ש בזהר דאו\"א תתאין הם יש\"ס ותבונה<sup data-n=\"2529\">9</sup> ונק' אימא תתאה<sup data-n=\"2530\">10</sup> כו') מצד קליטת' היטב בכלי המקבל ההשגה דבינה ע\"כ מתפשט בה להביאה בכמה ענינים נבדלים מעצם ההשגה והוא הנק' איש תבונה כמו מים עמוקי' כו' איש תבונה ידלנה<sup data-n=\"2531\">11</sup> מים עמוקים הם בחי' עמקות בינה שנשאר בהעלם העצמיות ואיש תבונה דווקא ידלנה וישאבנה מן ההעלם להביאה להתפשטות בכמה אופנים שונים לרוות את המקבלי' כמו הדולה מים עמוקים להשקות הצאן כו' והוא כמו שאנו רואי' בחוש שבהיות השכל והסברא עמוקה ביותר מהכיל בהשגת אדם הנק' מים עמוקי' כו' שהוא בחי' עומק המושג הנ\"ל שהאורך והרוחב ממנו בא כו' ואיש בעל תבונה דווקא ידלנה פי' שיוציא לאור בחי' העלם העומק המושג עד שיכילנו השגת האדם כאלו לא הי' עמוק כלל כמו הדולה מים עמוקי' שמקרב את העומק כו' ולפי\"ז מוכרח לומר שכח התבונה הוא כח המתפשט מכח הבינה להביא עומקה לגילוי למטה למקבלי' כו' משא\"כ כשאינו איש תבונות גם שהוא בעל השגה במוח דבינה (שנק' תפסן בל' העולם) יוכל להיות שהשגתו נשארת רק כמו שהיא בעצם במוח הבינה שלו שנק' רוח בינתו לבד ולא יבוא ממנה שום התפשטות למטה בענין נבדל שחוץ מן עצם ההשגה כלל וגם שיש בהשגה אורך ורוחב ועומק כנ\"ל הכל הוא רק בעצם ההשג' כמו שהיא אבל לא שיתגלה למטה בענין",[["2521","1","<b>כנשים</b>: וזיביג: ניתוסף: וקטנים. וראה בסמוך בפנים."],["2522","2","<b>כנשים שדעתן קלות</b>: שבת לג, ב. ראה לקו\"ש (תזריע) כרך יז ע' 149 הערה 14."],["2523","3","<b>דרינן פר. . פר. . עס</b>: אג: דערינן [א: ניתוסף: זייער] פאר. . פאר. . אגד: עש."],["2524","4","<b>אחת</b>: אג: ליתא."],["2525","5","<b>דדעת גנוז בפומא דאימא</b>: בסה\"מ דלהלן בשם האד\"ר ? ראה זהר (אדרא דמשכנא) משפטים קכג, א. סה\"מ תקס\"ח ח\"א ע' קפד."],["2526","6","<b>משה שהוא הדעת</b>: ראה תניא פמ\"ב. מאמרי אדה\"א בראשית ע' ר. וש\"נ."],["2527","7","<b>משה. . זכה לבינה</b>: ראה ר\"ה כא, ב. וראה גם סה\"מ תקס\"ח שם ע' קפה."],["2528","8","<b>בינה ותבונה</b>: ראה זהר (אד\"ז) האזינו רצ, ב. רצא, א. פע\"ח (שחה\"מ) שכ\"א פ\"א. מאו\"א מערכת תבונה ס\"ז. תו\"ח בראשית כב, א הערה 1."],["2529","9","<b>דאו\"א. . יש\"ס ותבונה</b>: ראה גם ע\"ח (שער או\"א) שי\"ד פ\"ח. הנסמן במ\"מ לשע\"ת קכו, ב."],["2530","10","<b>ותבונה ונק' אימא תתאה</b>: ראה גם זהר (אד\"ז) האזינו רצא, א."],["2531","11","<b>מים עמוקי'. . ידלנה</b>: משלי כ, ה [ושם: ואיש ? ראה המשך תער\"ב ח\"א ע' קסה וע' רסד]. ראה גם סה\"מ עת\"ר ע' קעג."]]],[2800530220,"נבדל ומכ\"ש עומק המושג הרי נשאר בעומקו בהעלם לעצמו וכן האורך והרוחב הכל בעצם ההשג' כמו שהיא במקומה לבד ודוגמא לכל זה הנה אנו רואים בעומק הפלפול בתלמוד וטעמי' בסברות<sup data-n=\"2532\">12</sup> רבות כך וכך גם שבאים בהשגה דבינה אבל לא יוכלו עדיין להוציא לאור מעצם השכל איזה פסק דין חייב או זכאי כלל דהיינו שלא יוכל להוציא מתוך הסברה איזה חיוב עפ\"י זה השכל ולא איזה זכות עפ\"י זה השכל כי עדיין אין השכל והסברא רק השכלה שכליות לבד בלתי ימצא ממנה שום התפשטות בהטיות לענין נבדל הימנה שהוא לחייב על ידה או לזכות על ידה וה\"ז כמו דבר ההיולי שלא נודע עדיין מה ימצא ממנה ומה יעשה בה (בל\"א דער מושכל אליין כמו שהוא ער קאן מיט אים נישט טאן קיין זאך ניט צו קערין לזכות או לחוב כו') ואמנם כח התבונ' שמתפשט ממוח הבינ' היינו מה שביכולתו להביא עצם ההשגה לבחי' התפשטות למטה ממנה בכל ענין נבדל הימנה או לחיוב או לזכות או להתפעל בלב וכן להביאה במחשבה בכמה אופנים שונים כו'. אך לכאורה אנו רואים שיש בבינה עצמה בחי' מדות הנק' ז\"ת דבינה<sup data-n=\"2533\">13</sup> ונק' מדות שבשכל המטה כלפי זכות או שכל מטה כלפי חוב כידוע היינו כמו שהמדות שבשכל הן בעצם ההשגה עדיין בהעלם אבל להביא בחי'<sup data-n=\"2534\">14</sup> התגלותן בדבר נבדל כמו להורות בענין מקרה דבר מה עפ\"י השכל והסברא הזאת להטות את המשפט של זה הענין לחו\"ג שבו דוקא הרי איש תבונה דווקא יוציא לאור מן המדות שבבינה כו' ואיש תבונות היינו כח הקולט בכי טוב לעצם ההשגה ע\"כ מתפשטת ההשגה בו לעשות ולהורות בה כמה ענינים נבדלים לגמרי וגם ביכולתו להביא את עומק בינה לידי גילוי כנ\"ל וד\"ל (והיינו בחי' או\"א תתאין יש\"ס ותבונה יש\"ס מדות דחכמה ותבונה מדות דבינה<sup data-n=\"2535\">15</sup> אך באין בבחי' הגילוי לחוץ ובחי' מל' דתבונה הוא השכל הבא במחשבה הנק' אותיות מחשבת שכל שהשכל מתלבש בה והוא בחי' כלי חיצוני למח' עיונית שהוא גלוי השגה דבינה עצמ' מצד עצם השכל והסברא כו' ומבחי' מל' דתבונה נמשך שרש אותיות המחשבה עצמה שנק' לאה<sup data-n=\"2536\">17</sup> כו' והוא ד' רבתי דאחד<sup data-n=\"2537\">16</sup> ) וזהו שנק' תבונה בן ובת<sup data-n=\"2538\">18</sup> כידוע להיות כי גם בתבונה יש ג' דברים עומק ואורך ורוחב העומק הוא עצם כח התבונה הזאת שבאותה ההשגה כמו שהיא בשעה שקולטת אותה כו' ובה יוכל עומק ההשגה הנ\"ל לבוא לגלוי כנ\"ל בפ' איש תבונה ידלנה כו' והאורך הוא ירידתה בענין אחר הנבדל להורות בו ולעשות מעשים רבים על ידה כו' והרוחב הוא בחי' התפשטות התבונה בעצם ההשג' להרחיבה במח' בכמה רבוי אופנים שונים ולא כמו שהיא לבד כו' ומה שכלולה התבונה מב\"ן וב\"ת היינו מה שמתבונה דוקא יולדו המדות בגלוי מהות בפ\"ע כי מבינה עצמה לא היו תולדות המדות אע\"פ שנק' אם הבנים<sup data-n=\"2539\">19</sup> כו' (אבל היא אימא עילאה<sup data-n=\"2540\">20</sup> ) משא\"כ התבונ' נק' אימא תתאה להוליד המדות והוא בחי' ב\"ן וב\"ת אהבה ויראה<sup data-n=\"2541\">21</sup> שבאים בהתכללות בתבונה דוקא שהיא בחי' התפשטות אור הבינה למטה כנ\"ל וגם לזה הטעם בחי' המוחין שבמדות נמשך מבחי' התבונה (וכמ\"ש ה' בחכמה יסד ארץ<sup data-n=\"2542\">22</sup> דאבא יסד ברתא<sup data-n=\"2543\">23</sup> כו' כונן שמים בתבונה שמים הן בחי' המדות<sup data-n=\"2544\">24</sup> אש מים<sup data-n=\"2545\">25</sup> כידוע וכן ובתבונה יתכונן שהוא בחי' קיום המדות בבחי' המוחין דתבונ' שבהם כי התבונ' כמו ממוצע להביא מוחין מבחי' מדות דבינה במדו' שבלב שזהו כמו כח ההבאה",[["2532","12","<b>וטעמי' בסברות</b>: אג: בטעמים וסברות."],["2533","13","<b>מדות הנק' ז\"ת דבינה</b>: ראה גם לקמן קלא, סע\"ב. סידור סדר הגדה רצה, ב. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשיח. כתובים ח\"א ע' קע. תו\"ח בראשית יד, ג ואילך. וירא קי, ד."],["2534","14","<b>בחי'</b>: תוקן ע\"פ ד: (בלוח התיקון). ובמהדורת טשערנאוויץ: בבחי'."],["2535","15","<b>יש\"ס ותבונה. . מדות דחכמה. . דבינה</b>: ראה גם פע\"ח (שחה\"מ) שכ\"א פ\"א."],["2536","17","<b>המחשבה. . לאה</b>: נסמן לקמן קלג, ב."],["2537","16","<b>מל' דתבונה. . לאה. . ד' רבתי דאחד</b>: ראה מאמרי אדה\"א דברים ח\"א ע' רפג ובהנסמן שם."],["2538","18","<b>תבונה בן ובת</b>: ראה זהר שבהערה 8. תו\"ח בראשית כח, ד בהערה 26."],["2539","19","<b>מבינה. . אם הבנים</b>: ראה זהר ויחי ריט, א. יתרו פד, א. פה, ב. לעיל עז, ב. צו, א. אמ\"ב שער התפילין צט, ד. מאמרי אדה\"א נ\"ך ע' שיב. וש\"נ."],["2540","20","<b>מבינה. . אימא עילאה</b>: ראה ע\"ח (שער או\"א) שי\"ד פ\"ח."],["2541","21","<b>ב\"ן וב\"ת אהבה ויראה</b>: ראה תניא פט\"ז. לעיל עז, ב. מאמרי אדה\"א שמות ח\"א ע' נג. וש\"נ."],["2542","22","<b>ה' בחכמה יסד ארץ</b>: משלי ג, יט."],["2543","23","<b>דאבא יסד ברתא</b>: ראה זהר (רע\"מ) פינחס רנו, ב. רמח, א. רנח, א. אגה\"ק ס\"ה. הנסמן במאמרי אדה\"א דברים ח\"ב ע' שפ הערה ד\"ה: מצירופי. קונטרסים ס\"ע תקמז ואילך."],["2544","24","<b>שמים הן בחי' המדות</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ע' לג. תקס\"ד ע' קמו ואילך. תו\"ח בראשית כא, ד."],["2545","25","<b>שמים. . אש ומים</b>: חגיגה יב, סע\"א."]]],[2800530221,"בענין הנבדל שהוא עיקר ענין התבונה<sup data-n=\"2546\">1</sup> כנ\"ל) וידוע<sup data-n=\"2547\">2</sup> ג\"כ שיש נו\"ן כפופה ונו\"ן פשוטה בבינה<sup data-n=\"2548\">3</sup> להיות נו\"ן כפופה הוא הרוחב ונו\"ן פשוטה הוא האורך ונ' המלוי שלו בנ' פשוטה משא\"כ בשאר מילוי האותיות כי האורך נכלל ברוחב וכך הוא בתבונה ואמנם נון הכפל בענין הנק' התבוננות כמו עמי לא התבונן<sup data-n=\"2549\">4</sup> וכו' שזהו בחי' פנימית בינה הנק' עיון לעמוד על דבר כו' שנק' בינה שבבינה הוא ממוצע בין בינה לתבונה ע\"י הנו\"ן פשוטה שמחמתו נק' התבוננות כו' וד\"ל<sup data-n=\"2550\">5</sup> :\n(ג) <b>ובכל</b> זה יובן בענין ההתבוננות בהשגת האלקות שיש ב' מדריגות בינה ותבונה בינה היינו בחי' עצם ההשגה האלקית בכל פרט ענין שמתבונן איך הוא ומה הוא ועומד על הדבר בעיון רב בכל פרטי חלקיו כו' כנ\"ל כמו בהשגה פרטיות דממכ\"ע שהוא התהוות יש מאין הנק' כח הפועל האלקי בנפעל כו' והוא בחי' שם אד'<sup data-n=\"2551\">6</sup> או שם אלקים לשון כח<sup data-n=\"2552\">7</sup> כידוע הנה יש בזה כמה חלוקי פרטי' באופני חיצוניו' הענין עד אשר יושג תוך תוך הענין הזה בפנימית העצמי איך שהוא בעצם כו' שזהו הנק' עומק המושג כו' כנ\"ל שהעיון הוא בחי' כלי לבא לבחי' העומק כו' ובחי' האורך הוא בחי' התקרבות הענין הזה אל השכל במשלים שונים הידועים עד שיהיה הדבר הזה קרוב במוחו מאד (בל\"א אראפ גילאזן זייער דעם שכל צו זיך) בלבוש הגשמה עד שיוכל תינוק להשיג כו' כנ\"ל והרוחב היינו להרחיב זה הדבר כמו שהוא בכמה אופנים שונים ולא באופן א' לבד כמו המשל לזה הדבר מחיי הנפש בגוף<sup data-n=\"2553\">8</sup> שאין זה רק התפשטות מן העצם כידוע ויש רבוי אופנים למאוד בהתפשטות מן העצם וגם בגלוי ההעלם כתנועת החי וכאותיות הדבור כו' או כהתחכמות מן עצם החכמה או כגלוי הראי' דעין או כגלוי שלהבת מן הגחלת כו' וכ\"ז נק' גלוי ההעלם משא\"כ משל זיו השמש או אור הנר וכח הפועל כו' שנק' התפשטות כו' וכה\"ג הרי כ\"ז בעצם הענין רק שנתרחב וההיפך מזה הוא הקיצור רק באופן אחד וגם הוא בדרך קצרה נסקר במוחו בלתי התפשטות להרחיב בו כלל כו' אבל כמו שזה הדבר נתפס לעומקו בעצם אחר כל רבוי הסבר דמיון המשלים הוא הנק' עומק ותמצית זה המושג כנ\"ל ודוקא אחר האריכות והרוחב במשלים בעיון רב יבא לבחי' העומק שמובן מהם (בל\"א דער הערין דיא טיפקייט פון דעם וויא דיא זאך איז באמת) דהיינו אחר הלבשת חיצוניותו בכל העיון הרב כו' וד\"ל:\n<b>(וכמ\"ש</b> למעלה בכל פרטי כח\"ב דבינה הכל ימצא בהשגה פרטיות כזאת וכה\"ג בכל השגת אלקות הפרטים<sup data-n=\"2554\">9</sup> וכמשי\"ת) ובחי' הדעת הוא בחי' ההכרה<sup data-n=\"2555\">10</sup> והרגשה במושכל בהתקשרות כנ\"ל וע\"ז נאמר וידעת כו'<sup data-n=\"2556\">11</sup> דע את אלקי<sup data-n=\"2557\">12</sup> כו' שהוא בהשגה זו דממכ\"ע דוקא כידוע (בל\"א דער קלעפ כו' כנ\"ל באורך) שהוא דוקא המביא לבחי' עומקא דכולא דהיינו לעומק דחכ' שמאין תמצא כנ\"ל דהיינו בבחי' עומק ראיות השכל בהשגה זו דבחי' מכ\"ע שלמעלה מהשגת השכל כידוע (וכמ\"ש ברע\"מ בעין השכל דבלבא אתחזי כולא<sup data-n=\"2558\">13</sup> ונק' לאסתכלא ביקרא<sup data-n=\"2559\">14</sup> כו' וגם בזה יש בחי' עומק כנ\"ל באריכות) ובחי' התבונה היינו לדלות ע\"י מעומק זה הנעלם במושג זה דממכ\"ע הנ\"ל לידי גילוי כי בהיותו קולט בכי טוב לעצם ההשגה הזאת ע\"כ יוכל להביאה בכמה ענינים נבדלים ממנה כמו בכמה פרטי מציאות עולמות הנבראים איך שמתהווים מאין ליש בבחי' ממלא דרך פרט אשר נעלם בכללות השגה זו כו' ובלתי כח התבונה הזאת בהשגה זו דממכ\"ע הרי נשארת",[["2546","1","<b>התבונה</b>: תוקן ע\"פ אגד. ובמהדורת טשערנאוויץ: התבוננת."],["2547","2","<b>וידוע</b>: גוז: (וידוע. וראה להלן הערה 5."],["2548","3","<b>נו\"ן כפופה. . פשוטה בבינה</b>: ראה מגן דוד להרדב\"ז מערכת נו\"ן. פרדס (שער האותיות) שכ\"ז פי\"ז."],["2549","4","<b>עמי לא התבונן</b>: ישעי' א, ג."],["2550","5","<b>וד\"ל</b>: גו: וד\"ל). וראה לעיל הערה 2."],["2551","6","<b>אד'</b>: תוקן ע\"פ גד. ובמהדורת טשערנאוויץ: אדם."],["2552","7","<b>שם אלקים לשון כח</b>: ראה שו\"ע אדה\"ז חאו\"ח דין כוונת הברכות ס\"ה ס\"ג. אוה\"ת יתרו ע' תשנא."],["2553","8","<b>המשל. . בגוף</b>: ראה (ובהבא לקמן) לקמן קסו, א. מאמרי אדה\"א נ\"ך ע' קנח ואילך ובהנסמן לשם."],["2554","9","<b>הפרטים</b>: טו: הפרטי'."],["2555","10","<b>הדעת. . ההכרה</b>: ראה גם שע\"ת פא, א ובהנסמן במ\"מ שם."],["2556","11","<b>וידעת כו'</b>: ואתחנן ד, לט."],["2557","12","<b>דע את אלקי</b>: דהי\"א כח, ט."],["2558","13","<b>בעין השכל דלבא אתחזי כולא</b>: ראה זהר (רע\"מ) משפטים קטז, ב. הנסמן במאמרי אדה\"א קונטרסים ע' תקפד."],["2559","14","<b>לאסתכלא ביקרא</b>: ראה זהר מקץ קצט, א. בראשית לח, א-ב. פקודי רמז, ב. תרומה קלד, א."]]],[2800530222,"השגה זו רק במוח הבנתו לבד ולא ידע מה לעשות בה ואיך להביא זאת ההתבוננות באיכות ענין התהוות היש מאין כלל כמובן מכל הנ\"ל וד\"ל (ומזה מובן סיבת המניעה בחדשים או גם בישנים בחסרי תבונה גם שמשיגים היטב הדק בשעה ששומעים ורואים לא יוכלו להביא הדבר כלל בהתבוננות בתפלה בענין התהוות העולמות עד שישאל מה לעשות בכל זה ולאיזה תועלת צריכים לזה כי ב' דברים נבדלים הם לדעתו מפני שנשאר רק בחי' ההבנה עצמה במוחו נבדל לגמרי מכל ענין כו' (בל\"א מער ניט „ז דער מושכל<sup data-n=\"2560\">15</sup> „ליין פ„ר זיך כו') וד\"ל<sup data-n=\"2561\">16</sup> :\n(ד) <b>ומעתה</b> יש לבאר באיכות ענין ההתבוננות אם דרך כלל או דרך פרט דווקא כמו ע\"ד דוגמא בהשגה אלקית דבחי' ממכ\"ע דרך כלל בג' עולמות בי\"ע הכל שרש ענין א' הוא בכל המשלים דזיו והתפשטות או אותיות כו' וכללותו רק ענין הגלוי מן ההעלם או כמו ערך הנבדל לבחי' בע\"ג מחודש לגבי בלתי בע\"ג דרך כלל שיש בזה ריבוי אופנים והכל בכלל<sup data-n=\"2562\">17</sup> גם שנמצא בזה ענינים פרטים הרבה (כמשי\"ת) או דרך פרט להתבונן בכל עולם ובכל נברא ובכל פרטי מדריגות חלוקים בסדרי ההשתלשלות מעילה לעילה בכ\"א בפ\"ע דוקא כו' וכך הוא השאלה בהתבוננות ביחו\"ע באו\"כ דאצי' בכל פרטי ע\"ס עד עצמות אור א\"ס אם להתבונן בכללות ענין אור האצי' באיכות צמצומו מן העצמות ואיך שנבדל הערך לגבי עצמות המאציל ואיך דאיהו וחיוהי חד<sup data-n=\"2563\">18</sup> כו' (גם שיש בו עניני' פרטיים הרבה מאד כמשי\"ת) בכמה מיני משלים כמו שלהבת הקשורה כו' שנז' בס\"י<sup data-n=\"2564\">19</sup> או כענין גלוי ההעלם דכחו' הנפש מעצמו' הנפש דרך כלל כידו' עד שאח' העיון יושג בחי' העומק מזה כנ\"ל בהשגה דממכ\"ע שנק' יחו\"ת כידוע. והנה באמת לא ראי זה כו' דיש מעלה בהתבוננות דרך כלל כדי שיוכל לבא לבחי' העומק בכלל שהוא בחי' עצמות אור האלקי בבחי' הכלל בין ביחו\"ע בין ביחו\"ת שזהו עיקר התכלית בגלוי אלקות בנפש כו' ויש מעלה בהתבוננות דרך פרט דוקא מצד עוצם הקירוב גלוי אור האלקי בנפשו יותר כי בהתבוננות דרך כלל יוכל להטעות א\"ע עד שנדמה לו כי מאד קרוב אליו הדבר ובאמת מרחוק מאד ה' נראה לו בהיותו דרך כלל לבד משא\"כ ההתבוננות דרך פרט<sup data-n=\"2565\">20</sup> שכל פרטי בהשגה בדבר פרטי הרי יוקבע בנפשו בבחי' הקירוב ביותר וממנו יבוא להשגת דבר פרטי העליון הימנו בהדרגה עד שיבוא לכלל ההשגה בכלליות שאז מתאמת יותר בלתי הטעות א\"ע כלל כמו כשתחלה יתבונן דרך פרט בממכ\"ע באיכות התהוות שרש שפע הרוחניות דגלגלים<sup data-n=\"2566\">21</sup> ומזלות<sup data-n=\"2567\">22</sup> מאין ליש דעשי' משמרי האופנים ואח\"כ יתבונן בפרטיו' באופני' וחיות כו' עד בחי' מל' דעשיה כללות האור האלהי שמהוה עולם העשיה ועד\"ז בפרטי י\"ס דעשיה עד בחי' מל' דיצירה שנעשה כתר לעשיה וכן עד\"ז בפרטיות דיצי' ובפרטיות דבריאה כו' עד בחי' מל' דאצי' כללות הכל כו' שנק' שם אלהי' בכלל כידוע שאז מתאמת הדבר יותר בקירוב כו' כי אחר העיון היטב בכל הפרטים הגם שכל פרט בפ\"ע אינו ענין אלהות בכללות ואינו רק בחי' טפל פרטי לבד אבל כאשר יתחבר כל העיון מכל הפרטים אל הכלל אז יוקבע יותר בנפש בחי' הכלל כאשר בדוק ומנוסה לכל עוסק בעמקות בהתבוננות וגם ביחו\"ע בהתבוננות דרך פרט בכל פרטי הע\"ס בפרצופים דזו\"נ ואו\"א וא\"א וע\"י עד ראשית הקו בא\"ק כו' דרך פרט דוקא הוא המועיל לקבוע בנפש מבחי' כללות עצמות המאציל הכוללם יחד משא\"כ ההתבוננות דרך כלל לבד כנ\"ל שמרחוק ה'",[["2560","15","<b>מושכל</b>: טו: שכל."],["2561","16","<b>וד\"ל</b>: אוצ\"ל: וד\"ל)."],["2562","17","<b>בכלל</b>: טו: בכללות."],["2563","18","<b>דאיהו וחיוהי חד</b>: ת\"ז בהקדמה (ג, ב)."],["2564","19","<b>שלהבת הקשורה. . בס\"י</b>: פ\"א מ\"ז."],["2565","20","<b>ההתבוננות דרך פרט</b>: ראה ג\"כ שיחת י\"א ניסן תשמ\"ח הערה 68 (ספר התוועדויות תשמ\"ח ח\"ג ע' 42)."],["2566","21","<b>שפע הרוחניות דגלגלים. . האופנים</b>: ראה פרדס (שער אבי\"ע) שט\"ז פ\"ח."],["2567","22","<b>ומזלות. . האופנים</b>: ראה גם מאמרי אדה\"א דברים ח\"ב ע' תפד (בשם הע\"ח). תו\"ח נח נט, ד ובהערה 57."]]],[2800530223,"נראה לו (עד שיוכל ליפול בדמיונות כוזבות כשוטים וחסרי הדעת מצד צמצום כלי מוחו רק בדבר א' והוא כללי כו') אבל צמצום העמקת הדעת בכל פרט הוא ההיפוך מן הטעו' והריחוק אדרב' עי\"ז מתקרב הדבר יותר אצלו בהיותו הולך מפרט לפרט העליון הימנו עד שכוללם יחד ליחד יחוד כללי ולא יחוד פרטי כמו לך ה' הגדולה<sup data-n=\"2568\">1</sup> כו' שענין היחוד האלקי הוא בחי' עומק ההשגה בביטול היש לאין ביחו\"ת ויחו\"ע ויש יחוד פרטי בדבר פרטי כמו לך ה' הגדולה שהוא בחי' חסד שבמל' דאצילות בבי\"ע דרך פרט בכל עולם כו' וגם כללותו אינו אלא פרט מדה א' ממדה שבמל' כו' ולך ה' הגבורה בכללותו ופרטיו בכל עולם נק' יחוד פרטי ועד\"ז בכל יחודי' פרטיי' שבי\"ס דבי\"ע כידוע אבל יחוד הכללי הוא כמו מ\"ש הנה מקום אתי<sup data-n=\"2569\">2</sup> או המלך המרומם כו' המתנשא מכל ימות עולם<sup data-n=\"2570\">3</sup> דו\"ק ומוחין חו\"ב שבהם כו' וגם זה פרט יחשב לגבי עצמות בחי' המל' שהוא כתר מל' וכה\"ג בע\"ס דאצי' כו' עד עצמות בחי' מל' דא\"ס בראשית הקו יש יחודי' פרטים הרבה בכל ספירה ופרצוף כו' ויחוד הכללי בכללות ביטול כל ההשתלשלות דקו כו' לגבי עצמות אור א\"ס כידוע. אך הנה מי שלא העמיק דעתו ביחודי' פרטי' ומתחיל מבחי' הכלל גם שבא לו ביגיעה רבה בהשגות רבות באיכות ענין הביטול בכלל כמו כשלהבת כו' וכה\"ג לא יוקבע בנפשו אמיתית ענינו כ\"כ כמו אחר עיון היטב בכל פרטיי' עד שמהם יבוא לבחי' הכלל. והיינו דפרט אצטריך לכלל<sup data-n=\"2571\">4</sup> וכלל אצטריך לפרט מפני שאין כלל בלא פרט כו' (ודבר זה כבר נחלקו בו הרבה מגדולי הראשונים כמו הרמב\"ם והטור אם לכוון בפי' המלות<sup data-n=\"2572\">6</sup> דרך פרט בגדולת ה' אם לכוון דרך כלל לפני מי<sup data-n=\"2573\">7</sup> אתה עומד<sup data-n=\"2574\">5</sup> ומתפלל כו' כמ\"ש בכתבי') והגם שהמח' כללי' עם המח' פרטי' לא ישכנו כא' מ\"מ מי שהוא מעמיק בכל לבו ובכל חפצו לעצמו' האלקו' דוקא הנה גם בעיונו בפרטיות יכוין הכל אל המח' הכללי' דעצמות דוקא ולא יפול מכללות הכונה כלל מחמת צמצום הכונה הפרטיות מאחר שכל הפרטים אינם נמשכים והולכים רק אחר הכלל דוקא כידוע לכל הולך בדרך אמת לה' לבדו דוקא כמ\"ש ז\"ל אליו ולא למדותיו<sup data-n=\"2575\">8</sup> רק כללות ענין ההתבוננו' בפרטי מדותיו הוא רק כדי שיבא לעצמותו ומהותו דוקא ולא לכוון העיקר רק בכוונה של הפרט כמו בשביל איזה לימוד לעצמו גם בעיונו בס' הזוהר ובכתבי האריז\"ל צ\"ל עד\"ז דוקא וד\"ל (וכאשר מקובל היה א\"א מו\"ר ז\"ל נ\"ע בדבר זה מפי הה\"מ ז\"ל<sup data-n=\"2576\">9</sup> בפי' גמור וכך שמעתי מפיו ז\"ל). ובזה מתורץ שאלת השואלים על פי' המלות דרך פרט ליודעים בהם איך שאינם מבלבלי' את מחשבת הכלל אלא אדרב' כוונות פי' המלות עפ\"י הקבלה מסייעים לחזק את עומק השגת הכלל בעצמות אלקות כידוע לטועמי טעם בהם דרך פרט כו' רק החדשים יותר טוב להם להעמיק דרך כלל תחלה עד שיורגלו מעט מעט בדרך הפרט דווקא וד\"ל<sup data-n=\"2577\">10</sup> :\n(ה) <b>והנה</b> אחר שנתבאר שצריך להתבונן דרך פרט דוקא הרי מן ההכרח לידע כל פרטי חילוקי המדריגות בכל פרטי סדרי ההשתלשלות דאבי\"ע להתבונן בהם אשר אינם מובנים לכל מכללי התורות כו' ויבוארו כולם בקונטרס מיוחד מן הצריך מכל פרט וממילא יובן למבין ויודע כמה פרטים אחרים אך תחילה צריך להקדים באיכות ההתבוננות גם בדרך פרט עוד ענין א' הצריך ביותר לכל החפץ באמת בקרבת אלקי' ואינו רוצה לצאת י\"ח להטעות א\"ע כו'.",[["2568","1","<b>לך ה' הגדולה</b>: דהי\"א כט, יא."],["2569","2","<b>הנה מקום אתי</b>: תשא לג, כא."],["2570","3","<b>המלך המרומם. . עולם</b>: ע\"פ ברכת יוצר."],["2571","4","<b>דפרט אצטריך לכלל</b>: ראה זהר שמות ג, א. תרומה קסא, ב. ואתחנן רסד, א. שע\"ת קטו, סע\"ג ואילך."],["2572","6","<b>והטור. . בפי' המלות</b>: או\"ח רסצ\"ח. וראה גם אג\"ק כ\"ק אדה\"א ח\"א ע' רסו וע' שיא."],["2573","7","<b>לפני מי אתה עומד</b>: ראה ברכות כח, ב."],["2574","5","<b>הרמב\"ם. . לפני מי אתה עומד</b>: הל' תפלה פ\"ד הט\"ז. וראה גם שיחת ש\"פ צו תשמ\"ו (ס' התוועדויות תשמ\"ו ח\"ב ע' 791). אגרות קודש מכ\"ק אדמו\"ר שליט\"א חי\"ג ע' רלה. לקו\"ש (אמור) כרך כב ע' 118 הערה 36."],["2575","8","<b>אליו ולא למדותיו</b>: ראה פרדס (שער הכוונה) של\"ב פ\"ב. מאמרי אדה\"א ויקרא ח\"א ע' נ. וש\"נ. נ\"ך ע' לד. וש\"נ. לקמן קכו, א."],["2576","9","<b>וכאשר מקובל. . הה\"מ ז\"ל</b>: מובא גם בסה\"מ מלוקט ח\"ו ע' צז."],["2577","10","<b>ובזה. . וד\"ל</b>: ג: (ובזה. . וד\"ל)."]]],[2800530224,"<b>והוא</b> בהיות ידוע שבכל התבוננות בענין אלקי דהתהוות יש מאין בכל מקום לפי מה שהוא הרי כולל ב' ענינים הא' בחי' ביטול היש לאין שזהו השגת ערך הב\"ג תחלה באיכות אופן התהוות מציאותו מאין כו' שזה קרוב אל השכל ביותר ע\"י כמה מיני הסברי' ודמיונות המשלים וכה\"ג עד שנתאמת במוח היטב (בל\"א עש לייגט זיך אין מוח זייער כו') והב' ענין בחי' האין האלקי המהווה אותו ואיך שהוא נבדל בערך להיותו בלתי בע\"ג כו' וזהו הנעלם מעיני השכל בהשגה גמורה רק מ\"מ יוברק כמו ברק בסקירה בעלמא במוחו אמיתת ענינו כמו שהוא אבל הוא בבחי' ההעלם כאילו נתאמת הדבר בראי' חושיית והוא ההפרש בין בחי' ראי' דחכמ' כח מ\"ה<sup data-n=\"2578\">11</sup> שבנפש שרוא' ולא בראי' חושיית כ\"א ראי' שכליית בהברקה למעלה מן השגה הגמורה וע\"כ ההתפעלות מזה אינו רק בחי' הביטול שהוא רק העדר הרגשת עצמו מכל וכל כו' (בל\"א ער ווערט צו רירט פון ארט ואינו מרגיש גם זה גופא כו') ובין בחי' שמיעה דבינה שבאה בהשג' גמורה ממש שהוא באיכו' התהוות היש מאין כנ\"ל שההתפעלות מזה הוא השמחה במורגש וטוב לב כל שמשיג יותר יותר טוב לו (בל\"א עש איז זייער גוט ומחי' לנפש כו') וכל שמעמיק יותר יותר משיג ובבחי' הראי' דחכ' הוא להיפוך כל שיעמיק יותר יותר יפלא ממנו מהות בחי' האין האלקי המהווה כו' בהפלאת הערך יותר ויותר כו' עד שיצטע' וידאג כו' (כמ\"ש בכתבי'<sup data-n=\"2579\">12</sup> ) ולפי\"ז הרי בכל מעיין בדרך פרט יבוא לכלל ב' ענינים האלה בהתבוננות בהעלם וגילוי והתפעלו' הנולד ב' הפכים הם לבו דואג בקרבו<sup data-n=\"2580\">13</sup> על עוצם הפלא' ההשגה באין האלקי המהווה כו' והשמחה מהשגתו בכי טוב באיכות התהוות המתהווה כו' כמו ע\"ד דוגמא המתבונן דרך פרט בהתהוות הגלגלים מאין האלקי שהיא מבחי' כלים חיצונים דמל' דמל' דעשיי' שהוא רק מבחי' כלי חיצוניות הארה דהארה לבד המאיר בנפש של זה הגלגל בהשגתו במהווה אותו ועד\"ז גם במלאכים דבריאה דאימא מקננא<sup data-n=\"2581\">14</sup> כו' שמשיגים כח האלקי דמל' דמל' דאצילות כו' המהווה אותם הרי זהו המושג בהשגה ויתפעל מגדולת הבורא ואיך שהמה בטלי' בתמידות כמ\"ש וצבא השמים לך משתחוים<sup data-n=\"2582\">15</sup> בסיבובם כו' אבל בחי' האין האלקי דמל' דעשי' המהווה נעלם מהותו מן ההשגה רק שממילא הוא מוכרח בהשג' אחר התאמת אופן הענין של ההתהוו' היש כו' ובבחי' ההעלם לבד הוא מושג ובהפלאת הערך נבדל דוקא וכך הוא בהתבוננות פרטיו' באצילות באו\"כ כמו באצילות אור חסד שבמל' או באצילות אור חסד שבחכמ' ואיך שנאצל יושג ע\"ד דמיון מאור הנאצל למטה בגילוי מהעלם העצמות כמו ויאצל מן הרוח<sup data-n=\"2583\">16</sup> דמשה כו' וכה\"ג ויושג ג\"כ בענין התהוות מדות דאצילות גם שהן בחי' מקוריי' נבדלי' מן השפעה האלקי' בנבראי' כו' אבל בחי' אין האמיתי המאיר עליהם מאור עצמות המאצילם לא יושג אף בדמיון שכל כ\"א בהעלם לבד והוא בבחי' ראי' השכל שלמעל' מן השג' ותפיסא ממש וכמאמ' לית מח' תפיסא בך<sup data-n=\"2584\">17</sup> כו' שהוא מח' דבינה כו' דהיינו שזהו היפך ההשגה כי כל שמעמיק יותר יותר מופלא הימנו עצמיות אור המאציל כו' והסימן לזה הוא הנולד מזה בחי' הביטול ביותר כנ\"ל ונמצא בחי' הביטול והשמחה שמסתעפי' ונולדי' מחו\"ב שבכל פרט בהכרח שבאים כא' דוקא בכל התבוננות בכל פרט ופרט דווקא והא בהא תליא ואם לא השמחה ביש מההשגה בטוב לא יבוא להפלאת וריחוק ההשגה באי\"ן ולפי ערך השמחה כך ערך הביטול ממש כי כפי ערך ההשגה במתהווה כך ערך",[["2578","11","<b>דחכמ' כח מ\"ה</b>: זהר (רע\"מ) צו כח, א. לד, א."],["2579","12","<b>הראי' דחכ'. . כמ\"ש בכתבי'</b>: ראה גם מאמרי אדה\"א במדבר ח\"ג ע' תתקע."],["2580","13","<b>לבו דואג בקרבו</b>: נסמן לקמן קיג, ב."],["2581","14","<b>דאימא מקננא</b>: ת\"ז ת\"ו (כג, א). ראה מאמרי אדה\"א דברים ח\"א ע' רסב. וש\"נ. קונטרסים ע' תכג. וש\"נ."],["2582","15","<b>וצבא השמים לך משתחוים</b>: נחמי' ט, ו. ראה מאמרי אדה\"א בראשית ע' נז. וש\"נ. תו\"ח בראשית א, ג ובהערה 42."],["2583","16","<b>ויאצל מן הרוח</b>: בהעלותך יא, כה."],["2584","17","<b>לית מח' תפיסא בך</b>: ת\"ז בהקדמה (יז, א)."]]],[2800530225,"ההפלאה בהבדל המהווה כו' וזהו כלל גדול בכל ההתבוננות בפרט ובכלל (משא\"כ מי שנדמה לו שתופס היטב ההתהוות ואין לו בחי' ביטול מצד המהווה לא השיג כלום בוודאי בלי ספק ומי שידמה לו בחי' הביטול בעצמו מצד הפלאת ערך המהווה כו' ולא השיג בכי טוב לאופן המתהוה כו' דמיון שוא הוא ואין לו בחי' ביטול כלל כי הא בהא תליא לפי ערך דוקא מטעם הנ\"ל וכידוע לכל טועמי טעם בהתבוננות באמת ואינם מטעים א\"ע כלל וכאשר יובן כ\"ז לרגילים בד\"ח<sup data-n=\"2585\">1</sup> מנעוריהם כו' ורבים מאד יטעו בעצמם בכ\"ז בכמה אופנים שונים וכו'):\n(ו) <b>והנה</b> ידוע המאמר דבכי' תקיע' בלבאי מסט' דא וחדווה מסט' דא<sup data-n=\"2586\">2</sup> כו' להיות שצריך להקדי' בחי' הכנה בנפש לכללות הידיעה האלקי' בהשתלשלות דאוא\"ס באבי\"ע עד שתהא הנפש בחי' כלי מוכן לזה וזה אינו אלא ע\"י אמצעות ב' דברים הללו דבכי' וחדוו' גם שהן ב' הפכים הרי באים כא' ממש מהתבוננות אחת דווקא ובזה נעשה דוקא בחי' הכנה רבה בנפש לקבוע בעצמיות שלה מכל השגות פרטיות דאא\"ס באבי\"ע ואם יחסר א' מאלה דהיינו זה בלא זה או גם שנדמה לו שיש בלבו משתיהם אבל אינם לאמיתתם ולעומק' בנפש כלל רק דרך מעביר חיצוני בעלמ' ה\"ז סימן גמור שלא נקבע בנפשו כלום רק מרחוק מאד כו' ובמעט דבר המנגד כמו בטרדא גדולה או בהרגשת עצמו ליש ביותר כו' ינתק מלבו לגמרי כו'. וביאור הדברי' הנה ידוע דענג ושמחה הוא בחו\"ב הענג בחכמה<sup data-n=\"2587\">3</sup> ושמחה בבינה<sup data-n=\"2588\">4</sup> (וזהו ההפר' בין שבת ליו\"ט<sup data-n=\"2589\">5</sup> כידוע) כי ההשג' בשכל מוליד השמחה שהוא שמחת הנפש כמ\"ש אם הבנים שמחה<sup data-n=\"2590\">6</sup> וידוע שעיקר השמחה דווקא באלקות הוא וכמו וישמחו בך<sup data-n=\"2591\">7</sup> דוקא ולפי הנ\"ל דבהשג' לית מח' תפיסא ביה אדרבה מופלא בהפלאת הערך הנבדל כו' והיינו בבחי' כח מ\"ה דחכמ' בהעלם כנ\"ל וא\"כ נהפוך הוא שאין השמחה במהותו כו' כי מאחר שמשיג אין זה אמיתתו ומהותו רק בחי' צמצומו להוות המתהווה כו' ובחכמ' בחי' אין כנ\"ל שם ראוי להיות השמחה כמו שאמר וישמחו בך ואינו כן כידוע דהביטול היפך השמחה בחכמה דווקא והשמחה בבינה כו'. אך הענין הוא כידוע שבכל דבר יש היפוכו וגם שנגלה להיפוכו ממש אדרבה מזה עצמו נראה לעין שכל כחו אינו בא רק מכח המנגדו ממש ולפי ערך כח המנגד כן ימצא כח היפוכו ממש א\"כ כדבר א' ממש הוא כמו הענג והצער שלפי ערך כח התענוג בדבר מה כן ממש לפי ערך ימצא כח התפעלות הצער<sup data-n=\"2592\">8</sup> שהוא גרעון אור הענג המנגדו דהיינו אם יעמוד לנגדו דבר לבטל הענג ההוא להיות מן ההיפוך כו' וכן להיפך ערך הענג מדבר מה לא יוכר רק לפי ערך הצער בהעדר אותו הדבר כו' הרי כח א' הוא ממש רק שנחלק לב' קווין שוין ממש ושקולין בלתי יטה כח קו א' על הב' אפי' כקוש\"י וכן החדוה והבכי' שלפי ערך החדווה שהוא ענג המורגש בגלוי אלקות בהשגתו כנ\"ל כך ימצא קו הב' שיוצא ממנו ומכחו דוקא שהוא הבכי' על העדר גלוי האור בנפשו מצד הסתר אלקות עד שמואס בחייו ממש וכל שטעם טעם ענג אלקי בחדווה יותר יותר יתמרמר בנפשו מהיפוכו וכן להיפך מערך עומק המרירות והבכי' למאוס בחייו הגשמים ניכר ערך כח העונג והחדווה באלקות כמה ערך כוחו כי ב' קווין הללו שקולין מאד בשוה כנ\"ל והיינו בכי' מסט' דא",[["2585","1","<b>בד\"ח</b>: א: בדברי חסידות."],["2586","2","<b>המאמר דבכי'. . מסט' דא</b>: תניא ספל\"ד. ראה גם שע\"ת ב, א ובהנסמן לשם."],["2587","3","<b>הענג בחכמה</b>: ראה תו\"א יתרו ע, א. סה\"מ תקס\"ה ח\"א ע' קנא. מאמרי אדה\"א דברים ח\"ד ע' א'תעא."],["2588","4","<b>ושמחה בבינה</b>: ראה מאמרי אדה\"א נ\"ך ע' מח. וש\"נ."],["2589","5","<b>ההפר' בין שבת ליו\"ט</b>: ראה שו\"ע אדה\"ז הל' שבת ר\"ס רמב. הל' יו\"ט סתקכ\"ט. לקו\"ש (דברים) ח\"ד ע' 1090 בהערה 31. מאמרי אדה\"א במדבר ח\"ג ע' תתקסד ואילך."],["2590","6","<b>אם הבנים שמחה</b>: תהלים קיג, ט."],["2591","7","<b>וישמחו בך</b>: נוסח תפלת העמידה ליו\"ט."],["2592","8","<b>הענג והצער. . הצער</b>: ראה אגה\"ק סכ\"ט (קמט, ב). לקמן קכו, א. מאמרי אדה\"א הנחות תקע\"ז ע' עט. וש\"נ."]]],[2800530226,"וחדוה מסט' דא בשקול א' בשוה ממש וכמו\"כ למעל' מזה בבחי' עונג הנעל' שבחכמ' שמזה בא בחי' הביטול מעצמותו לגמרי (בל\"א צו טראגן גאר פון זיך) מעומק עונג הנעלם בעצמיות שלו כו' הרי היפוכו הבא מכחו הוא ענין השלכת נפשו מנגד בכל דבר המנגד לזה שהוא נכלל בבחי' הרגשת עצמו דהיינו למאוס בחייו בתכלית התבטלות האמיתי' כמו מי לי בשמים ועמך כו' כלה<sup data-n=\"2593\">9</sup> כו' כי ב' קווין שקולים בשוה הן כנ\"ל וד\"ל. והנה יש בכי' למעלה מזו והוא הבא מהעדר ההשגה מחמת עוצם הפלאת והבדלת הערך מפני שלא יכילו כלי מוחו כו' כמו זלגו עיניו דמעות דר\"ע<sup data-n=\"2594\">11</sup> בסודות עמוקות שלא יכיל הכלי כו'<sup data-n=\"2595\">10</sup> והוא בבחי' הפלא' סדכ\"ס דהיינו בעצמו' אא\"ס ממש אשר בלתי מושג כלל אדרב' כל שיעמיק יותר יותר יפלא כנ\"ל שמזה דוקא לבו דואג ובוכה שאינו בא רק מעוצם התענוג והתשוקה להשיג ואינו יכול כו' וידוע שזהו עיק' בחי' הכלי לבחי' חכמה ברזין דאורייתא כמ\"ש במ\"א בענין אין מוסרין רזי תורה אלא למי שלבו דואג בקרבו<sup data-n=\"2596\">12</sup> כו' אבל כשהי' משיג לעצמו' אא\"ס ממש שם הוא ענין השמחה בעצמותו ואע\"פ שהוא גלוי הענג האלקי הבא במורגש דוקא אבל שרשו באמת בעצמות התענוג הנעלם שממנו יצא היפוכו שהוא הבכי' מהעדרו שהוא הפלאה והבדלה כנ\"ל כי ב' קווין הללו שקולין ג\"כ בשוה ממש דהיינו שלפי ערך כח עוצם וגודל התענוג שהיה מתענג בעצמות דוקא כשהי' משיגו ממש כך ימצא כח היפוכו שהיא הבכי' העמוקה כשלא יכילו כלי מוחו להשיג כנ\"ל וד\"ל. ונמצא סדר המדריגות בדבר והיפוכו כך הם חדוה ושמחה מגלוי אור אלקי המושג ממש והיפוכו יוצא בכי' בהסתר המנגד לזה ולמעלה מזה בבחי' ענג וחדוה הנעלם שבכח מ\"ה דחכמה בעצמות אלקות המהווה כו' וכחו בהיפוכו יוצא למאוס בחייו ובחיי כל זולתו כמו מי לי כו' ולמעלה גם מזה הענג והחדוה העצמי' בעצמות אלקות דוקא כמו וישמחו בך ממש בגלוי כו' כוחו<sup data-n=\"2597\">13</sup> בהיפוכו יוצא כאשר לא יכילו כלי מוחו להכיל כו' יבכה (וכמו בכי' דאוהב הנאמן בנפשו בהפרדו כדוד ויהונתן דאהבת נפשו אהבו<sup data-n=\"2598\">14</sup> דכתיב וישקו ויבכו<sup data-n=\"2599\">15</sup> כו' שבא מכח ריבוי אהב' בתענוג הגדול שביחוד' ודבוקם כו' וכה\"ג). ובכ\"ז מתורץ ענין הנ\"ל בשמחה שבבינה וענג שבחכ' דגם שההשגה עצמה היא בבחי' צמצום אור האלקי שמשיגו אבל השמחה שרש' מגיע בעצמות אלקות דוקא כמו הנשמות נהנין מזיו השכינ' ממש בג\"ע<sup data-n=\"2600\">16</sup> גם השגת' באה ע\"י צמצום כידוע וזהו וישמחו בך דוקא והיינו חדווה בסט' דא ובכי' היפוכ' יוצא מכחה בג' מיני מדריגות הנ\"ל וב' קווין שקולין הם בשוה ממש כנ\"ל וזהו בשמחה וטוב לבב מרוב כל<sup data-n=\"2601\">17</sup> בהשגת המהוה<sup data-n=\"2602\">18</sup> וכמו לעתיד דכתיב עין בעין נראה<sup data-n=\"2603\">19</sup> כו' ואמר ביום ההוא<sup data-n=\"2604\">20</sup> הנה אלקינו זה לנוכח אז ונגילה ונשמחה בו<sup data-n=\"2605\">21</sup> דוקא כידוע וד\"ל אבל עכשיו כ\"ז בוקע ויוצא ע\"י המנגד היפוכו דוקא שהוא הבכי' מסט' דא עד רום המעלות וכמ\"ש בבכי יבואו<sup data-n=\"2606\">22</sup> דוקא וכן הלוך ילך ובכה<sup data-n=\"2607\">23</sup> כו' ולע\"ל יהי' השחוק כמ\"ש אז ימלא שחוק פינו<sup data-n=\"2608\">24</sup> וכמ\"ש במ\"א בענין הקניגי'<sup data-n=\"2609\">25</sup> כו' וז\"ש כי אתה אבינו זה יצחק<sup data-n=\"2610\">26</sup> שצחוק זה בא לעתיד מן המנגד שלו אשר בחי' הבכי'<sup data-n=\"2611\">27</sup> הי' בגלות כידוע. ובכל זה יובן טעם האמיתי לענין תיקון חצות בבכי' דוקא שהוא תועלת לנפש להיות בתפילה גילוי תענוג העצמי כמו וישמחו בך וכה\"ג והגם שהבכי' בתיקון חצות<sup data-n=\"2612\">28</sup> הוא דמעות פשוטים על ח\"נ וכה\"ג אבל על זה אמר היתה לי דמעתי<sup data-n=\"2613\">29</sup> לחם יומם ולילה בק\"ש ותפילה דשחרית וערבית כו' מפני שהדמעות על הריחוק שלו מעוונות וחטאים",[["2593","9","<b>מי לי בשמים. . כלה</b>: תהלים עג, כה. כו."],["2594","11","<b>זלגו עיניו דמעות דר\"ע</b>: ראה זהר (מדה\"נ) וירא צח, ב. ז\"ח בראשית ז, א. הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'קכג."],["2595","10","<b>כמו. . כו'</b>: אג: (כמו. . כו')."],["2596","12","<b>אין מוסרין. . בקרבו</b>: ראה חגיגה יג, א. סה\"מ תקס\"ד ע' סד. מאמרי אדה\"א ויקרא ח\"ב ע' תסא ואילך וש\"נ."],["2597","13","<b>כוחו</b>: אוצ\"ל: וכחו."],["2598","14","<b>דאהבת נפשו אהבו</b>: שמואל-א כ, יז."],["2599","15","<b>וישקו ויבכו</b>: שמואל-א כ, מא [בדילוג]."],["2600","16","<b>הנשמות נהנין. . בג\"ע</b>: ראה ברכות יז, א."],["2601","17","<b>בשמחה. . מרוב כל</b>: תבוא כח, מז [ושם: ובטוב ? ראה הנסמן במאמרי אדה\"א קונטרסים ס\"ע שיט]."],["2602","18","<b>המהוה</b>: אג: המהות."],["2603","19","<b>עין בעין נראה</b>: שלח יד, יד. א: יראו ? ישעי' נב, ח."],["2604","20","<b>ואמר ביום ההוא</b>: ישעי' כה, ט."],["2605","21","<b>ונגילה </b>[אג: נגילה]<b> ונשמחה בו</b>: תהלים קיח, כד."],["2606","22","<b>בבכי יבואו</b>: ירמי' לא, ח."],["2607","23","<b>הלוך ילך ובכה</b>: תהלים קכו, ו."],["2608","24","<b>אז ימלא שחוק פינו</b>: תהלים שם, ב."],["2609","25","<b>בענין הקניגי'</b>: ראה ויק\"ר פי\"ג, ג. סה\"מ תקס\"ב ח\"א ע' צו ואילך. מאמרי אדה\"א בראשית ע' רמד ואילך. דברים ח\"א ע' רצה. וש\"נ."],["2610","26","<b>כי אתה אבינו זה יצחק</b>: ישעי' סג, טז. שבת פט, ב. ראה גם תו\"ח לך קג, ג ובהערה 25."],["2611","27","<b>אשר בחי' הבכי'</b>: אג: בחי' הבכי' אשר."],["2612","28","<b>שהבכי' בתיקון חצות</b>: ראה גם ד\"ח שער התשובה ו, ב. ד. יג, ד. מאמרי אדה\"א במדבר ח\"ג ע' תתפז ואילך (ובהנסמן בריש המאמר שם)."],["2613","29","<b>היתה לי דמעתי</b>: תהלים מב, ד. ראה גם ד\"ח שם יג, ד."]]],[2800530227,"שלו מתקנים בחי' מקור הפגם שהוא דוקא פריקות עול מ\"ש ובחי' גלות השכינה הוא בא בדרך פרט בכל ניצוץ אלקי והדמעה הזאת תתקן ותעביר הפגם לגמרי ותעורר למעלה בחי' הבכי' שמנגד ובא מכח היפוכו שהוא החדוה העצמית הנ\"ל להאיר בנפשו האלקי' בק\"ש ותפלה כו' להיות ממש כמו לחם לנפשו כו' ולהיפוך בפריקו' עול היפך הדמעה כמו והתברך בלבבו<sup data-n=\"2614\">1</sup> בשרירות לבי אלך כו' כעבד שמורד שהמרידה ופריקו' עול עיקר ומקור לכל שיעשה נגד רצון האדון כו':\n<b>והנה</b> ע\"ז אמר אוילים מדרך פשעם<sup data-n=\"2615\">2</sup> פשעים אלו המרדים<sup data-n=\"2616\">3</sup> בפר\"ע גם שיתענו מעונותיהם בח\"נ מה יועיל כי כל אוכל דחכמה הנ\"ל תתעב נפשם<sup data-n=\"2617\">4</sup> היפך הענג שחיה תחי' לנפשו כו'. וז\"ש ויגיעו עד שערי מות<sup data-n=\"2618\">5</sup> כמ\"ש החיים והטוב<sup data-n=\"2619\">6</sup> שהוא שמחה וטוב לב בענג העצמי הנ\"ל והיפוכו מות ורע בפרק\"ע והדמע' בתקון חצות דוקא הוא עיקר ההכנה בנפשו להיות בתפלה כל ענין הנ\"ל בג' מדריגות דבכי' מסט' דא כו' וא\"ל<sup data-n=\"2620\">7</sup> יטעה א\"ע בא' מאלה או בכי' לבד וחדווה לבד או שאינם לאמיתתן ולעומקן וה\"ז סימן שלא נגה על נפשו אור האלקי רק מרחוק מאד כמו בסוד גלות השכינה בכללות נש\"י (וזהו עיקר ומקור הסיבה הכללי' לכל הנופלים תמיד ממדריגתם בעונג וחדוה האלקית בלתי מתקיימ' כלל וכלל ובמעט מונעי' מנגדי' ינתקו חבלי התקשרות מלבו לגמרי כנ\"ל כמ\"ש אוילים מדרך פשעם כו' כל אוכל כו' ולזה כל אשר קרבת אלקים יחפץ באמת יעשה הכנה רבה בנפשו תמיד בתיקון חצות ובענין בכי' מסט' דא כו' הנ\"ל ולא יטעה א\"ע לאבד את נפשו בחנם ממש וד\"ל) (ובכ\"ז יובן ג\"כ עיקר הטעם לענין הכלל הגדול בשם הה\"מ ז\"ל<sup data-n=\"2621\">8</sup> במ\"ש הטבעית שהוא כלי הכנה לעונג האמיתי במס\"נ באחד כו' ולקבלת כל רזין כו' כמ\"ש בקונטרס<sup data-n=\"2622\">9</sup> באריכות וד\"ל):\n(ז) <b>ומעתה</b> יש להקדים בתחלה וקודם להידיעה בפרטות כל ההשתלשלות ענין הנ\"ל (באות ד') בחיבור הפרט עם הכלל דוקא כו' בהיות ידוע לכל מעיין בס' הזוהר ובס' הקבל' האמיתי' בהשתלשלו' והתלבשו' הפרצופי' כו' בסדר קצר ההכרחי לכל אדם לידע מתחלה אחדות הפשוטה מריש כ\"ד עד סוף כ\"ד בסוף עולם השפל שלנו שהוא בא בחיבור וקשר א' ממש מראש לסוף ממש כשלשלת כו' שמשתלשל מעילה לעיל' כו' ואור הראשון דאח\"פ שנק' עילת כל העילת<sup data-n=\"2623\">10</sup> הוא הנק' ראשון או קדמון כמ\"ש אני ראשון ואני אחרון<sup data-n=\"2624\">11</sup> אני ראשון הוא בחי' מל' דא\"ס אחר הצמצום הראשון הנק' מק\"פ<sup data-n=\"2625\">12</sup> כו' ואני אחרון סוף הכל הוא בחי' מל' דמל' דעשי' מקור התהוות זה העולם השפל ונעוץ תחלתן בסופן וסופן בתחלתן<sup data-n=\"2626\">13</sup> והיו לאחדי' ממש כשלשלת שהאחרונה ביותר קשורה בהעליונ' ביותר וז\"ש ראו כי אני אני הוא<sup data-n=\"2627\">14</sup> בלא שינוי מראש לסוף כלל והגם שידוע שיש ריבוי פרטי השתלשלות מאד מאד מראש לסוף הנה זה כל האדם בהתבוננו' כל פרטי פרטיות מראש לסוף לחבר הכל ליחוד הכללי דאח\"פ הנק' ראשו' וכמ\"ש אני אני הוא ממש וכמ\"ש אני הוי' לא שניתי<sup data-n=\"2628\">15</sup> כו' וזהו עיקר קוטב היסוד המוסד בהתבוננות הפרט דוקא שיומשך הכל אל הכלל כנ\"ל. וביאור הדבר למתחילים הנה ידוע בדרך קצרה בסדר ריבוי השתלשלות דבחי' הקו וחוט שנמשך אחר צמצום הראשון הוא כך דבתחלה קודם הצמצו' הראשון היה הוא ושמו בלבד<sup data-n=\"2629\">16</sup> כו' דהיינו עצמיות א\"ס ב\"ה ואורו וזיוו הנק' שמו הכל היה בבחי' עצמיו' שלו בבחי' א\"ס ממש והי' ממלא את כל החלל<sup data-n=\"2630\">17</sup> כו' ואח\"כ צמצם א\"ע ונשאר",[["2614","1","<b>והתברך בלבבו</b>: נצבים כט, יח [בדילוג]."],["2615","2","<b>אוילים מדרך פשעם</b>: תהלים קז, יז."],["2616","3","<b>פשעים אלו המרדים</b>: יומא לו, ב. [אג: המורדים ? ראה גם ד\"ח שם ו, סע\"ג. מאמרי אדה\"א במדבר שם]."],["2617","4","<b>כל אוכל. . תתעב נפשם</b>: תהלים שם, יח."],["2618","5","<b>ויגיעו עד שערי מות</b>: המשך הכתוב כל אוכל."],["2619","6","<b>החיים והטוב</b>: נצבים ל, טו [ושם: ואת הטוב]."],["2620","7","<b>וא\"ל</b>: ג: ואם לא."],["2621","8","<b>הכלל הגדול בשם הה\"מ ז\"ל</b>: ראה מאמרי אדה\"א קונטרסים ע' קסח ואילך."],["2622","9","<b>בקונטרס</b>: אג: ניתוסף: הראשון ? והכוונה לקונט' ההתפעלות. ראה לעיל קט, א הערה 2."],["2623","10","<b>עילת כל העילת</b>: ראה זהר בראשית כב, ב. פרדס (שער אם הא\"ס הוא הכתר) ש\"ג פ\"א. לקמן קכב, ב. קעג, ד."],["2624","11","<b>אני ראשון ואני אחרון</b>: ישעי' מד, ו. ראה גם לקמן קמו, א. לעיל מח, א. שע\"ת קיד, ב. קמו, א. מאמרי אדה\"א בראשית ע' תל."],["2625","12","<b>הצמצום הראשון הנק' מק\"פ</b>: ראה ע\"ח (דרוש עגו\"י) ש\"א ענף ב."],["2626","13","<b>ונעוץ תחלתן. . בתחלתן</b>: ראה ס\"י פ\"א מ\"ז."],["2627","14","<b>ראו כי אני אני הוא</b>: האזינו לב, ט [בדילוג]."],["2628","15","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו."],["2629","16","<b>היה הוא ושמו בלבד</b>: נסמן לעיל יב, א."],["2630","17","<b>ממלא את כל החלל</b>: בע\"ח שם: ממלא כל המציאות. אבל עד\"ז מובא בכ\"מ ומהם: מאמרי אדה\"ז תקס\"ב ח\"א ע' רפב. תקס\"ז ע' רמ. פרשיות התורה ח\"ב ע' תרכד. ענינים ע' רפו. שיג. שיח. שסב. תכג. כתובים ח\"א ע' קפט. ד\"מ לד, א. שע\"ת ח\"א כו, א. ל, ג. מאמרי אדה\"א ויקרא ח\"ב ע' תתפח. תתקכא. במדבר ח\"ג ע' א'עט. דברים ח\"א ע' שמז. קונטרסים ע' תכג. וראה לקמן קעה, ד. קעז, רע\"א. ד\"ה בחודש השלישי תשל\"ג סה\"מ תשל\"ג (ברוקלין תשמ\"ט) ע' 343."]]],[2800530228,"בחי' רשימו<sup data-n=\"2631\">18</sup> מן הצמצום שבחלל זה ומרושם זה נמשך בחי' הקו\"ח<sup data-n=\"2632\">19</sup> בבחי' מקיף ופנימי כו' ונקר' אא\"ס שלפני הצמצום בשם טה\"ע<sup data-n=\"2633\">20</sup> ובחי' מקיף הכללי דקו זה בראשיתו נק' טה\"ת<sup data-n=\"2634\">21</sup> כידוע ואח\"כ נמשך ע\"י צמצום מל' דא\"ס להיות כתר דא\"ק<sup data-n=\"2635\">22</sup> וממל' דא\"ק נעשה כתר לע\"י וא\"א<sup data-n=\"2636\">23</sup> וממל' דא\"א נעשה כתר לאו\"א וממל' דאו\"א נעשה כתר לז\"א ומז\"א לנוק' עד שממל' דאצי' נעשה כתר לבריאה<sup data-n=\"2637\">24</sup> וכך מבריאה ליצי' ומיצי' לעשי'<sup data-n=\"2638\">25</sup> עד בחי' מל' שבמל' דעשיי' סוף הכל כו' ונמצא סוף הכל שהוא מל' דמל' דעשי' נעוץ בתחלת הכל שהוא בחי' מל' דא\"ס שמתצמצם להיות כתר לא\"ק כמ\"ש בע\"ח בהתחלתו בשער הכללי' והיינו אני ראשון ואני אחרון כנ\"ל (משא\"כ בחי' עצמות אא\"ס שלפני הצמצום לא נקרא עדיין גם בשם תחלה וסוף כי הרי הוא בחינת אור עצמותו עדיין כמו שהוא טרם שנמשך בשביל השפע' למטה כמ\"ש אתה קדוש ושמך קדוש<sup data-n=\"2639\">26</sup> כו' כידוע) והנה אחר היחוד בהתבוננות היטב בכל פרטי ההשתלשלות מריש כ\"ד שהוא מל' דא\"ס עד מל' דעשי' דוקא אזי יומשך הכל אל המקור הראשון שהוא בחי' עצמיות אור א\"ס שלפני הצמצו' והיינו כוונה כללי' דפ' ראשון ביחו\"ע<sup data-n=\"2640\">27</sup> דק\"ש ה' אחד אח\"פ ממש שלפני הצמצום הראשון שע\"ז אמר בס\"י לפני א' מה אתה סופר<sup data-n=\"2641\">28</sup> למעלה מי\"ס כו' וכמאמר אנת הוא חד ולא בחושבן<sup data-n=\"2642\">29</sup> י\"ס כו' וכידוע וכוונה כללית דבשכמל\"ו ביחו\"ת<sup data-n=\"2643\">30</sup> הוא בחי' מל' דא\"ס אחר הצמצום שע\"ז אמר מלכותך מכ\"ע<sup data-n=\"2644\">31</sup> עד מל' דעשי' שהוא ענין אני ראשון ואני אחרון הנ\"ל וכל יחוד וחיבור דראש לסוף זה אחר ההתבוננ' בפרטיו' רבות שביניהם אינו רק כמו פרט א' לגבי בחי' הכלל הכוללם יחד שהוא בחי' מקיף הכללי דעגול שמקיף לקו וגם הוא פרט א' יחשב לגבי עצמיו' אור א\"ס שלפני הצמצום שנק' טה\"ע שלמעלה מהיו' גם בחי' כלל לפרט מאחר שנק' קדוש ומובדל בבחי' העצמיות וזהו פי' יחיד חי העולמי'<sup data-n=\"2645\">32</sup> מבחי' יחיד זה נמשך ע\"י צמצום הראשון הנ\"ל להיות נק' חי כל העולמי' דאבי\"ע שבקו בבחי' מקיף ופנימי כו' וכידוע וד\"ל. ואחר שיבואר לאדם ביאור כל פרט בסדר השתלשלו' זאת הצריך לכל אדם לידע ולקבוע בנפשו הנה תמיד כל ימי חייו ירגיל מוחו ולבו אחר טוב ידיעתו ורגילותו תמיד בכל פרטיהם דוקא לעשות הקיצור מן האריכות מראש לסוף יחד עד שברגע א' ממש בהתבונן בנפשו בסוף הכל שהוא השגו' איכות התהוו' יש מאין הגשם דגלגלי' וד' יסודו' הגשמיי' וכל פרטי עוה\"ז השפל כמ\"ש שאו מרו' עיניכ'<sup data-n=\"2646\">33</sup> בראי' גשמיי' וראו מי ברא אלה בגשמיו' התהוות' ליש גמור ממש בצמצו' היות' אחרון שבזה ממש שורה בבחי' א\"ס דוקא מבחי' תחלת הכל שהוא בחי' מל' דא\"ס שלפני מקור האצי' וע\"כ לא נזכר בכל ס' תהלים בשבחי גדולת ה' רק בדרך פשוט בגדולות ונפלאות מעשה ה' בשמים וארץ וכל צבאם הגשמיי' דוקא ולא נזכר שבחי גדולתו בעולמות העליונים רוחניים עד רום המעלות שלפני האצי' כו' מפני שנעוץ תחלתן בסופן דוקא כנ\"ל וכמ\"ש אני אני הוא ממש וכו' ועצמיות אא\"ס הוא הסובב כו' וד\"ל. וזהו אמיתית המכוון בהתבוננות בפרט כנ\"ל (וגם שלפי החשבון בפרטי ההשתלשלות רחוק מאד מאד מראש לסוף אבל באמת קרוב מאד בלי הפסק והסתר כלל באמצע וכמ\"ש אני אני הוא ומבלעדי באמצעיתא<sup data-n=\"2647\">34</sup> כו' וד\"ל) (וכמ\"ש כי האלקים עשה את האדם קדמא' ראשי' הקו ישר<sup data-n=\"2648\">35</sup> מראשו לסופו עד עקב דא\"ק שמסתיים בסוף העשי' בבחי' יושר שהוא ההתכללות גמור מראשו לסופו והמה בקשו חשבונות",[["2631","18","<b>ונשאר בחי' רשימו</b>: ראה עמה\"מ שער (א) שעשועי המלך בתחלתו."],["2632","19","<b>ומרושם זה. . הקו\"ח</b>: ראה מאמרי אדה\"א קונטרסים ע' ח. וש\"נ. אמ\"ב שער הק\"ש כא, ד. תו\"ח נח עה, ד ואילך ובהערה 42."],["2633","20","<b>אא\"ס. . טה\"ע</b>: ראה גם הנסמן בשע\"ת קח, ד."],["2634","21","<b>מקיף. . דקו. . טה\"ת</b>: ראה גם לקמן קכא, סע\"א. שע\"ת ח\"א ל, ד. אמ\"ב שער הק\"ש כא, ד."],["2635","22","<b>מל' דא\"ס להיות כתר דא\"ק</b>: ראה בסמוך בפנים ולקמן קכג, סע\"א בשם ע\"ח בהתחלתו בשער הכללים. אמ\"ב שער הק\"ש כא, א. מאמרי אדה\"א קונטרסים ע' תכה. וש\"נ. דברים ח\"ג ע' תתפט. וש\"נ."],["2636","23","<b>ומל' דא\"ק. . לע\"י וא\"א</b>: ראה ע\"ח (שער סדר אצי') ש\"ג פ\"א. הנסמן בתו\"ח נח סו, ב הערה 18."],["2637","24","<b>שממל' דאצי'. . לבריאה</b>: ראה ע\"ח (שער העקודים) ש\"ו פ\"ב."],["2638","25","<b>מבריאה ליצי' ומיצי' לעשי'</b>: נסמן לקמן קמה, ב."],["2639","26","<b>אתה קדוש ושמך קדוש</b>: תפלת העמידה."],["2640","27","<b>דפ' ראשון ביחו\"ע</b>: ואתחנן ו, ד. זהר בראשית יח, ב."],["2641","28","<b>לפני א' מה אתה סופר</b>: ראה ס\"י פ\"א מ\"ז."],["2642","29","<b>אנת הוא חד ולא בחושבן</b>: ת\"ז בהקדמה (יז, א)."],["2643","30","<b>דבשכמל\"ו ביחו\"ת</b>: פסחים נו, א. זהר בראשית יח, ב."],["2644","31","<b>מלכותך מכ\"ע</b>: תהלים קמה, יג."],["2645","32","<b>יחיד חי העולמי'</b>: נוסח ברכת ברוך שאמר וישתבח. ראה גם לעיל נו, ב."],["2646","33","<b>שאו מרו' עיניכ'</b>: ישעי' מ, כו."],["2647","34","<b>ומבלעדי באמצעיתא</b>: ראה ת\"ז ת\"ע (קכ, סע\"א). שע\"ת קמו, א ובהנסמן במ\"מ שם."],["2648","35","<b>כי האלקים עשה את האדם. . ישר</b>: קהלת ז, כט [ושם: אשר עשה האלקים ? ראה הנסמן לעיל סז, ב]."]]],[2800530229,"רבים בבחי' העגולים כו' בפירוד והתחלקות זה למעל' מזה כו') ויובן כל הנ\"ל בדרך קצרה מאד בבחי' הכתרים שבכל עולם שאין בכתרים בחי' השתלשלות עו\"ע בריחוק המדרגה<sup data-n=\"2649\">1</sup> כלל כמו בחי' הרצון הפשוט שבעצמיות אא\"ס כמ\"ש כשעלה ברצונו הפשוט<sup data-n=\"2650\">2</sup> כו' בחי' מל' דא\"ס עצמה כשעלה במח' הפשוטה אנא אמלוך<sup data-n=\"2651\">3</sup> כו' שהוא למעלה מרצון להאציל או לברוא כו' רק בחי' היולי עדיין וממנו נתצמצם תחלה בחי' רצון הקדום שנק' כתר לא\"ק ואח\"כ הרצון להאציל בחי' כתר דאצי' בכלל ואח\"כ הרצון לברוא בחי' כתר שבמל' דבריאה ואח\"כ כתר מל' דיצי' כו' עד כתר מל' דעשי' הרצון לעשות וכמ\"ש כל אשר חפץ ה' עשה<sup data-n=\"2652\">4</sup> כו' ומהו ההפרש באדם התחתון בבחי' רצונו ועצמותו ההיולי שהיה כלול בו ד' רצונו' כמו רצון לעצמות גופו לרצון לפעול ולעשות היותר אחרון הכל משרש ומקור א' יצא כו' כך אין הפרש ממש בין בחי' רצונו הפשוט שנמשך להיות רצון להאציל לבחי' רצונו הפשוט שנמשך להיות חפץ ה' בכל אשר עשה בסוף עולם העשיה שלנו כו' וד\"ל:\n(ח) <b>וכך</b> עד\"ז שבבחי' הכתר יש יחוד כל פרטיהם אל הכלל עד בחי' הרצון הפשוט שבעצמיות אא\"ס ממש כנ\"ל כך יוכל האדם להתבונן גם בבחי' החכמה שבכל עולם מראש לסוף והוא מ\"ש בראשית ברא<sup data-n=\"2653\">5</sup> כו' ות\"י בחוכמתא וא\"ת בקדמין ברא שהוא בחי' הכתר<sup data-n=\"2654\">6</sup> שנק' קדמון להיותו בבחי' העצמיות שמקודם לחכמה כי החכמה מאין תמצא<sup data-n=\"2655\">7</sup> ולא בחי' אין ממש משא\"כ הרצון כו' אבל כמו שהרצון נתצמצם מן העצמות עד שמתלבש בעשי' להיות כל אשר חפץ עשה כנ\"ל כך בחי' החכמה מתצמצמת מן העצמות שנק' שם חכמה הקדומה או חכמה הפשוטה באחדות פשוט כו' ומשם נמשך מלמעלה למטה בכל עולם ועולם דאבי\"ע עד בחי' חכמה שבמל' דמלכות דעשיי' שע\"ז נאמר כולם בחכמה עשית<sup data-n=\"2656\">8</sup> כי כמ\"ש בראשית בחוכמתא ברא כך בחכמה יצר ועשה כמו ברצון שברא ויצר ועשה הכל ברצון א' רק שנשתלשל וירד מעולם הבריאה לעולם היצי' ומעולם היצי' לעשיה ביריד' מדריגות עו\"ע כמו ממל' דכתר דבריא' נעשה כתר ליציר' כו' כך בחכמה א' ברא ויצר ועשה רק שירד ונשתלשל מבריא' ליצי' כו' דהיינו שנמשך מבחי' מל' שבחכמה דבריאה לחכמה שבמל' דיצי' ועד\"ז מיצי' לעשי' עד חכמה שבמל' דעשי' שעז\"א כולם בחכמה עשית וכן ה' בחכמה יסד ארץ<sup data-n=\"2657\">9</sup> וכה\"ג (והגם שדרך פרט הרי משתלשל מבחי' מל' דמל' דבריא' להיות כתר ליצי' והחכמה דיצי' ממל' דכתר דיצי' מ\"מ דרך כלל כל בחי' עו\"ע מעולם לעולם נמשך מזה לזה שלא ע\"י צמצום רבוי הממוצעי' שביניהם כמו וה' נתן חכמה לשלמה<sup data-n=\"2658\">10</sup> שהיה בעולם העשי' הרי נמשך השפעה זו מחכמה שבעצמיות אא\"ס לחכמה דא\"ק ומחכ' דא\"ק לח\"ס דע\"י וא\"א ומשם לאור אבא דאצי' עד בחי' חכמה שבמל' דאצי' ומשם לחכמה שבמל' דבריאה וכן עד\"ז מבריאה ליצי' ומיצי' לעשי' עד שבא האור ושפע חכמה אלקית הזאת בנשמת שלמה מחכמה שבמל' דעשי' וכן בהיכל ק\"ק שבבהמ\"ק האיר מכתר וחכמ' שבעצמיו' עד בחי' כתר וחכמ' שבהיכל ק\"ק דעשי' בלוחות וארון גשמי' שהיו עומדי' בהיכל ק\"ק הבנוי למטה היה שורה מכו\"ח דהיכל ק\"ק דעשי' הרוחניות כו' (וכך אנו מבקשים אתה חונן לאדם דעת כו' וחננו מאתך<sup data-n=\"2659\">11</sup> דוקא כו' וד\"ל) (ועד\"מ<sup data-n=\"2660\">12</sup> הנה יובן באדם התחתון כמו שחכמתו העצמיו' ההיולית כולל כל הסתעפות התפשטו' אור חכמתו עד לחוץ",[["2649","1","<b>שאין בכתרים. . בריחוק המדרגה</b>: ראה גם מאמרי אדה\"ז אתהלך לאזניא ע' נד. סה\"מ תש\"ג ע' 112. וש\"נ."],["2650","2","<b>כשעלה ברצונו הפשוט</b>: להלן פי\"א מציין: בע\"ח בהקדמה ? ראה ע\"ח (דרוש עגו\"י) ש\"א ענף ב. הערה במאמרי אדה\"א דברים ח\"ב ע' תקפז. מעין החכמה רפ\"א."],["2651","3","<b>אנא אמלוך</b>: ראה סה\"מ תקס\"ח ח\"א ע' ז: ?וכמ\"ש בזהר בפי' וימלוך אנא אמלוך\" הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתצד."],["2652","4","<b>כל אשר חפץ ה' עשה</b>: תהלים קלה, ו."],["2653","5","<b>בראשית ברא</b>: בראשית א, א."],["2654","6","<b>וא\"ת בקדמין. . כתר</b>: ראה גם לקמן קלט, ב. תו\"ח בראשית ז, ג ואילך. רקאנטי ר\"פ בראשית."],["2655","7","<b>החכמה מאין תמצא</b>: איוב כח, יב. ראה גם מאמרי אדה\"א בראשית ע' ד. וש\"נ."],["2656","8","<b>כולם בחכמה עשית</b>: תהלים קד, כד."],["2657","9","<b>ה' בחכמה יסד ארץ</b>: משלי ג, יט."],["2658","10","<b>וה' נתן חכמה לשלמה</b>: מלכים-א ה, כו."],["2659","11","<b>אתה חונן. . וחננו מאתך</b>: תפלת שמו\"ע. וחננו ? ראה לעיל לא, ב. סידור יעבץ."],["2660","12","<b>ועד\"מ</b>: אג: ועד\"ז."]]],[2800530230,"מעצמות שלו לגמרי והוא עד שכל המלובש בעשי' גשמי' נבדלת לגמרי ואין הפרש אצלו בין התפשטו' חכמתו העצמיו' בעצם שכלו להשכיל עיון שכלי להתפשטו' שלה בעשי' נבדלת שהכל נק' בשם התחכמו' א' אלא שזה ברוחניות ובעצמותו יותר ובעשי' בא בדבר נבדל עד שלגבי בחי' העצמות ממש הרי הכל רק התחכמו' א' רק שהולכת ומתפשטת מעיון שכלו למדותיו ולמחשבתו עד שעושה ממש בחכמתו זו כמו בהתחכמו' בעסק מו\"מ כו') וכמו ויאמר אלקי' יהי אור שבדיבור ובא לידי מעש' כמ\"ש ויהי אור<sup data-n=\"2661\">13</sup> הרי התחלתו מבחי' חכמתו העצמי' שבעצמיות המאציל שהאציל האור ואח\"כ ברא ויצר ועשה כו' וכך הוא בכל פרטי התהוות הנאצלי' והנבראים והנוצרים והנעשי' מעצמות הא\"ס כו' כולם מיוחדים ומקושרים כל פרטיהם בעצמיות אא\"ס שבאבי\"ע ואין הפרש לגבי עצמו בין ראשון לאחרון כלל וא\"כ מ\"ש אני ראשון ואני אחרון קאי גם בבחי' החכמ' שבראש האצי' עד חכמה שבסוף העשיה כו' וכן יובן עד\"ז דרך פרט בחי' יחוד כללי בבחי' המדות ומחדו\"מ שבכל עולם מד' עולמות דאבי\"ע שמדות דאצי' מתלבשי' במדות דבריאה ומדות דבריאה במדות דיצי' ומדות דיצי' במדות דעשי' עד שבחי' ו\"ק דעשי' נעוץ בתחלת הכל במדותיו העצמיים שלפני האצי' שעז\"א המתנשא מימות עולם כידוע והם בחי' ז\"ת דע\"י עד ז\"ת דא\"ק עד מדות שבאא\"ס עצמו הגנוזות בעצמות שלו ממש כמו בחי' חסד שבאא\"ס עצמו שעז\"א חסדי ה' כי לא תמנו<sup data-n=\"2662\">14</sup> כו' בבחי' א\"ס ממש אנו אומרים יהי חסדך זה עלינו<sup data-n=\"2663\">15</sup> ממש בבחי' חסד מצומצם שבמדות דמל' דמל' דעשי' שמאיר בעוה\"ז כו' וכן מבחי' מח' שבעצמותו נמשך עד בחי' מח' דמל' דעשי' אשר חושב לעשות בפו\"מ וכן בדו\"מ כו' כי כמו שכל אשר חפץ ברצון העצמו' עוש' כך כל אשר חפץ ברצונו העצמי חושב כו' רק שיורד ונמשך בהשתלשלות עד חפצו ורצונו ושכלו ומחשבתו בעשי' בפו\"מ כו' אבל הכל רק רצון ושכל ומדה ומח' ומעשה א' תחשב לגבי בחי' העצמו' ממש כמובן מכל הנ\"ל וד\"ל. ואחכ\"ז הרי ישכיל האדם בהתבוננותו במי ברא אלה בגשמיות איך שלא נבדל גם הפרט היותר אחרון מהמקור הכללי היותר ראשון גם בכל פרט שבכל דבר ודבר כמו בבריאת שמים או ארץ או כל פרטי חלקי דצח\"מ איך ששרשם ברוחני' דמל' דעשי' עד רום המעלות אחוז וקשור כשלשלת כו' וכמ\"ש בראשי' ברא בקדמין ובחוכמתא כו' הרי בחי' כתר וחכמה שבאבי\"ע מיוחדי' כך כל פרטיהם המסתעפי' מהם במדות ובמדו\"מ שבכל עולם (שהוא כללות ע\"ס דכל עולם שהוא ע\"י וא\"א ואו\"א וזו\"נ דאבי\"ע) עד בחי' עשי' דמל' דעשי' נעוץ סופן בתחלת הכל דכמו שבקדמון האציל כו' כך בקדמון זה עצמו ברא ויצר ועש' כמ\"ש כל אשר חפץ כו' וכך במדות כמו הנה מקום אתי בחי' ביטול הו\"ק לך הוי' הגדולה בכל עולם לפי מה שהוא עד בחי' מקום העצמי שנק' מקומו וכמאמרז\"ל הוא מקומו של עולם<sup data-n=\"2664\">16</sup> ואין העולם מקומו וכן מאמר הידוע דאיהו תפיס בכל עלמין<sup data-n=\"2665\">17</sup> ולית מאן דתפיס בי' אפי' מח' ורצון הקדום כו' ומכ\"ז הרי יובן בחי' יחוד וחיבור הפרט אל הכלל דרך כללות הכל מעצמיו' אור א\"ס באבי\"ע מלבד בחי' היחוד שבכל עולם דרך פרט בע\"ס שבו כו' אך אעפ\"י שיודע האדם כל ביאור ההשתלשלות דאבי\"ע בפרט ימשוך נפשו ליחוד הפרט אל היחוד בכלל עד עצמיות אא\"ס ממש ע\"ד הנ\"ל וכה\"ג מלבד היחוד וביטול כל עולם בפרט לגבי העצמו' כו' עד שיבוא לו כל ההתבוננו' שמרחיב בפרט",[["2661","13","<b>ויאמר אלקי'. . ויהי אור</b>: בראשית א, ג."],["2662","14","<b>חסדי ה' כי לא תמנו</b>: איכה ג, כב."],["2663","15","<b>יהי חסדך. . עלינו</b>: תהלים לג, כב [בדילוג]."],["2664","16","<b>הוא מקומו של עולם</b>: ראה ב\"ר פס\"ח, ט. הנסמן בתו\"ח בראשית מג, א הערה 2."],["2665","17","<b>דאיהו תפיס בכל עלמין</b>: ראה זהר (רע\"מ) פינחס רכה, א. הנסמן במאמרי אדה\"א דברים ח\"א ע' קפב. תו\"ח נח סו, ג הערה 30. לעיל כ, א."]]],[2800530231,"בענין זה בקיצור מופלג כמו מלכותך מכ\"ע שזהו בחי' מל' דא\"ס במל' דמל' דעשי' ע\"ד הנ\"ל ברצון וחכמה ומדות כו' כמ\"ש ראו כי אני אני הוא ממש וכן אני הוי' לא שניתי בחי' אני הוא בחי' מל' שהוא בחי' אין דכתר דנעוץ תחלתן בסופן בכל עולם בפרט וכן דרך כללות הכל ולזה או' אני הוי' לא שניתי בין מל' דא\"ס למל' דעשי' כלל וז\"ש מלכותך הוא מלכות כל עולמים עד מלכות דמלכות דעשיה מטעם כל הנ\"ל וד\"ל:\n(ט) <b>אך</b> הנה לכאורה אינו מובן מה שאמר אני הוי' לא שניתי שזה מדבר במל' דא\"ס עצמו הרי אם בבחי' מל' דעשי' יש בו שינוי בין דין לחסד שהוא בחי' התפעלות כו' מוכרח שגם במל' דא\"ס יש שינוי זה מאחר שאמר אני אני הוא כו' כנ\"ל וכן מלכותך מכ\"ע בשוה ממש כנ\"ל דהיינו כאשר עולה ברצונו הפשוט שבעצמות ממש להיות חפץ חסד הרי חפץ חסד העצמי הזה יורד עד למט' ממש בחפץ חסד דמל' דעשי' וכן להיפך כפי המובן מכל הנ\"ל וגם הרי בכ\"י מחדש מע\"ב למטה מטה שהוא בקדמין ובחוכמתא דבראשית ברא עד רום המעלות בעצמותו ממש א\"כ יש בחי' חידוש גם בעצמיו' אא\"ס ואיך אמר אני לא שניתי כלל וכן אנו או' אתה הוא קודם שנבה\"ע<sup data-n=\"2666\">1</sup> כו' וכמ\"כ קודם שהאציל<sup data-n=\"2667\">2</sup> כו' וכידוע ועד\"מ מאדם התחתון הרי יש שינוי גם ברצון העצמי מרצון של דין לרצון של חסד וכידוע ואיך א\"א<sup data-n=\"2668\">3</sup> יהי ר\"מ רצון חדש<sup data-n=\"2669\">4</sup> שיתהפך רצון של דין לחסד כו' ואנו רואין שנויי' רבים בכל יום ושעה כו' בכל אשר חפץ עשה תמיד בשמים ובארץ כו'. והתירוץ לכל זה הוא ענין הצמצום כידוע דאם היה השפע דרך עילה ועלול הי' נופל ענין שינוי התפעלות<sup data-n=\"2670\">5</sup> כו' אבל מאחר שההמשכ' בבחי' אור וזיו לבד וגם הוא ע\"י צמצו' ע\"כ אין בעצמו' אלקו' שום שינוי כלל גם במל' דמל' דעשי' וכך הוא עד רום המעלות ואחר הצמצום יש בחי' שינוי וזהו מצד המקבלים לבד כידוע. וביאור ענין ההפרש בין אור לשפע<sup data-n=\"2671\">6</sup> ידוע לכל ואמנם גם בבחי' אור הוצרך להיות ע\"י צמצום וע\"כ צריך כל אדם לידע ענין הצמצום ולהתבונן בו בכל עולם לפי ערכו כי הוא העיקר בכלל היחוד האלקי באין שינוי לגבי העצמות וכמו קמי' כחשיכה כאורה<sup data-n=\"2672\">7</sup> רוחניות וגשמיות שוין עד אצי' ועשי' שוין<sup data-n=\"2673\">8</sup> כידוע הגם שזהו לגבי בחי' המקיף בלבד הנק' סוכ\"ע בכלל ופרט שלמעל' מהדרג' האור שבבחי' ממכ\"ע כידוע אך הנה גם בבחי' או\"פ בחי' ממלא בכלל ובפרט אין שינוי כו' ועליון ותחתון שבו שוין כמ\"ש אני לא שניתי ואני הוא בחי' ממלא כידוע וכן מ\"ש את השמים ואת הארץ<sup data-n=\"2674\">9</sup> אני מלא בהשווא' אחת דווקא מלא זה ג\"כ בבחי' או\"פ וכמאמר לית אתר פנוי מיני'<sup data-n=\"2675\">10</sup> כידוע והיינו משום דגם בבחי' ממלא בא ירידת האור והשפע ע\"י צמצומים דוקא וכידוע דגם בבחי' הקו\"ח שנמשך מעצמות אא\"ס שנק' ממכ\"ע דאבי\"ע בכלל הרי הוא נמשך ע\"י צמצום בתחל' בעצמות והוא צמצום הראשון הנק' מק\"פ וחלל ריקן כו' כמ\"ש בע\"ח<sup data-n=\"2676\">11</sup> וכן בירידת הקו למטה בבחי' עגולים ויושר כו' עד שנעשה בחי' כתר לא\"ק הוא ע\"י צמצום<sup data-n=\"2677\">12</sup> וכן מא\"ק לע\"י וא\"א<sup data-n=\"2678\">13</sup> כו' וגם באצי' עצמו יש מסך בין כתר לחכמ' בכלל והוא מ\"ש והבדיל' הפרוכת פרסא<sup data-n=\"2679\">15</sup> בין<sup data-n=\"2680\">14</sup> כו' כמ\"ש בזוהר וכן מאו\"א לז\"א<sup data-n=\"2681\">16</sup> ומז\"א לנוק' כידוע וממל' דאצי' לבריא' יש מסך<sup data-n=\"2682\">17</sup> והמל' בוקע המסך<sup data-n=\"2683\">18</sup> ונעש' כתר לבריא' ועד\"ז יש מסך בין בריא' ליציר'<sup data-n=\"2684\">19</sup> ומל' דבריא' בוקע המסך ונעש' כתר ליצי'<sup data-n=\"2685\">20</sup> וכן מל' דיצי'<sup data-n=\"2686\">21</sup> בוקע המסך ונעש' כתר",[["2666","1","<b>אתה הוא קודם שנבה\"ע</b>: ראה תפלת השחר. של\"ה ג, ב. וראה גם מאמרי אדה\"ז על מארז\"ל ע' שלו. מאמרי אדה\"א בראשית ע' תקסג. הנחות תקע\"ז ע' רלג. תו\"ח ויצא קסג, ג."],["2667","2","<b>קודם שהאציל</b>: ראה עבודת הקודש (לר\"מ בן גבאי) חלק היחוד פ\"ב."],["2668","3","<b>א\"א</b>: אג: אנו אומרים."],["2669","4","<b>יהי ר\"מ </b>[רצון מלפניך]<b> רצון חדש</b>: ברכות השחר. ועוד. ראה שערי אורה ? לר\"י גיקטלייא ? ש\"ט [ירושלים תש\"ך צה, א]. סידור שער החנוכה רעג, ב. סה\"מ תקס\"ח ח\"א ע' מד. מאמרי אדה\"א שמות ח\"ב ע' תקפג. וש\"נ."],["2670","5","<b>התפעלות</b>: אג: והתפעלות."],["2671","6","<b>ההפרש בין אור לשפע</b>: ראה מאמרי אדה\"ז תקס\"ב ח\"א ע' קעח ואילך. ע' רסו. ח\"ב ע' שע. תקס\"ג ח\"א ע' שלה. נביאים ע' רסו ואילך. אוה\"ת ענינים ע' קי ואילך."],["2672","7","<b>כחשיכה כאורה</b>: תהלים קלט, יב."],["2673","8","<b>רוחניות וגשמיות. . אצי' ועשי' שוין</b>: ראה גם שע\"ת יד, ג ובהנסמן לשם."],["2674","9","<b>את השמים ואת הארץ</b>: ירמי' כג, כד."],["2675","10","<b>לית אתר פנוי מיני'</b>: ראה ת\"ז תנ\"ז (צא, ב). שם ת\"ע (קכב, ב). האמונות והדיעות לרס\"ג מאמר ב פי\"ג. לקו\"ת ויקרא (הוספות) נב, ג."],["2676","11","<b>צמצום הראשון. . בע\"ח</b>: ראה ע\"ח (דרוש עגו\"י) ש\"א ענף ב."],["2677","12","<b>הקו. . כתר לא\"ק. . צמצום</b>: ראה גם לעיל קיד, ב. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' קנז."],["2678","13","<b>מא\"ק לע\"י וא\"א</b>: ראה גם מאמרי אדה\"ז שם."],["2679","15","<b>הפרוכת פרסא</b>: ראה גם הנסמן במאמרי אדה\"א דברים ח\"א ע' קס."],["2680","14","<b>והבדיל' הפרוכת. . בין</b>: תרומה כו, לג. ראה גם בשם הזהר מאמרי אדה\"א דרושי חתונה ח\"ב ע' תקלו. וש\"נ. שמות ח\"א ע' מב. וש\"נ."],["2681","16","<b>מאו\"א לז\"א</b>: ראה ע\"ח (שער דרושי נקודות) ש\"ח פ\"ב. סידור שחרית סג, ג."],["2682","17","<b>דאצי' לבריא' יש מסך</b>: ראה ע\"ח (שער דרושי אבי\"ע) שמ\"ב פ\"ד. מאמרי אדה\"א דברים ח\"ג ע' תתפא. וש\"נ."],["2683","18","<b>והמל' בוקע המסך</b>: ראה ע\"ח שם פי\"ג. הנסמן במאמרי אדה\"א דברים שם."],["2684","19","<b>מסך בין בריא' ליציר'</b>: ראה ע\"ח שם פי\"ג. פי\"ד. תו\"א לך יב, סע\"ג."],["2685","20","<b>ומל' דבריא'. . כתר ליצי'</b>: נסמן לקמן קמה, ב."],["2686","21","<b>דיצי'. . המסך. . לעשי'</b>: ראה ע\"ח שם."]]],[2800530232,"לעשי' עד מל' דעשי' שנק' המלך המרומם לבדו כו' כמאמרז\"ל כברייתו של עולם<sup data-n=\"2687\">22</sup> ברישא חשוכא והדר נהורא וכן משאמרז\"ל בתחלה עלה במח'<sup data-n=\"2688\">23</sup> לברוא במה\"ד שהוא בחי' הצמצום דשם אלקי' שבמל' דעשי' כמ\"ש בראשית ברא אלקי' בחוכמת' בקדמין רצון וחכמ' דמל' דעשי' וכו' וד\"ל:\n<b>ועפ\"ז</b> יתורץ הכל דמ\"ש אני הוי' לא שניתי בין רצון של חסד או דין בכל עולם דאבי\"ע היינו כמו שהוא קודם הצמצום ומסך שבוקע בו ונעש' כתר לעולם התחתון וע\"ז אמר י\"ר מלפניך דייקא וכל בחי' מעל' ומטה שבעולם זה שוין כו' אבל אחר הצמצום נמשך הרצון בחכמ' ומדות בשינויים עד מל' דעשי' אומרים יהי רצון מלפניך בשינוי לענין עשי' בפו\"מ מדין לחסד וכה\"ג וד\"ל:\n(י) <b>ומעתה</b> הנה יש להבין דרך פרט בכל ד' עולמות דאבי\"ע דהיינו בכל פרטי ענין ע\"ס דאבי\"ע או\"כ והתלבשותן זב\"ז בכל פרטיהן גם בכל ספי' שמתחלקת לפרטי פרטיות כמו גם בבחי' חסד דמל' שבחכמ' שבמל' דחסד וכה\"ג וענין יחודם והתכללותם בבחי' הכתר שבכל עולם שהוא בחי' הממוצע<sup data-n=\"2689\">24</sup> בין עולם העליון לתחתון הימנו כידוע הכלל דרך קיצור שמבחי' מל' שבעליון נעשה כתר לתחתון<sup data-n=\"2690\">25</sup> עד רום המעלות. אך הנה מתחל' יש לכל מתבונן להתבונן במקור הראשון הנק' מקורא דכולא<sup data-n=\"2691\">26</sup> שהוא בבחי' עצמות אא\"ס שלפני הצמצום הנק' מקום פנוי הנ\"ל גם שם דרך פרט דוקא והוא הנק' מאריך באחד<sup data-n=\"2692\">27</sup> באחדו' הפשוטה דוקא ונחלק לג' מדריגות דרך כלל ובכל א' כלול מי\"ס והוא יחיד ואחד<sup data-n=\"2693\">28</sup> וקדמון והכל בבחי' עצמות אא\"ס שלפני הצמצום הראשון הנ\"ל בחי' יחיד משמעו לבדו ממש והוא למעל' מהתאחדות נפרדי' שנק' אחד<sup data-n=\"2694\">29</sup> כידוע ולפ\"ז בבחי' העצמות ממש לא יתכן לומר עדיין ענין ע\"ס כלל וכמו מל' דא\"ס שממילא מובן שקדם לזה בחי' כתר וחכמ' כו' ובאמת גם בבחי' העצמות דאא\"ס שנק' לבדו כלול בעצמו י\"ס אך שנק' חכי' ולא בחכמ' ידיעא כידוע עד ולאו מכל אלין מדות כלל<sup data-n=\"2695\">30</sup>. והענין הוא דבאמת כמו שעצמות הא\"ס הוא אור פשוט בתכלית הפשיטו' כך ממש בחי' אורו וזיוו הנק' אא\"ס דהיינו הוא ושמו בלבד כנ\"ל והוא הנק' טה\"ע שזהו ענין ובחי' התגלו' אור עצמותו כמו שהוא דוק' והוא הנק' יחיד שאין עוד מלבדו לומר בו לשון התאחדות או לשון יחוד וזהו אנת הוא חד<sup data-n=\"2696\">31</sup> ולא בחושבן י' כו'. אך מה שאמרו חכים ולא בחכמה ידיעא כו' שיש עכ\"פ חלוקי מדריגות חכים ומבין חסדן ורחמן כו' הכל לא מצד עצמותו רק מצד מה ששיער בעצמו בכח מה שעתיד להיות בפועל אחר הצמצום הראשון הנ\"ל (וכמ\"ש במק\"מ<sup data-n=\"2697\">32</sup> בל' האריז\"ל עצמו ומבואר במ\"א באריכות) וזהו ענין כללות המאמר הראשון שבזוהר בריש הורמנא<sup data-n=\"2698\">33</sup> דמלכא גליף גליפו בטה\"ע פי' בעצמות גלוי אורו הפשוט הנ\"ל שנק' טה\"ע גליף גליפו שהוא ענין חקיקת אותיות ובריש הורמנא שזה כשעלה ברצונו הפשוט הוא בחי' כתר ובחי' האותיות שחקק הוא בחי' המל' דאא\"ס וא\"כ יש ראש וסוף כתר ומל' גם בבחי' עצמיות אא\"ס וביאורו שעלה במח' ורצון הפשוט אנא אמלוך והכל בעצמותו עדיין קודם ענין מה ששיער בעצמו בכח דוקא כל מה שיהיה לו רצון למלוכה בגלוי והוא אחר הצמצום הנק' מק\"פ כו' והדמיון בזה ידוע מכחות הנפש בהתגלות מרצון עד המעש' שישנם כולם בפרט בהעלם אור עצמות הנפש שנק' בחי' יחידה כמו ע\"ד דוגמא כאשר האדם הוא",[["2687","22","<b>כברייתו של עולם</b>: שבת עז, ב (כגי' רש\"י)."],["2688","23","<b>בתחלה עלה במח'</b>: ראה רש\"י בראשית א, א. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'תכ."],["2689","24","<b>הכתר. . בחי' הממוצע</b>: ראה ע\"ח שם פ\"א. הנסמן במאמרי אדה\"א ויקרא ח\"ב ע' תס. בראשית ע' שפא."],["2690","25","<b>מל' שבעליון. . לתחתון</b>: ראה ע\"ח (שער כסא הכבוד) שמ\"ו, פ\"ב. פ\"ה. הנסמן במאמרי אדה\"א בראשית ע' לז. וראה גם לקמן קעו, א."],["2691","26","<b>מקורא דכולא</b>: לשון הזהר בראשית לג, א."],["2692","27","<b>מאריך באחד</b>: ברכות יג, ב."],["2693","28","<b>יחיד ואחד</b>: ראה גם אמ\"ב שער הק\"ש פ\"ח. סה\"מ תרנ\"ב ע' צח."],["2694","29","<b>מהתאחדות נפרדי' שנק' אחד</b>: ראה חובת הלבבות שער היחוד פ\"ח. מאמרי אדה\"א בראשית ע' תק. וש\"נ. סה\"מ מלוקט מכ\"ק אדמו\"ר שליט\"א ח\"ד ע' סט. וש\"נ."],["2695","30","<b>חכי' ולא בחכמ'. . כלל</b>: ת\"ז בהקדמה (יז, ב)."],["2696","31","<b>אנת הוא חד</b>: ת\"ז שם (יז, א)."],["2697","32","<b>ששיער בעצמו בכח. . במק\"מ</b>: מק\"מ לזח\"א טו, א. ראה גם סה\"מ תקס\"ח ח\"א ע' שכד ואילך. תקס\"ו ע' רה."],["2698","33","<b>מאמר הראשון שבזוהר בריש הורמנא</b>: ראה זהר בראשית טו, א. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתיח. פרשיות התורה ח\"א ס\"ע סז."]]],[2800530233,"חפץ חסד וטוב להטיב בדבר פרט שזהו בא מצד שיש בו מדה זאת דחפץ חסד וטוב בבחי' עצמות נפשו הנק' יחידה ע\"כ בא חפץ חסד זה בגלוי מן העלמו ומוכר' לומ' בוודאי שחפץ חסד זה בעצמות נפשו הוא בבחי' כח היולי בעצמיות לכלול כל מה שעתיד לחפוץ בחסד וטוב בכל פרטי פרטי העניני' שיבקשו ממנו וא\"כ בהכרח שקוד' שעלה ברצונו וחפצו זה שבגלוי להטיב חסדו בדבר זה הפרטי היה כלול בעצמיו' חפץ חסד ההיולי ויצא מן ההיולי להתגלות בדבר פרטי זה ואנו רואי' שיש בחפץ חסד זה שכל וחכמה ומדות ומחדו\"מ א\"כ ודאי במקור חפץ חסד זה בהעלמו כשהי' כלול בעצמיות החפץ חסד ההיולי ג\"כ מהתחלקות שכל ומדות ומחדו\"מ שבו אבל בבחי' עצמיות חפץ חסד ההיולי כמו שהוא קודם שבא עדיין בדבר פרטי הגם שבודאי גם שם יש התחלקו' שכל ומדות כו' מ\"מ כלולים ומתאחדי' בתכלית וכמ\"כ במדה פרטי' אחרת שבעצמיו' כמו מדת הגבור' והת\"ת והנצח וכה\"ג עד בחי' המל' שהוא מדת ההתנשאות שכלול בודאי מי' רצון וחפץ למלוכ' וחכמה ומדות ומח' כו'. אך קודם שבא לבחי' התגלות בדבר פרט כמו למלוך על מדינה זו וכה\"ג כלולים ומתאחדים בתכלית בבחי' מדת המלוכ' ההיולי' העצמית כמו בעצמו' חפץ חסד ההיולי' הנ\"ל וא\"כ מובן ממילא שבחי' מדת העצמיו' דכח\"ב וחג\"ת ונהי\"ם ההיולים שבעצמיו' הנפש לא יתכן לומר גם לשון זה שמתאחדי' וכלולים בעצמיו' הנפש הנק' יחידה מאחר שאינן נבדלים מן העצם כלל כמו מדת חפץ חסד ההיולי הנ\"ל שמוטבע בטבעית ועצמיות הגם שהוא חלק אחד הנמשך מעצם הנפש ממש שלמעל' מהיות חפץ חסד בעצמיות שזהו ענין פרטי ממהות' העצמי' הפשוט' בתכלי' מ\"מ א\"א לומ' בו שמתאחד במדת נצוח ההיולית הנטוע בעצם הנפש מאחר שמיוחדים שניהם בעצמות ואינן נבדלין כלל וכלל מן העצם ע\"ד דוגמא כח התנוע' שנכלל ממש בעצם החי קודם שמניעו לגמרי שאינו נבדל מן העצם כלל אעפ\"י שבגלוי כח התנוע' להניע דבר פרט יתחלק לכמה פרטי אופנים א\"א לומר שכל אופני פרטי התנוע' כלולי' ומתאחדי' היו כשהי' כח התנוע' נכלל בעצם החי מאחר שאז לא הי' בסוג וגדר תנוע' כלל לא בכלל ולא בפרט כו' וכן בחי' גילוי התפשטות החיות להחיות כל הגוף בעודנ' כלול לגמרי בעצם רוח החיים הגם שבגלויו מתחלק לראי' ושמיע' לעין ואוזן וכה\"ג שבודאי גם טרם בואו להתגשם בעין ואוזן בפועל הי' כלול בו חיות הראי' הרוחני' לעין בפ\"ע וחיות השמיע' באוזן בפ\"ע מ\"מ קודם שבא' עצם הנפש לכלל בחי' התפשטות החיות גם שכלול בה ה\"ז כהתכללות כח התנוע' בעצם החי הנ\"ל וכל מה שמוכן ועתיד לבוא לידי גלוי בפועל החיות עדיין יתכן היחוד וההתכללות דראי' ושמיע' וכה\"ג אבל כאשר כלול לגמרי בעצם הנפש והי' כלא יש במציאו' התפשטות חיות כלל וכלל מצד עצם הנפש שלמעל' הרבה מבחי' התפשטות רק שכולל בעצמו' ג\"כ בחי' ההתפשטות כעצם החי שכולל בעצמו כח התנוע' כנ\"ל א\"כ איך יתכן בחי' היחוד והתכללו' דפרטי אור וחיות רק מצד שעתיד ומוכן לצאת בהתפשטות חיות בהתחלקות פרטי חיות מזה מוכרח לומר שיש כל פרטים הללו בהתפשטו' הכלולה בעצם לגמרי שאל\"כ מאין נמצאו פרטים הללו בגלוי ההתפשטות כמו האור וזיו שכלול בעצם השמש שיש בו בהעלם כל פרטי אופני זיו המתפשט וכה\"ג וד\"ל. ונמצא ג' מדריגות<sup data-n=\"2699\">1</sup> זא\"ז נמשך מעצמיו' הנפש ממש הנק' בחי' יחידה הא' י' כחות עצמי' והיוליים כמו חפץ וחסד העצמי והיולי וכה\"ג",[["2699","1","<b>ג' מדריגות</b>: ראה המשך תרס\"ו ע' תקיא ואילך. סה\"מ קונטרסים ח\"ב ע' שכו."]]],[2800530234,"כלולים בה בתכלית כהתכללות כח התנועה בעצם החי וכהתכללות התפשטו' החיות בעצם כנ\"ל ולא יתכן בהם לומר לשון התאחדות מדברים נבדלים יחד אחר שכלולים לגמרי בעצם והיה כלא היה במציאות כלל וכלל כנ\"ל. והב' בחי' התפשטות י' כחות שמוכנים לבא בבחי' גלוי כמו חפץ חסד העצמי ההיולי שבא לדבר חסד בדרך פרט גם קוד' שנמשך בפו\"מ רק כשעתיד ומוכן לצאת לדבר פרט שם יתכן ענין האחדות מכמה פרטי' שבו כמו שכל ומדות שבחפץ חסד זה הנמשך מהעלמות ההיולי הכללי כו'. והג' כשנמשך ובא לאותו דבר פרט רק שעדיין לא בא מצד העדר ומניעה אבל ההכנה בעצמה כבר בשלימותה ולא חסר רק לבא בהתגלות בפ\"מ דהיינו שכבר שיער היטב בעצמו בדרך פרט לאותו דבר שבא לפו\"מ והיינו שיער בעצמו בכח מה שצריך להביא בפועל כמו ע\"ד דוגמא הנ\"ל בכח התנועה כשעתידה לצאת בגלוי בדבר פרט וכמו התפשטות החיות להחיות לגוף כשמוכן לצאת שכלולי' שם ביחוד כללי כל החיות פרטיי' ואח\"כ הוא מה ששיער והכין כבר בכח התנועה איך להניע דרך פרט וכן מה ששיער התגלות התפשטות רוח החיים והוכן בו מה שעתיד להחיות בפו\"מ וכמ\"כ דמיון כח הצומח כשמוכן להצמיח בפו\"מ שיש בזה ג\"כ ענין ג' מדריגות הללו והכל הוא טרם שבא הדבר עדיין בפו\"מ כמו התנועה קודם שבאה בגש' הנפעל או החיות הרוחני קודם שבא בגשם הגוף ששם משתנה ממהות רוחני' למהות גשם שהוא בחי' תנועה גשמיו' והחיות גשמיו' וכה\"ג בגשם הצמיח' כו' שצריך לזה בחי' צמצום וכיווץ בגלוי זה הרוחני בתחלה כדי שיבוא מכלל רוחניות לגשמיות (כמשי\"ת באות הי\"ב):\n(יא) <b>והנמשל</b> מכל הנ\"ל בנפש יובן למשכיל למעלה בעצמות אא\"ס שלפני הצמצום שנק' יחיד וכלול גם שם מע\"ס ונק' ע\"ס הגנוזות בהעלם העצמות ממש כמו בחי' חפץ חסד שכלול בבחי' עצמיות דאא\"ס שמחמתו וסיבתו היה הרצון הפשוט לכל ההשתלשלות שזהו בדבר פרט כמ\"ש בע\"ח בהקדמ' כשעלה ברצונו<sup data-n=\"2700\">2</sup> הפשוט כו' ובודאי סיבת עליי' הרצון הפשוט בעצמותו היינו רק כי חפץ חסד הוא בעצמו ע\"כ עלה ברצונו להטיב חסדו להיות מקור למקור להשתלשלות דקו\"ח כו' וה\"ז ע\"ד דוגמא כשמחמת עצמיות המדה דחפץ חסד הכלולה בבחי' יחידה כנ\"ל עולה ברצונו לעשו' טוב וחסד בדבר פרט כנ\"ל שבא בגלוי מן העלמו ההיולי דחפץ חסד לכלול כל מה שיעלה בפרט ברצונו להטיב הכל בא מחמתו וכחו כו' וכמו שבגלוי רצון שבא מחמת חפץ חסד זה כלול מי' חב\"ד ומדות כו' מזה מוכרח שגם בבחי' חפץ חסד ההיולי שכלול בעצמות ממש כלול מי' חכמה ומדות כו' רק שלא יתכן בהם לומר גם ענין ההתכללות והאחדות אחר שכלול בעצמות בבחי' היולי עדיין כו' וכמ\"כ במדה זולתה כמו מדת הגבו' או הנצח והת\"ת וכה\"ג הכל הוא כלול בעצמיות דאא\"ס שנק' טה\"ע והוא שנק' יחיד שלמעלה מאחד פשוט כו' עד בחי' מדת המלוכה בעצמות אא\"ס שנק' מל' דא\"ס גם הוא כלול בבחי' היולי העצמי דעצמות אא\"ס שהוא בבחי' א\"ס ממש וכמו שחפץ חסד בבחי' א\"ס ממש בעצמות או לחכמתו א\"ס כך מדת ההתנשאות שכלול בעצמות אא\"ס הוא בבחי' א\"ס וכלול מי' בהעלם העצמות שהוא בחי' הרצון והתענוג וחכמה ומדות שבמדות המלוכה אך ענין אנא אמלוך שעלה ברצונו ומח' הפשוט היינו כשבא בדבר פרט לבחי' ההשתלשלות בגלוי מהעלמו ההיולי כנ\"ל במדה דחפץ חסד באדם למטה וכנ\"ל במשל י' כחות הכלולים",[["2700","2","<b>כמ\"ש בע\"ח בהקדמ' כשעלה ברצונו</b>: נסמן לעיל קטו, א."]]],[2800530235,"שבבחי' יחידה בבחי' היולי ועצמיות כו' שאינן נבדלין מן העצם כלל וכמו כח התנוע' שכלול בעצם החי וכהתפשטו' החיות ההיולי הכלול בעצם הנפש ממש כנ\"ל ולמטה מזה הוא בחי' אא\"ס המאיר ומתפשט והכל עדיין בבחי' עצמותו לפני הצמצום וזהו הנק' אחדות הפשוטה שיתכן שם בחי' התכללות ואחדות בע\"ס וגם הם נק' ע\"ס בלי מ\"ה<sup data-n=\"2701\">1</sup> כי הוא למעלה גם מבחי' הכנה להשפעה למטה בגלוי עדיין רק שמוכן לצאת מההיולי בדבר פרט כמו חפץ חסד ההיולי הנ\"ל כשבא לענין הרצון וחפץ חסד בהשתלשלות דקו כו' גם שלא יצא עדיין בגלוי גמור גם בעצמו עכ\"פ שם יתכן בחינת אחדות והתכללות רק שנק' אחדות הפשוטה בהיותו עדיין באור עצמותו הפשוט בתכלית וכמו בחי' התחלקו' שכל ומדו' כו' שבחפץ חסד זה שמחמתו הוא שעלה ברצונו וחכמתו להטיב כו' גם טרם בואו לגלוי כלל וכלל כו' וכנ\"ל במדריג' הב' בנפש האדם. והג' כאשר מבחי' חפץ חסד זה הוא שעלה כבר ברצון ושכל כו' והוכן בכל השיעור באותיות ששיער בעצמו איך יהיה איכות אופן ההשפע' ממש לחוץ מעצמותו ע\"ד דוגמ' מכח התנוע' המוכן איך להניע וכח החיות המוכן איך להחיות כשמוכנים כבר בשיעור ואופן מוגבל כנ\"ל בענין מדריגה הג' בנפש ולמעלה היינו מה ששיער בעצמו' אא\"ס שנק' טה\"ע באופן ושיעור מה שרוצ' בהשתלשלות בפועל התגלות דקו עד סוף עולם העשי' שזהו מ\"ש גליף גליפו בטה\"ע כנ\"ל והוא הנק' בחי' קדמון דהיינו מה שקדם אופן הרצון להשפיע טרם שמשפיע עדיין בגלוי ממש וזהו עדיין לפני הצמצום הראשון הנק' מק\"פ וחלל כו' כנ\"ל וד\"ל. ומדריג' הד' הוא מה שאחר הצמצום הנ\"ל נשאר בחי' הרשימו ונמשך ממנו הקו שהוא בכללות בחי' טה\"ת בחי' מקיף כללי לכל השתלשלות דקו כו' שזהו הבא בבחי' השפעה למטה מן העצמות כמשל חיות המתפשט בגלוי להחיו' כו' וככח התנועה שמתפשט' להניע הנפעל בגלוי כו' שמשתנ' ממהות רוחני למהות הגשמה כנ\"ל וכמו צמיחה גשמי' מצמיחה רוחני' כך הוא ערך האור שאחר הצמצום לגבי האור העצמי שלפני הצמצום דמשום זה הוצרך להיות ענין הצמצום הזה רק בשביל שיוכל להיות הארת האור שבקו שבא בשביל מקור לאבי\"ע כידוע אך עכ\"ז הרי כל פרטי הע\"ס דאבי\"ע הכל כלולים מתחלה בעצמות אא\"ס בבחי' היולי ועצמי ואח\"כ ע\"י הצמצום משתנה לפי אופן מוגבל בהשפעה הכללי' דקו בבחי' סובב וה\"ז כדוגמת חיות הנפש הרוחני' כשבאה להחיו' הגוף שכלול' ברוחניות מכל פרטי חיות הגשמיו' ראי' ושמיעה שבגוף הגשמי כנ\"ל (וענין הצמצום והרשימה יתבאר בסמוך) (וזהו פירוש כללי למ\"ש ברוך שאמר והיה העולם<sup data-n=\"2702\">2</sup> פירוש שאמר בהעלם ברצונו הפשוט שבמל' דאין סוף בהיותו עדיין כלול בחפץ חסד העצמי הנ\"ל ואח\"כ והי' בגלוי אור המתפשט לדבר פרט להשתלשלו' להיות מקור לכל העולמות ופי' והיה העולם היינו דווקא מן מה ששיער בעצמו בכח שהוא שרש מה שמתהוו' אח\"כ העול' הכללי שנמשך מן הקו וכו' וכנ\"ל וד\"ל. וברוך הוא נסתר היינו בחי' קדמונו של עולם<sup data-n=\"2703\">3</sup> דהיינו מה ששיער בעצמו בכח כו' וכמ\"ש מגיד מראשית אחרית<sup data-n=\"2704\">4</sup> מראשית הקו עד סופו כו' ומקדם אשר לא נעשה<sup data-n=\"2705\">5</sup> עדיין היינו מקדמונו של עולם הנ\"ל ונק' ימי קדם<sup data-n=\"2706\">6</sup> שקודם למה שנמשך בקו והוא מה שקדם בעצמו בכח מה שעתיד להיות בפועל כו' וד\"ל. ומ\"ש ברוך אומר ועושה כו' היינו מה שנמשך בקו בפו\"מ ועושה בראשית כו' הוא כל שיעור קומת א\"ק",[["2701","1","<b>ע\"ס בלי מ\"ה</b>: ס\"י פ\"א מ\"ב."],["2702","2","<b>ברוך שאמר והי' העולם</b>: נוסח ברוך שאמר. ראה גם שע\"ת ח\"א כו, א ואילך. וראה גם לעיל נו, ב."],["2703","3","<b>קדמונו של עולם</b>: לשון ב\"ר פל\"ח, ז."],["2704","4","<b>מגיד מראשית אחרית</b>: ישעי' מו, י."],["2705","5","<b>ומקדם אשר לא נעשה</b>: המשך הכתוב מגיד מראשית [ושם: נעשו ? ראה סה\"מ תקס\"ה ח\"א ע' רכה. אמ\"ב שער הק\"ש כא, א. כח, א]."],["2706","6","<b>ימי קדם</b>: ראה מיכה ז, כ. ראה גם אמ\"ב שם כא, א."]]],[2800530236,"כו' וגוזר ומקיים בתחלה הוא בחי' קו המדה שלפני א\"ק שהוא בחי' צמצום דרשימו שנמשך ממנו הקו כידוע וכמשי\"ת בעז\"ה בסמוך):\n(יב) <b>ומעתה</b> יש להבין ביאור ענין הצמצום הראשון הנ\"ל ובחי' הרשימו שנשאר כו' הגם שידוע ליודעי' הרי יש בזה פרטים רבים וצריך להעמיק הדעת בהם ביותר כי זהו עיקר היחוד האמיתי בעצמות אא\"ס איך דכולא קמי' כלא<sup data-n=\"2707\">7</sup> כו' גם בבחי' כללות כל ההשתלשלות דקו וכו' עד שיוכל אדם לכוון רצונו במס\"נ לעצמות אא\"ס לבדו כמ\"ש אתה הוא ה' לבדך<sup data-n=\"2708\">8</sup> אתה כו' וזהו המלך המרומם לבדו בחי' מל' דא\"ס שלפני הצמצום שמתנשא גם מימות עולם דא\"ק<sup data-n=\"2709\">9</sup> שנקרא ימי קדם הנ\"ל וזהו השמים בחי' סובב הכללי שאחר הצמצום ושמי השמים שלפני הצמצום לא יכלכלוך<sup data-n=\"2710\">10</sup> גם בבחי' כלי לכלי כמו גליף גליפו בטה\"ע כו' וד\"ל וכמ\"ש מי לי בשמים<sup data-n=\"2711\">11</sup> שהוא גם בחי' סובב הכללי שלפני הצמצום שנק' שמי השמים<sup data-n=\"2712\">12</sup> כו' ועמך לא חפצתי בארץ בבחי' קו\"ח בחי' ממלא הכללי כו'. והנה יש כמה אופנים במשלי' שונים להשכיל ביאור ענין הצמצום הנק' מק\"פ כידוע למעיין וכללותו עולה בסגנון א' והוא כדי שיוכל להיות אא\"ס בבחי' השפעה בצמצום בבחי' קו הוצרך לצמצם עצמו' אורו שישאר בהעלם בעצמותו כו' ולא יאיר כולו רק אפס קצהו בלבד כדי שיהי' אח\"כ המשכות האור בדילוג הערך וה\"ז כמשל אור שכל עמוק ורחב שבעצמות המשפיע שכדי שיומשך ממנו למקבל הבלתי ערך אליו הוצרך המשפיע להעלים בעצמו כל עומק השגתו ולא ישאר רק בחי' רושם כנקודה א' מכל העומק והרוחב ולא שנסתלק ונתעלם לגמרי רק כמו השונ' בדרך קצר' שכל העומק ורוחב הפלפול ישנו בשכלו רק שהוא נכלל לפי שעה בהעלם עצמותו בשעה שאומר הדין דרך קיצור ומיד שישאלוהו ירחיב הדבר כו' רק בשביל שיובן למקבל דרך זה הקצר מעלים גם בעצמו לפי שעה כו' וכמ\"ש במ\"א באריכות<sup data-n=\"2713\">13</sup> ומה שנשאר כמו נקוד' שהוא דרך קצר' אין זה צמצום גמור ואמיתי כמו המצמצם ומעלי' לגמרי שנחסר למקבל לגמרי אלא הענין הוא שכולל בדרך קצר זה כל האריכות לא יחסר דבר וחצי דבר כמו שכלול בדין הקצר שבמשנ' כל האריכות הפלפול שבגמרא וכמו שלא נעלם ליודע כל הפלפול גם בשעה ששונה לעצמו דרך קיצור כו' שנמצא שידיעתו באריכות מקפת בהעלם כל התגלות הקיצור ולא שנסתלק לגמרי כשכחה וכה\"ג כו' וכמ\"ש ביאור זה באריכות במ\"א<sup data-n=\"2714\">14</sup>. ואופן משל הב' מחיות הנפש בגוף ג\"כ עול' ע\"ד הנ\"ל והוא בהיות שכדי שישתנה מחיי רוחני' שבעצם הנפש לחיי בשר הוצרך להיות בחי' העלם וכיווץ האור של הנפש בתחל' לפי שאין ערך ביניהם ועכ\"ז הרי מתפעל' הנפש ממקרי הגוף א\"כ גם אור הגשמ' החיות תתחבר ונקשר אל אור עצמותה הרוחני כצמיחה גשמי' שנקשר בכח הצומח הרוחני כו' ובהחתך אבר הגוף לא יחסר באור וחיות רוחניות של אבר זה וראי' מסומא שמוליד שלם כו' כידוע אין זה רק שהרוחניות הוא בהעלם וישנו במציאותו חופף על חיות הגשמי שבגוף ונק' צלם איש כו' והיינו ע\"ד הנ\"ל בידיע' שבהעלם כו' (וכ\"ז מבואר באריכות במ\"א) וכן כח התנוע' הרוחניות כשבא' בתנועת הגשם מתצמצמת בעצמותה כו' ועכ\"ז התנוע' גשמית מחוברת ומקושרת בתנוע' הרוחנית וכה\"ג באופני' אחרים כמו ענין התחכמות שכל פרטי מכח המשכיל שלו ששור' עליו בהעלם כו'. ואמנם להבין בחי' הרשימו שענינ' מורה בחי' הסתלקות בהעלם ולא נשאר מהכל רק",[["2707","7","<b>דכולא קמי' כלא</b>: ראה זהר בהקדמה יא, ב. מאמרי אדה\"א דברים ח\"ב ע' תרנג."],["2708","8","<b>אתה הוא ה' לבדך</b>: נחמי' ט, ו."],["2709","9","<b>המלך המרומם. . דא\"ק</b>: ברכת יוצר. ראה גם לעיל קטו, ב."],["2710","10","<b>השמים. . ושמי השמים. . לא יכלכלוך</b>: מלכים-א ח, כז."],["2711","11","<b>מי לי בשמים</b>: תהלים עג, כה."],["2712","12","<b>שמי השמים</b>: תהלים קמח, ד. נחמי' ט, ו. ראה גם שע\"ת יב, ב ובהנסמן במ\"מ לשם."],["2713","13","<b>וכמ\"ש במ\"א באריכות</b>: ראה לקו\"ת ויקרא בהוספות נב, ג ואילך. מאמרי אדה\"א ויקרא ח\"ב ע' תתקכא ואילך."],["2714","14","<b>וכמ\"ש. . באריכות במ\"א</b>: ראה גם לקו\"ת ויקרא (הוספות) נג, ג. סה\"מ תרמ\"ז ע' מח."]]],[2800530237,"רושם כו' הוא מובן יותר מעניני' משלים אחרים<sup data-n=\"2715\">1</sup> כמו הרושם שעוש' האומן<sup data-n=\"2716\">2</sup> שיוכל לעשות הבנין בקיצור קו זה שברושם שכולל כל אריכות המעש' בקיצור רושם זה או כמו שעוש' לזכרון הנק' אות שאין האות ענין שייך אל עצם הענין רק לזכרון בעלמא כמו עשה לך ציונים<sup data-n=\"2717\">3</sup> כו' וזהו בחי' העלם יותר מקיצור ההלכה ששונה וכולל בו הכל שעכ\"פ שייך ענין הקיצור אל האריכות ויש עוד אופן ברשימו זו שהוא מורה ענין הצמצום וההעלם הרבה יותר והוא כמו הזורק אבן שכח המוליך אותו נבדל מן העצם ועכ\"ז כל כח התנוע' מלובש בו בהעלם אך שהוא בריחוק נבדל ביותר מכחו העצמי שבידו משא\"כ כח התנוע' עצמה שמניעה בעצמו בגשם שמלובש בגלוי בגשם ביותר כנ\"ל ויש בחי' העלם יותר גם מזה שדומה לענין הרושם לזכרון לבד והוא כמו הרומז בידו לאיזה שכל עמוק ביותר שנבדל תנועה גשמי' מהשכל הרוחני ועכ\"ז מבין השכל מתוכו כו' ויותר מזה העלם אור השכל בתנוע' האצבע בכתיבתו אותו וכמ\"ש במ\"א באריכות והכל עולה לסגנון א' הנ\"ל שבחי' העצמות נשאר בהעלם וכלול ברושם ונקודה זו כו' וד\"ל:\n(יג) <b>והנמשל</b> מכל הנ\"ל יובן למעל' בכללות ענין הצמצום הנק' מק\"פ שזהו בחי' הסתלקות וההעלם לעצמותו כדי שיוכל להיות אח\"כ בחי' השפעת אור כנ\"ל ולא שנסתלק ונתעלם לגמרי אלא כמשל הסתלקות והעלם בעצמו הידיעה של כל העומק והאריכות כששונה דרך קיצור כנ\"ל א\"כ לפי זה גם אחר כל ההשתלשלות דאבי\"ע שעומד במקום פנוי זה הרי בחי' העלם אור העצמות מקיף וסובב לכל השתלשלות דקו וכמו שהי' אור העצמות קודם הצמצום ממלא את כל החלל ריקן ומק\"פ הזה כמ\"ש בע\"ח כך גם אחר הצמצום הרי ישנו לאור העצמיות כמו שהוא בבחי' א\"ס ממש רק שלא נגלה למטה לגבי שפע המקבלים אבל לגבי עצמותו אין שינוי בזה כלל וכמו משל היודע כל האריכות להשיב לשואלו מיד גם בשעה ששונה לתלמידו בקיצור כו'. ומ\"ש ישת חשך סתרו<sup data-n=\"2718\">4</sup> וכמאמרז\"ל ברישא חשוכא<sup data-n=\"2719\">5</sup> כו' היינו לגבי למט' שנמשך רק מבחי' הרשימו שנשאר אחר ההעלם כנ\"ל וזהו אתה קדוש ושמך אור העצמי קדוש<sup data-n=\"2720\">6</sup> ומובדל ואתה הוא קודם<sup data-n=\"2721\">7</sup> כו' כמ\"ש אני הוי' לא שניתי<sup data-n=\"2722\">8</sup> כו' משום דמה שמגלה עמוקות מני חשך<sup data-n=\"2723\">9</sup> והעלם זה אח\"כ בהארת הקו הוא דוקא מאותו אור העצמות שלפני הצמצום וזהו אתה הוא כו' וכידוע ואמנם לא נק' אור העצמות שמקיף ההשתלשלות<sup data-n=\"2724\">10</sup> שבמק\"פ כו' כמו בחי' מקיף לפנימי כמקיף הכללי דקו שמקיף לאבי\"ע בשוה כו' כי הרי עדיין אינו בגדר וסוג בחי' אור השפעה כלל גם לא להיות בחי' מקיף כו' רק אור העצמות שהוא בחי' התגלותו כמו שהוא בעצמות ולזה אנו אומרים הוא קיים ושמו קיים<sup data-n=\"2725\">11</sup> וכן ברוך הוא ברוך שמו<sup data-n=\"2726\">12</sup> וכה\"ג רק מבחי' אותיות דגליף בטה\"ע זה שהוא מה ששיער בעצמו בכח כו' וגם זה הוא הנשאר בבחי' העלם והסתלקות קצת דהיינו רק לפ\"ע אופן הנצרך להשתלשלות אחר צמצום זה וד\"ל. וגם עפ\"י אופן משל הב' הנ\"ל דחיות הנפש בגוף שמשתנה ממהות רוחני למהות גשמי כנ\"ל ג\"כ אין זה שינוי כלל שהרי כמו שיש קישור וחיבור לחיות הגשמי לחיות הרוחני ממה שרואי' התפעלות הנפש ממקרי חיות הגוף ועכ\"ז לא ישתנה בעצם הרוחנית מחסרון התפשטות חיות אבר גשמי כנ\"ל כך אין שינוי בבחי' אור העצמות להיותו מאיר גם אחר הצמצום גם שאינו רק לפ\"ע ההשתלשלות הרי יש ביניהם קשר וחיבור ועכ\"ז בצמצום האור בבחי' הקו אין זה שינוי כלל",[["2715","1","<b>משלים אחרים</b>: ראה סה\"מ תרמ\"ז ע' נא ואילך. אגרות קודש מכ\"ק אדמו\"ר שליט\"א ח\"ב ע' שצה. וש\"נ. נדפס גם בחלקו בלקו\"ש בראשית (כרך טו) ע' 475."],["2716","2","<b>הרושם שעוש' האומן</b>: ראה גם סה\"מ תקס\"ז ע' כה."],["2717","3","<b>עשה לך ציונים</b>: ירמי' לא, כ [ושם: הציבי]."],["2718","4","<b>ישת חשך סתרו</b>: תהלים יח, יב."],["2719","5","<b>ברישא חשוכא</b>: שבת עז, ב [כגי' רש\"י]."],["2720","6","<b>אתה קדוש ושמך. . קדוש</b>: נוסח תפלת העמידה."],["2721","7","<b>ואתה הוא קודם</b>: נסמן לעיל קטז, א."],["2722","8","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו."],["2723","9","<b>שמגלה עמוקות מני חשך</b>: איוב יב, כב."],["2724","10","<b>ההשתלשלות</b>: אג: כל ההשתלשלות."],["2725","11","<b>הוא קיים ושמו קיים</b>: ברכת אמת ויציב."],["2726","12","<b>ברוך הוא ברוך </b>[אג: וברוך]<b> שמו</b>: מסכת היכלות בסופה [נדפסה באוצר מדרשים ? אייזענשטיין ? ח\"א ע' 111]."]]],[2800530238,"באור העצמו' עפ\"י משל זה וכן עפ\"י משל הג' מכח התנועה בגשם או כמשל התחכמות מכח המשכיל הנ\"ל הכל עולה לסגנון א' כנ\"ל באריכות וד\"ל. ואמנם בבחי' הרשימו שמבואר למעל' שזהו כמו הקיצור שכלול בו כל האריכות הנה למעל' יובן מזה שזהו בחי' כח ההגבלה שיש באור א\"ס הבלתי מוגבל בעצם דהיינו להביא כל הארו' אור העצמות הבלתי גבול בבחי' הגבול שזהו ענין הרושם שכולל בבחי' הגבלה מבחי' כל עצמות אא\"ס כמשל הקיצור שכולל הכל כו' כי הוא ית' כל יכול וכלול בו ג\"כ מכח המגביל להגביל ולכלול ברשימה א' מכל אור העצמות כו' וכמ\"ש במ\"א באריכות<sup data-n=\"2727\">13</sup>. אך הנה באמת אין זה דמיון אמיתי לבחי' הרשימו הנשאר בחלל ריקן ומק\"פ הנ\"ל כי הוא מורה שנסתלק משם הכל ולא שנשאר איזה אור רק שהוא בקצור וגבול אלא רק בחי' רשימו בעלמא כו' א\"כ הדמיון האמיתי הוא מרושם וציון קו קצר שעושין האומנין שכולל כל אריכות מעשה הבנין ויותר מזה כמו האות לזכרון כנ\"ל וכך למעל' כתיב זכר רב טובך<sup data-n=\"2728\">14</sup> העצמי כו' וכה\"ג ויותר בהעלם והסתלקות הוא כמשל הזורק אבן כו' כנ\"ל וכך אמר בס' הבהיר<sup data-n=\"2729\">16</sup> וכמו זרקא<sup data-n=\"2730\">17</sup> כו' שהרי בחי' הרשימו נשאר נבדל בריחוק מקום מעצמות האור וכו' ונקרא כח הנעלם ברשימו זו בחי' העלם אור נבדל מהעלם עצמות האור דא\"ס כמו כח נבדל הנעלם בזריקת אבן שבא מכח היד שכבר נעלם בעצמו כו' (וכדמיון כל הגלגלים וכוכבי לכת שסובבי' מכח תנועה אלקי' הנעלם שבא בבחי' זריקה<sup data-n=\"2731\">15</sup> מאור וכח האלקי דט' כלי' החיצוני' דמל' דעשי' שנק' זה כח הנבדל בחי' מל' שבמל' הבא בערך ריחוק נבדל ולא כמו הכתיבה באצבע או כח יד הפועל עצמו בנפעל שזהו גלוי עצם הכח בקירוב שנק' בחי' מל' (כמ\"ש<sup data-n=\"2732\">19</sup> במ\"א באריכות<sup data-n=\"2733\">18</sup> ) ומשלים היותר קרובים לזה הוא כמו הרמז שהשכל בהעלם בתנועה הגשמיית שזהו נק' בחי' הלבשה ותפיסא בדבר נבדל כו' וכן כשכותב שכל וחכמה בתנועת האצבע כו' כנ\"ל כך למעלה בחי' הרשימו בחי' דבר נבדל בערך שבו מלובש בהעלם מכללות אור העצמו' כו' וד\"ל. ואמנם מכל אלה יובן עכ\"פ כללות ענין הרשימו דגם שהוא בא בבחי' הסתלקו' הכל ולא נשא' בה רק בהעלם גדול בחי' תכלית הקיצור והרמז כו' או ככח נבד' כו' אבל מ\"מ מזה עצמו בא ונמשך כל פרטי ההשתלשלו' דקו שנמשך מרשימו זו כי ברשימו זו להיותה כוללת הכל בהעלם עכ\"פ היא הנותנת שיוכל לבא הכל בהתגלות ע\"י בחי' הקו עד סוף העשי' וכמאמר כל היצור לא נכחד ממך<sup data-n=\"2734\">20</sup> ממך דוקא שזהו הכל נעשה ונמשך בגלוי כמו שעלה ברצונו הפשוט בעצמו' האור שלפני הצמצום כמו ששיער בעצמו כו' שהרי במח' קדומה זו ששיער בעצמו הוא צופה ומביט הכל בסקירה א'<sup data-n=\"2735\">21</sup> דהיינו מה שנסקר בהעלם ובקיצור ורמז ברשימו זו כו' וה\"ז כמשל רושם האומן שממנו דוקא ידע לעשו' כל אריכות מעש' הבנין בפרטי פרטיו מראשו לסופו רק כדי שלא יתעלם ממנו טעמו ונימוקו בעצמותו לאריכות הענין הוא עושה לו רושם לזכרון שלא ינטה מזה ולא יצטרך לעיין בעצמו מחדש וכמ\"כ ענין הציונים ללימוד עמוק שבעצמו כו' שזהו תועלת לידע מהם כל אורך עיון עומק עצמותו שיש לו פן ינטה ממנו כו' וכך בחי' הרשימו הזאת הכוללת ברמז ובקיצור מכל אור העצמות הנעלם בה הוא עצמו המקור לכל ההמשכו' דקו\"ח בבחי' מקיף ופנימי מראשו לסופו שיהי' הכל כמו שעלה ברצונו וחכמתו הפשוטה בעצמו' אור א\"ס ממש כו' וזהו מ\"ש במ\"א שהנקודה יש בה העלם והתגלות<sup data-n=\"2736\">22</sup> ב'",[["2727","13","<b>מכח המגביל. . ברשימה. . באריכות</b>: ראה מאמרי אדה\"ז על ענינים ע' שדמ ואילך. ע' שסב. תקס\"ז ע' כה. פרשיות התורה ח\"ב ס\"ע תרכה ואילך. אוה\"ת תצא ע' תתקכה."],["2728","14","<b>זכר רב טובך</b>: תהלים קמה, ז."],["2729","16","<b>הזורק אבן. . בס' הבהיר</b>: ראה שמו\"ר רפי\"ג. הערה בסה\"מ תש\"י ע' 65. מאמרי אדה\"ז על ענינים ע' שפט ובהנסמן שם. הנסמן במאמרי אדה\"א נ\"ך ע' קפג."],["2730","17","<b>וכמו זרקא</b>: ראה גם פרדס (ריש שער הטעמים) שכ\"ט, פ\"א. סה\"מ תק\"ע ע' קנא. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'תסט."],["2731","15","<b>הזורק אבן. . בבחי' זריקה</b>: ראה גם סה\"מ תקס\"ו ע' רמח. מאמרי אדה\"א במדבר ח\"ג ע' א'נו ואילך."],["2732","19","<b>(כמ\"ש</b>: ג: כמ\"ש."],["2733","18","<b>זריקה. . הכתיבה. . באריכות</b>: ראה גם מאמרי אדה\"ז על ענינים שם. אמ\"ב שער הק\"ש לד, ג ואילך."],["2734","20","<b>כל היצור לא נכחד ממך</b>: ברכת זכרונות (מוסף לר\"ה)."],["2735","21","<b>צופה ומביט הכל בסקירה א'</b>: נסמן לקמן קכא, ב."],["2736","22","<b>שהנקודה. . העלם והתגלות</b>: ראה גם סה\"מ תקס\"ח ח\"א ע' רצב ואילך."]]],[2800530239,"הפכי' העלם מכל מה שעליון הימנה בערך וגילוי הכל למקבלים נמצא ממנה דוקא והוא בחי' הקו שנמשך מן הרשימו שהוא כצורת ו' שראשו י' והולך ונמשך למטה כמ\"ש במ\"א באריכות ובכל זה מובן כללות ענין הצמצום דמק\"פ ובחי' הרשימו והקו שהוא רק בחי' הגבלה בעצמו' כדי שיומשך הכל בגלוי וז\"ש כי עמך מקור חיים<sup data-n=\"2737\">1</sup> באורך העצמי נראה אור אור של תולד' שהוא בחי' הקו וכמשי\"ת בעז\"ה וזה כל האדם להעמיק דעתו בכ\"ז וכיוצא בו מפני שמזה דוקא יבוא לכלל היחוד האמיתי בהתקשרו' נפשו בחיי כל החיים העליונים שהוא עצמות אא\"ס ממש מטעם הנ\"ל וד\"ל:\n(יד) <b>ומעתה</b> יש להבין בבחי' הקו והחוט שנמשך מבחי' הרשימו הנ\"ל דרך פרט ותחלה י\"ל בו בענין כללותו שהוא בחי' ההיפוך ממש מבחי' הרשימו הנ\"ל כי הנה הנקודה מורה ההעלם והסתלקות הכל עד שלא נשאר רק כנקוד' א' וגם נקודה או רושם זה מורה בחי' העדר ההתפשטות למטה דוקא דהיינו ענין העדר ההמשכ' וההתגלות לאורך ורוחב כצורת הי' שאין בו תוך וחלל<sup data-n=\"2738\">2</sup> כו' כידוע. והנה בענין צמצום שלו מלמעלה דהיינו מה שנשאר בבחי' נקודה לבד יוכל להיות שיהיה מזה להיפוך מפני שמחמת זה יוכלל בו הכל בקיצור ורמז וכה\"ג ואדרבה זהו עיקר סיבת כל גלוי ההשפע' כנ\"ל אבל מה שמנקודה זו מורה העדר ההתפשטות לגמרי למטה לכאורה זהו ודאי נק' צמצום גמור ואמיתי להעלי' ולהסתיר לבלתי יבוא האור למטה וא\"כ איך יומשך מנקודה זו היפוכו ממש שהוא בחי' המשכה והתפשטות דקו כו'. אך הנה ידוע שבאמת הנקודה והקו אינם ב' הפכים שהרי הקו נמשך מן הנקודה ומחיבור נקודות יחד נעשה קו<sup data-n=\"2739\">3</sup> כו'. אך הענין הוא כידוע שהנקודה הוא כמו בחי' ההיולי לגבי הקו וכמו כל בחי' היולי או חומר פשוט שאע\"פ שהוא בהעדר ההתפשטות דוקא אין זה הכרחי כלל רק מצד עצם מהות ההיולי מפני שהוא למעלה עדיין מבחי' התפשטות ולזאת לא ירד מעצמותו וכמו היולי של חיות החי בגלוי בעודנה כלולה בעצם שאינה מתפשטת להחיות כו' וכהיולי של כח התנועה בעצם טרם שמתפשט להניע וככח הצמיחה טרם שמתפשט להצמיח וככח השכל טרם שמתפשט להשכיל וכה\"ג רבים בדומה הרי יובן שהעדר ההתפשטות הזאת לא נקרא צמצום אמיתי מצד עצמו אדרב' הרי הוא כח ההיולי העצמי שממנו נמצא הכל בהתגלות והתפשטות וכה\"ג יובן בבחי' נקודה לגבי הקו שהעדר התפשטות' הוא רק מצד היותה בבחי' העצמיות שלמעלה מבחי' ההתפשטות עדיין והגם שבאה ע\"י צמצום הכל עד שלא נשאר רק כנקודה א' כנ\"ל אך ה\"ז עצמו מורה שכל בחי' העצמיות כלול בה ולהיות כן בלתי מתפשטת למטה וכמשל התלמיד לפני רבו דאיידי דטריד למבלע ונעשה כנקודה בצמצום כל עצמותו כו' לא פליט<sup data-n=\"2740\">4</sup> להשפיע לזולתו בהתפשטות אמנם אחר קבלתו אדרב' מזה הצמצום שהיה בבחי' נקודה הוא שנמשך ממנו כל ההשפעה והתפשטות לזולתו<sup data-n=\"2741\">5</sup> כו' וכמ\"ש במ\"א ומכ\"ז יובן שהקו הנמשך מן הנקוד' הוא רק כמו בחי' התפשטות מן היולי העצמי אמנם מה שנמשך בבחי' קו קצר הנה מבואר במ\"א שכמו שהנקודה בחי' היולי לגבי הקו כך הקו בחי' היולי לבחי' אורך ורוחב דשטח<sup data-n=\"2742\">6</sup> להיות ידוע שהקו הגם שהוא בא בבחי' המשכה והתפשטות<sup data-n=\"2743\">7</sup> מלמעלה למטה אבל אינו ענין פרטית אופן המשכה כלל רק מה שנמשך האור מלמעלה למטה<sup data-n=\"2744\">8</sup> בלבד שעי\"ז נמצא בחי' מעלה ומטה מהמשפיע אל המקבל",[["2737","1","<b>כי עמך מקור חיים</b>: תהלים לו, י."],["2738","2","<b>הי' שאין בו תוך וחלל</b>: ראה זהר בלק קצא, א. מאמרי אדה\"ז תקס\"ד ס\"ע קעז ואילך. תקס\"ח ח\"א ע' רצה. לקו\"ת בלק עא, ד. מאמרי אדה\"א במדבר ח\"ד ע' א'תקלא."],["2739","3","<b>ומחיבור נקודות יחד נעשה קו</b>: ראה סה\"מ תרנ\"ב ע' צז. ע' ק ואילך. תער\"ב ח\"א ס\"ע רמה ואילך."],["2740","4","<b>דאיידי דטריד למבלע. . לא פליט</b>: ראה חולין קח, ב. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתצה. תו\"ח נח סג, ג הערה 44."],["2741","5","<b>אחר קבלתו. . והתפשטות לזולתו</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ע' ריב. תקס\"ח ח\"א ע' תקלט."],["2742","6","<b>הקו בחי' היולי. . דשטח</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקעג. ראה גם סה\"מ תרנ\"א ע' כד. תרנ\"ב ע' צז. תרנ\"ט ע' מט."],["2743","7","<b>שהקו. . בבחי' המשכה והתפשטות</b>: ראה סה\"מ תרנ\"ב ע' צז. ע' קא."],["2744","8","<b>שהקו. . שנמשך האור מלמעלה למטה</b>: ראה סה\"מ שם ע' קד."]]],[2800530240,"משא\"כ בהיולי דנקודה אין בו מעלה ומטה ראש תוך וסוף כו' כידוע (וזהו מ\"ש בע\"ח דכל עיקר הארת הקו אינו רק להיות בחי' מעלה ומטה<sup data-n=\"2745\">9</sup> כמשי\"ת) וכמשל אמת הבנין שאינו בא בגדר שטח הבנין עצמו לאורך ורוחב רק שבו מודד כל מדידת אורך וכל מדידת רוחב והוא עצמו רק כמו קו הקצר שכולל כל אופני מדידות של אורך ורוחב כו' כך ציור הקו בחי' היולי לגבי בחי' שטח האותיו' לעשותם באורך ורוחב כמו בחי' קוין שבאות הב' כו' וכמ\"ש במ\"א ולפ\"ז גם ראשי' המשכת הקו מן הנקודה הגם שהוא בא בבחי' התפשטות והמשכה אבל הוא בחי' המשכה היולית עדיין לכלול כמה פרטי אופני המשכות לאורך ורוחב במדה ולזה נקר' קו המדה כידוע וע\"ז מורה צורתו שהוא קצר בעצם והולך ונמשך מלמעלה למטה בלבד אבל הוא כולל בהמשכתו עכ\"פ כל מה שיש בהעלם ההיולי דנקודה כו' רק שבא באופן המשכה למטה והוא בא מכח אור העצמי הנעלם שבעצמות המשפיע שלפני צמצומו בנקודה א' רק שבא דרך קו לבד ולא כמו שהוא בעצמות המשפיע שהוא בהרחבת הערך של העצמו' ממש ובקו זה הנה אור העצמות בא לפ\"ע המקבלי' לבד אבל עכ\"ז הרי יש בו מעין ודוגמת אור העצמות הנעלם בנקודה כו' רק שבא בדרך המשכה למטה ע\"כ בא בציור קו והוא בחי' היולי לכל אור ושפע המקבלים כו' וד\"ל:\n(טו) <b>והנמשל</b> מכל הנ\"ל יובן בבחי' רושם שנשאר בחלל ומק\"פ הנ\"ל (שהוא יו\"ד דס\"ג שבטה\"ע כמ\"ש בס' עמק המלך<sup data-n=\"2746\">10</sup> ) שהוא בחי' היולי כולל כל מה שיסתעף ממנו ע\"י הקו\"ח כו' וגם שנתעלם כללות האור<sup data-n=\"2747\">11</sup> העצמות עד שלא נשאר רק בחי' רשימו עכ\"ז ודאי הכל נכלל בו בקיצור עי\"ז הצמצום דוקא כנ\"ל וגם מה שהוא מורה העדר ההתפשטות למטה אינו בחי' צמצום גמור רק מצד שהוא בחי' כח ההיולי כו' כנ\"ל רק להיותו כח מגביל לכללות האור הראשון ע\"כ בלתי מתפשט רק דרך קו לפי אופן ההשפעה כנ\"ל. אמנ' יובן מהנ\"ל דקו זה יש בו מכח האור הראשון שלפני הצמצום בבחי' א\"ס ממש רק שבא דרך קו לפי אופן המקבלים כו' ובזה יובן מ\"ש באורך נראה אור<sup data-n=\"2748\">12</sup> בחי' הארה דהאר' הנק' אור של תולדה שאחר הצמצום בוקע האור דרך קו בעלמא כו' אבל הוא בא מאורך העצמי להיות שברשימו הרי נכלל הכל וממנו נמשך הקו בבחי' היולי לכללות השפע להיות בבחי' מעלה ומטה עכ\"פ כמ\"ש בע\"ח ומזה הטעם יובן תירוץ על ב' ענינים הפכים שנמצא בקו זה הא' אשר בכחו דוקא לאכללא<sup data-n=\"2749\">13</sup> שמאלא בימינא<sup data-n=\"2750\">14</sup> כו' שהוא בחי' ההתכללות והיחודי' של כל האורות המסתעפים מכתר דא\"ק עד מל' דאצי' עד שע\"י דוקא יוחלף האור בכלי שאינו שלו כמו אור החסד בכלי הגבור' כו' כמ\"ש במ\"א באריכות בענין וא\"ו דוהנורא<sup data-n=\"2751\">15</sup> כו' והב' מה שנק' בשם קו המדה<sup data-n=\"2752\">16</sup> דוקא למדוד כל או\"כ כו' וכנ\"ל בענין הקו שנק' אמת הבנין כו' שזהו היפוך ההתכללות לכאור'. אך הענין הוא דשניהם אמת ואדרבה הא בהא תליא משום דשרש זה הקו מכח הראשון דעצמיות אא\"ס שלפני הצמצום הוא בא כנ\"ל בענין באורך דוקא נראה אור דקו זה ובכח האור העצמו' דא\"ס<sup data-n=\"2753\">17</sup> ודאי יש לעשות בחי' התכללות ויחודים של כל ההפכים בכל ההשתלשלות מראש דא\"ק כו' עד מל' דאצי' וכמאמ' אנת הוא דמייחד<sup data-n=\"2754\">18</sup> לון ומקשר לון כו' אנת הוא מלגאו ומלבר כו' וכן ענין שם מ\"ה מלגאו דאיהו אורח כל האצי' כו' וכה\"ג הכל הוא מצד הארת אור העצמות דא\"ס שבקו",[["2745","9","<b>הקו. . בחי' מעלה ומטה</b>: במאמרי אדה\"ז על ענינים ע' שדמ מציין: בהתחלת ס' ע\"ח. במאמרי אדה\"א ויקרא ח\"ב ע' תתקכט מציין: לע\"ח בהקדמה. ראה שם (דרוש עגו\"י) ש\"א ענף ב."],["2746","10","<b>יו\"ד. . עמק המלך</b>: ראה שם (שער היו\"ד של שם ס\"ג) ש\"ג. הערה בסה\"מ תרנ\"ט ע' עז."],["2747","11","<b>האור</b>: אג: אור."],["2748","12","<b>באורך נראה אור</b>: המשך הכתוב כי עמך מקור חיים."],["2749","13","<b>בקו. . לאכללא שמאלא בימינא</b>: ראה סה\"מ תקס\"ז ע' כג ואילך."],["2750","14","<b>לאכללא שמאלא בימינא</b>: ראה זהר ר\"פ קרח."],["2751","15","<b>וא\"ו דוהנורא</b>: ראה סה\"מ שם ע' כו ואילך. תו\"ח בראשית מא, ד ובהערה 50."],["2752","16","<b>בשם קו המדה</b>: ראה לעיל עג, ב ואילך. וש\"נ."],["2753","17","<b>העצמו' דא\"ס</b>: ג: דעצמו' אא\"ס."],["2754","18","<b>אנת הוא דמייחד</b>: ראה ת\"ז בהקדמה (יז, א)."]]],[2800530241,"זה שהולך ונמשך עד למט' במל' סוף כ\"ד<sup data-n=\"2755\">1</sup> והיא הנותנת דוקא שיש בכחו למדוד מדה וגבול לכל או\"כ ולכל יחוד משפיע ומקבל כמה יהיה מ\"ד ומ\"ן כו' מצד בחי' הרשימו המגביל לכל אור העצמו' באופנים שונים כמו ששיער בעצמות אא\"ס לפני הצמצום כו' ונמצא מצד עצמות האור שבקו נק' בחי' היולי ליכלל<sup data-n=\"2756\">2</sup> ולחבר את הכל כו' ומצד כח הרשימו המגביל שבו מגביל שיעור ומדה לכל ע\"ד אותו בחי' השיעור הראשון שנכלל ברשימו זו עד\"מ אומן העושה רושם שמגביל האופן של המעש' שיהיה הכל מדוקדק כמו שהוחלט השיעור בעצמו שלא ינטה ימין ושמאל כו' ואעפ\"י שאם לפעמי' יהיה תוס' אור בנאצלי' יתר מכפי מאמר קו המדה כו' היינו מכח האור העצמו' דוקא שלפעמים יאיר כך ולפעמי' יאיר כך ולזה הטעם כל בחי' התחדשו' אור באבי\"ע הכל מעצמו' אא\"ס שלפני הצמצום דוקא דהיינו מפני שבאורו העצמי נראה אור בקו זה לפעמי' בתוס' ולפעמי' בגרעון וכן בשינויי היחודי' שבכל הפרצופי' מא\"ק עד עקב דא\"ק בסוף העשיה<sup data-n=\"2757\">3</sup> כמו השינוי מזמן בהמ\"ק לזמן הגלות וכה\"ג ודרך כלל הרי א\"א י\"ר<sup data-n=\"2758\">4</sup> מלפניך מלפני עצמותך ממש שלמעלה מי\"ס העצמיי' ג\"כ לשנות הרצון הפשוט שכבר נמשך בעצמו' האור דא\"ס לבא בשיעור ששיער בעצמו עד סיום הקו באופן אחר כמו מדין לחסד וכה\"ג וכנ\"ל (בסוף אות הה'<sup data-n=\"2759\">5</sup> ) בענין אני הוי' לא שניתי בין רצון של חסד לדין באור הראשון שלפני הצמצום מטעם הנ\"ל (באות יו\"ד) בענין חפץ חסד שבעצמות ההיולי שנכלל בעצמות כו' שיש בו ג' מדריגות עד שבא בדבר פרט כו' (כמבואר באריכות באות י\"א) וכשאמרו אליו ולא למדותיו<sup data-n=\"2760\">6</sup> מדבר גם במדותיו העצמיים שבאור העצמות מפני שהעצמות דאא\"ס לאו מכל אלין מדות כלל<sup data-n=\"2761\">7</sup> כו' וד\"ל. וזהו אנת הוא דמיחד לון כו' אנת דוק' שזהו אנת הוא חד ולא בחושבן<sup data-n=\"2762\">8</sup> י\"ס כו' וכן מעצמות אא\"ס דוקא בא כח הגבול והמדה אשר בבחי' רשימו שבקו שמחמת זה נק' קו המדה והא בהא תליא דוקא (וכמ\"ש במ\"א בענין כללות חו\"ג שבעצמות<sup data-n=\"2763\">9</sup> אור אין סוף שהוא בחי' כח הגבול להגביל ולהעלים בעצמותו בעילוי אחר עילוי עד אין קץ ושיעור והיינו אא\"ס למעלה עד אין קץ<sup data-n=\"2764\">10</sup> כו' ובחי' התפשטות האור למטה מטה עד אין תכלית שע\"י הקו שנמשך מן הרשימו כו' וב' קוין שקולין המה בבחי' א\"ס ע\"כ גם בירידת האור דא\"ס בקו זה שקולין ב' כחות הללו לצמצם ולהגביל או לחבר ולייחד וכן ענין שינויי האור וההמשכה אם בתוס' או בגרעון כמו מזמן לזמן כמו מחול לשבת ויו\"ט וכן מזמן בהמ\"ק לזמן הגלות הכל בכח א' שקול שנחלק לב' קוין חו\"ג הבא מכח ואור הראשון דעצמות א\"ס כמו שהוא בעצמו בבחי' חו\"ג כו' וד\"ל) והיינו כמבואר למעלה (באות הי\"ד) דקו לגבי שטח הוא היולי כולל ע\"ד אותו האור וכח העצמי שבעצמות של המשפיע רק שבעצמות הוא בהרחבת הערך ביותר ובקו זה בא כח זה עצמו בבחי' הצמצום שפע והמשכה למקבלים כו' וא\"כ גם בבחי' צמצום והתפשטות שבו משם הוא בא דווקא וד\"ל:\n(טז) <b>והנה</b> מעתה יש להבין בפרטי ענין הקו וחוט זה איך שיש בו בחי' מקיפים ופנימים כמ\"ש בע\"ח מתעגל וחוזר ומתעגל<sup data-n=\"2765\">11</sup> כו' (כמ\"ש במ\"א באריכות) ובחי' מקיף ועיגול הראשון הוא הנק' טה\"ת<sup data-n=\"2766\">12</sup> כו' והוא בחי' המקיף הכללי<sup data-n=\"2767\">13</sup> שמקיף לד' עולמות דאבי\"ע בשוה כמ\"ש בע\"ח ותחלה יש להקדים כללות ענין הקו הזה איך שהוא בחי' היולי כללי לכל הסתעפות המשכות פרטיים",[["2755","1","<b>כ\"ד</b>: אג: כל דרגין."],["2756","2","<b>ליכלל</b>: אג: לכלול."],["2757","3","<b>עקב דא\"ק בסוף העשיה</b>: ראה אגה\"ק ס\"כ (קלא, ב). הנסמן במאמרי אדה\"א ויקרא ח\"א ע' טו."],["2758","4","<b>א\"א י\"ר</b>: אג: אנו אומרים יהי רצון."],["2759","5","<b>הה'</b>: א: ט'. יב: כתב הה' ותיקן הט'."],["2760","6","<b>אליו ולא למדותיו</b>: נסמן לעיל קיב, א."],["2761","7","<b>לאו מכל אלין מדות כלל</b>: ראה ת\"ז בהקדמה (יז, ב)."],["2762","8","<b>אנת הוא חד ולא בחושבן</b>: ת\"ז שם (יז, א)."],["2763","9","<b>חו\"ג שבעצמות</b>: ראה גם שע\"ת פז, א ובהנסמן לשם."],["2764","10","<b>אא\"ס למעלה עד אין קץ</b>: ראה ז\"ח יתרו לד, ג. ת\"ז תי\"ט (מ, ב). סתנ\"ז. תו\"ח נח סט, ב ובהערה 11."],["2765","11","<b>הקו. . מתעגל וחוזר ומתעגל</b>: ראה ע\"ח (דרוש עגו\"י) ש\"א ענף ב. וראה גם מאמרי אדה\"א קונטרסים ע' תכג ואילך. וש\"נ. מאמרי אדה\"ז על ענינים ע' שנב."],["2766","12","<b>מקיף ועיגול הראשון. . טה\"ת</b>: ראה גם לעיל קיד, ב ובהערה 21."],["2767","13","<b>המקיף הכללי</b>: ראה סה\"מ תרנ\"א ע' קעה."]]],[2800530242,"הרבה שמסתעפים ממנו עד סוף העשיה כו' כנ\"ל ויובן זה עד\"מ הידוע בענין מחשבה כללית שבמחשב' זו הכללית צופה ומביט עד סוף כל הדורות כו' בסקיר' א'<sup data-n=\"2768\">14</sup> (ובל' הרמב\"ם<sup data-n=\"2769\">15</sup> היינו מה שבידיעת עצמו יודע את כל הנבראי' כמ\"ש במ\"א) וביאור הדברי' ידוע שיש ב' מיני רצון א' רצון הפשוט שבעצמות שנכלל בעצמותו ממש שלא נק' עדיין בשם בחי' מח' ורצון כללי כי מתאחד עדיין בעצמותו ממש כמו גם שהוחלט רצון זה כבר בעצמו איך לעשות דבר חסד פלוני או איך לדבר ולחשוב אותו או להשכיל שכל פרטי או להיות לו רצון ותענוג בדבר כו' הגם שמתחבר רצון המוחלט הזה אל התפשטות הרצון בדבר הפרטי אבל נשאר כלול בהעלם עצמותו וע\"כ אין בו עדיין בחי' כלל ופרט כו' רק כאשר לאח\"ז<sup data-n=\"2770\">16</sup> עולה רצון זה שהוחלט אצלו לבוא לידי מעשה בפו\"מ הרי יוצא מהעלמו לגלוי אז יבוא הרצון בבחי' כלל ופרט דהיינו מח' כללית שכוללת כל ענין המעשה מראש לסוף בסקיר' א' ואח\"כ מתחלק בו רצונות פרטיי' ולכל רצון שכל ומדות כו' ובאין זאח\"ז בהשתלשלות זה עליון מקיף לתחתון כאשר יהי' האופן בתוך האופן<sup data-n=\"2771\">17</sup> כו' והוא הנק' רצון המורכב שיש בו כלל ופרט ויובן זה עד\"מ הידוע אדם שרוצה לבנות בנין גדול כפי הרצון שהוחלט מכבר אצלו להיות בו אופני' מיוחדי' דוקא שאותו הרצון שהוחלט אצלו מכבר הגם שהוא בא במדה ותענוג מיוחד באופן כך וכך וממילא בשכל ומדות בא בשיעור ומדה כו' אך כ\"ז הוא השיעור וההחלט שבעצמותו עדיין ונכלל בעצמו והיה כלא הי' כו' רק כאשר לאחר זמן באה מחשב' זו לבא למעשה ניכר בו התחלקות אותן אופני' שונים ממש שכבר הוחלט אצלו בכל פרטיהם רק שמתחלה בא הרצון הזה בדרך כלל שיהי' לו בנין בציור כך וכך ואח\"כ מתחלק בו רצון פרטי לכל ענין פרטי ויורד ובא בסדר והדרגה מכלל הראשון שכולל הכל בסקירה א' לפרט רצון שהוא נקרא כלל לגבי רצונות המסתעפים ממנו עד שבא אל רצון ושכל פרטי היותר אחרון שבסוף מעשה בכלות הכל כו' וד\"ל. והנמשל מכ\"ז יובן למעלה בהפרש שבין בחי' טה\"ע ובין בחי' טה\"ת שלאחר הצמצום דמה ששיער בעצמו בכח בטה\"ע כו' הוא כמו ההחלט ברצון הפשוט שבעצמות הנ\"ל שעדיין לא בא כלל לבחי' התפשטות חוץ מן העצמות עדיין וגם שיתחבר מרצון המוחלט הזה אל התפשטות הרצון שאח\"כ מ\"מ נשאר כלול בהעלם עצמות דאא\"ס וע\"כ למעל' הוא מבחי' כלל להיות נק' צופה ומביט בסקירה א' כו'. אך הרצון הב' הוא אחר הצמצום הנ\"ל שעולה רצון הפשוט המוחלט שבעצמות לבא לידי בחי' התפשטות הוא בחי' הקו\"ח ההיולי שכולל כל המשכות פרטיות שבו מראשו לסופו כנ\"ל ובחי' מקיף הראשון שבו הוא הנק' טה\"ת שזהו כמשל רצון הכללי לבנין גדול כולל כל מה שבפרטיו מראשו לסופו בבת א' ואח\"כ מתחלק בו בסדר והדרגה מכלל לפרט עד\"מ הנ\"ל והיינו כמו כשעלה ברצונו הפשוט ההיולי לבא לגלוי דוקא היה כולל כל פרטי הרצונות והוא הרצון הכולל כולם ונק' רצון קדום לכל מה שבא אחריו ואח\"כ בא רצון זה דרך פרט כמו הרצון להאציל ובו כלול ע\"ס בכל פרטיהם ועדיין הכל בהעלם עד שבא לידי גלוי שהוא כשנאצל האור בבחי' האצי' כו' ואח\"כ הרצון לברוא יש מאין כו' ובו שכל ומדות כו' עד הרצון היותר אחרון שהוא כל אשר חפץ עשה כו' סוף הכל וכל פרטים הללו נכללו ברצון הקדום שבא בבחי' השפעה עכ\"פ אחר הצמצום והוא בחי' ראשית הקו כו' והיינו עיגול הראשון שאחר המשכת",[["2768","14","<b>מחשבה. . צופה ומביט. . בסקיר' א'</b>: ראה ר\"ה יח, א. ברכת זכרונות. הנסמן במאמרי אדה\"א הנחות תקע\"ז ע' צ. תו\"ח ויגש רל, ד. לעיל נו, ב."],["2769","15","<b>ובל' הרמב\"ם</b>: ראה הל' יסוה\"ת פ\"ב, ה\"ט. ה\"י. ראה גם תניא פמ\"ב. פמ\"ח. מאמרי אדה\"א קונטרסים ע' רא. נ\"ך ע' רנא."],["2770","16","<b>לאח\"ז</b>: אג: לאחר זמן."],["2771","17","<b>כאשר יהי' האופן בתוך האופן</b>: יחזקאל א, טז. י, י."]]],[2800530243,"ראשית הקו ההיולי הנ\"ל שנק' מקיף כללי לכללות כל הד' עולמות דאבי\"ע שמקיף אותם בשוה שנק' מח' כללית שצופה ומביט בסקירה א' מראש לסוף הכל כו' וזהו ביאור ענין כללי לכללות ענין הקו הזה ופרטי אופניו במה שמתעגל וחוזר ומתעגל כו' יובן לפי אופן משל הנ\"ל וכמשי\"ת בסמוך בעז\"ה וד\"ל:\n(יז) <b>והנה</b> מעתה יש להבין בפרטי ענין הקו כמו שהוא בבחי' עגולים כו'. והנה תחלה יש להקדים בבחי' ראשית הקו הזה שבא בבחי' או\"פ ואח\"כ מתעגל ונמשך בבחי' או\"פ וחוזר ומתעגל כו' ומבואר בע\"ח שבבחי' ע\"ס דעגולים העליון מכולם משובח מכלם והפנימי מכולם גרוע כו' ובבחי' ע\"ס דיושר להיפך<sup data-n=\"2772\">1</sup> העליון גרוע והפנימי משובח כו'. וביאור הדברים הנה ידוע שבחי' רצון קדום זה הגם שלגבי בחי' רצון הפשוט המוחלט בעצמות נק' התפשטות רצון אבל עדיין הוא בהעלם ולא בגלוי כלל כי אינו רק השפעת והמשכת רצון הפשוט של חפץ חסד שהוחלט בעצמות מכבר כך יהי' בפו\"מ ומיד שעול' במח' זאת שיהי' הכל הוא הנק' מח' ורצון קדום שכולל כל מה שבתוכו רצונות פרטים כנ\"ל במשל הבנין א\"כ עדיין רצון קדום זה הכל בעצמו בלתי התגלות לחוץ אבל ממנו נעשה הכל אח\"כ וזהו כי הוא אמר במח' הקדומה ויהי<sup data-n=\"2773\">2</sup> כו' ונק' חיי כל העולמים מראש דא\"ק עד עקב א\"ק בסוף עשי' והיינו כל היצור לא נכחד כו' שאין פרט היותר אחרון שלא קדם להיות ברצון ובמח' זו ואדרבה סוף מעשה כמו בסוף אלף הז' עלה במח' קדומה זו תחלה<sup data-n=\"2774\">4</sup> כמ\"ש במ\"א באריכות<sup data-n=\"2775\">3</sup> (ובל' הזהר נק' עתיקא דעתיקין<sup data-n=\"2776\">5</sup> או עתיקא סתימאה<sup data-n=\"2777\">6</sup> והוא בחי' רעוא דכ\"ר עילאין דאתגליין במצחא דע\"ק<sup data-n=\"2778\">7</sup> כו' כי ברצון מלובש התענוג והיו לאחדים ממש וברצון הפשוט ההיולי שבחפץ חסד ההיולי (הנ\"ל באות יוד ואות יא) היה כלול בו התענוג הפשוט שבעצמו' שנק' שעשועי המלך בעצמותו<sup data-n=\"2779\">8</sup> כו' וגם בג' מדריגות עד שבא בדבר פרט אנא אמלוך שזהו בחי' מל' דא\"ס שלפני הצמצום כמ\"ש שם הכל בחי' שעשועי המלך בעצמו בטה\"ע אך עתיקא דעתיקין מקור כל התענוגי' או רעוא דכ\"ר כו' היינו בבחי' הקו שאחר הצמצום שכולל כמה רצונות ותענוגים שעתידים לבוא בגלוי ועתיקא סתימא' הוא בבחי' כתר דא\"ק שהוא בהעלם הרצון והתענוג לעצמו עדיין רק שחושב להיות הדבר כך בפועל הגילוי כמו להיות גילוי הרצון והתענוג להאציל ע\"ס כו'<sup data-n=\"2780\">9</sup> (ולכך נק' עתיקא סתימא' בחי' העלם לגלוי עכ\"פ משא\"כ ראשית הקו נק' סדכ\"ס דגם מחשבה דא\"ק לא תפיס בי' כו') ולהיות הרצון והתענוג לברוא כו'<sup data-n=\"2781\">10</sup> וע\"ק הוא התענוג שבחכמה והוא בחי' ע\"י וא\"א דאצי' שהרצון והתענוג בא בגלוי כמשי\"ת הכל דרך פרט) והנה בחי' ע\"ס דעגולים זת\"ז<sup data-n=\"2782\">11</sup> הוא כידוע שכל עילה מקפת לעלול ועלול לא ישיג לעילה שלו כ\"א בריחוק מקום ממנו כאשר יהי' האופן בתוך כו' ויובן זה מהרצון הבא בגלוי גמור שגם שכלול הרצון הזה מי'<sup data-n=\"2783\">12</sup> חכמה ומדות אבל תחלתו בא רק בהסכם א' בלי התחלקות ניכר בו והוא הנק' עיגול רצון כללי מקיף לכל מה שבא בתוכו מכחו דוקא אך בריחוק מקום כמו הטעם ושכל לרצון זה שנק' עלול שלו א\"א שיהי' קרוב בערך אל עילתו שהוא הרצון כי הרי אין טעם לרצון כלל<sup data-n=\"2784\">13</sup> כידוע ולעולם לא ישיגנו אבל מ\"מ מכח הרצון נעשה עיגול החכמה ג\"כ בלי התחלקות ניכר לי' כו' כמו משל השוחד שימצא טעם לרצון וגם שבטעם זה כלול ג\"כ מיו\"ד רצון ושכל ומדות אבל נעשה בבחי' כללי כו' ועד\"ז לא ישיגנו העיגול",[["2772","1","<b>ע\"ס דעגולים. . ע\"ס דיושר להיפך</b>: ראה ע\"ח (דרוש עגו\"י) ש\"א ענף ב. ג."],["2773","2","<b>כי הוא אמר. . ויהי</b>: תהלים לג, ט."],["2774","4","<b>סוף מעשה. . עלה במח'. . תחלה</b>: ע\"פ נוסח לכה דודי."],["2775","3","<b>כל היצור לא נכחד. . באריכות</b>: ברכת זכרונות. ראה גם מאמרי אדה\"ז על ענינים ע' שעד ואילך. ד\"ה דור לדור מכ\"ק אדה\"א (קה\"ת, תשנ\"ב) ע' ז."],["2776","5","<b>עתיקא דעתיקין</b>: לשון הזהר בכ\"מ ? תרומה קסה, ב. נשא (אד\"ר) קכח, א-ב. ועוד."],["2777","6","<b>עתיקא סתימאה</b>: זהר נשא (אד\"ר) קכט, א. קלב, סע\"א. ועוד."],["2778","7","<b>רעוא דכ\"ר. . במצחא דע\"ק</b>: ראה זהר נשא (אד\"ר) קכט, א. קלו, ב."],["2779","8","<b>שעשועי המלך בעצמותו</b>: ראה עמה\"מ שער זה. מאמרי אדה\"א שמות ח\"ב ע' תנג. וש\"נ. קונטרסים ע' שמה. וש\"נ."],["2780","9","<b>כו'</b>: אג: ניתוסף כאן (מבסמוך שו\"ה בי'): ?ולהיות הרצון והתענוג לברוא כו'\"."],["2781","10","<b>ולהיות. . כו'</b>: אג: ליתא. ראה הערה שלפנ\"ז."],["2782","11","<b>זת\"ז</b>: אג: זה (ב)תוך זה."],["2783","12","<b>שכלול הרצון הזה מי'</b>: ראה להלן קכג, א. ביאוה\"ז שמות לו, ד ואילך."],["2784","13","<b>אין טעם לרצון כלל</b>: ראה של\"ה בית ה' ד, ב בהגה בשם ר' יוסף אלקשטיליא. יונת אלם (לרמ\"ע מפאנו) פ\"ב. הנסמן בתו\"ח נח סג, א הערה 7. לעיל קב, ב."]]],[2800530244,"דבינה שנעש' מכחו ועד\"ז המדות זת\"ז עד סוף מעשה שהוא עיגול האחרון והכל ברצונו לעצמו כלול הכל עד סוף מעשה שהוא הפנימי מכולם כו' וכך הוא ברצון הנעלם הנק' רצון הקדום הנ\"ל מקור כל הרצונות כלול מי\"ס עד\"ז עיגול בתוך עיגול עד עיגול דסוף מעשה שהוא הרצון לסוף מעשה להיות כל אשר חפץ עושה בפו\"מ כו' והעיגול העליון הכולל הכל הוא רצון הקדום הנ\"ל וכשבא הרצון לעצמו הזה להיות בפו\"מ הרי הוא להיפוך שהרצון מתעלם ומתלבש בשכל והשכל מקיפו והשכל מתעלם ומתלבש במדות זת\"ז עד סוף מעשה הוא העליון מהכל דהיינו כח המעשה בפו\"מ הרי בו מלובש המח' ובמח' מלובש המדות ובמדות מלובש החו\"ב ובחכ' מלובש הרצון והתענוג ונמצא פנימי מכולם הוא הרצון והתענוג וחיצון שבכולם הוא המעשה גרוע כו' והוא בבחי' היושר כשבא בבחי' התלבשות העליון בתחתון כו' אבל בבחי' רצון הקדום הנ\"ל שעדיין הוא בעצמו ע\"כ נמשך בבחי' עגולים שהעליון מהכל הוא העלם הרצון הכולל הזה ועיגול הראשון שבו הוא הרצון ותענוג לכללות כל השתלשלות שבתוכו ועיגול זה מקיף כללי לאבי\"ע כנ\"ל וראשית הקו הוא בחי' המשכה היולית כמו קו קצר המתצמצם מעילה לעלול כמו מן הרצון לחכמה וכה\"ג כך מבחי' הרשימו הנ\"ל נמשך קו בצמצום גדול מאד דהגם שהרשימו הוא בא בהגבלה כנ\"ל אבל הוא מבחי' עולם הא\"ס עכ\"פ רק שהוא בחי' האחרונה שנעשה בקיצור כו' משא\"כ להיות רצון קדום שהוא בא לכלל השפעה חוץ מעולם הא\"ס רק שהוא היולי כולל הכל כו' ע\"כ נמשך דרך קו קצר כו' וד\"ל (והוא מ\"ש בע\"ח דכל עיקר הארת הקו אינו רק להיות בחי' מעלה ומטה כמו ביו\"ד עגולים עד סוף מעשה כו' משא\"כ בעולם הא\"ס אין שם אפי' בחי' מעלה ומטה רק אח\"פ בתכלית כנ\"ל וגם ששיער בעצמו מה שעתיד כו' הכל הוא בעצמותו ממש שהוא בבחי' א\"ס ממש ולזה א' בע\"ח דגם בבחי' מל' דא\"ס אין רשאי' לדבר<sup data-n=\"2785\">14</sup> כו' רק בבחי' הקו ובחי' א\"ק כו' שהוא בחי' מקור הראשון לכל ההשתלשלות יוכל לבא בהשגה בריבוי ההשתלשלות עד ע\"ס שבאצי' בבי\"ע כו' מאחר שנק' בשם עילות כל העילות<sup data-n=\"2786\">15</sup> כו' או קדמון כו'<sup data-n=\"2787\">16</sup> אבל בעצמות אא\"ס לית מח' ת\"ב<sup data-n=\"2788\">17</sup> אפי' מח' הקדומה הנ\"ל להיות כי העולם הא\"ס נבדל בערך ונק' קדוש לגמרי מצד הצמצום הנ\"ל ובחי' רצון קדום הנ\"ל נק' שמו הגדול שמו גי' רצון<sup data-n=\"2789\">18</sup> והוא ענין יהא שמיה רבא מברך<sup data-n=\"2790\">19</sup> כו' (וכידוע דבחי' א\"ק נק' אדם דבריאה<sup data-n=\"2791\">20</sup> כו' וכמשי\"ת משא\"כ בעצמות אא\"ס נאמר כי לא אדם הוא<sup data-n=\"2792\">21</sup> כו' וכידוע בכונות דנשמת כל חי<sup data-n=\"2793\">22</sup> שהוא בחי' א\"ק כו' וד\"ל):\n(יח) <b>והנה</b> בחי' רצון הקדום לעצמו כל מה שיהי' בהשתלשלות שכלול מי' עד בחי' סוף מעשה שעלה ברצון קדום זה שהוא בחי' אחרונה שבו הרי מבחי' מל' שבעליון נעשה כתר לתחתון<sup data-n=\"2794\">23</sup> כו' והוא בחי' כתר דא\"ק להיות ידוע דבחי' א\"ק נק' אדם דבריאה דרך כללות והוא בחי' המח' וע\"י וא\"א דאצי' נק' אדם דיצירה וז\"א ונוק' אדם דעשי' כו' וכמו שהבריא' היא התהוות יש מאין ממש כידוע כך גם בחינת כתר דא\"ק זה נקרא בריאה יש מאין האמיתי דאור א\"ס עצמו שבקו הנ\"ל הנק' רצון קדום לעצמו כו'. וביאור הדברים ידוע להיות מבואר למעלה דרצון קדום הנ\"ל הוא הנק' מקור כל הרצונות שהוא בחי' רצון ההיולי להיות ממנו נמצא מקור לכל רצון לרצון ויובן זה ע\"ד דוגמא מבחי' יחידה שבנפש האדם כשעצמיות חפץ חסד שבה שבהתכללות בבחי' היולי כולל",[["2785","14","<b>מל' דא\"ס אין רשאי' לדבר</b>: ראה ע\"ח (דרוש עגו\"י) ש\"א ענף ה. וסוף ענף ב. הנסמן במ\"מ לשע\"ת קמה, א."],["2786","15","<b>עילות כל העילות</b>: ראה גם לעיל קיד, א ובהנסמן לשם."],["2787","16","<b>קדמון כו'</b>: נסמן לעיל נא, א."],["2788","17","<b>לית מח' ת\"ב</b>: ת\"ז בהקדמה (יז, א)."],["2789","18","<b>שמו גי' רצון</b>: ראה סה\"מ תקס\"ד ע' רלו בשם הפרדס. פע\"ח (שער הק\"ש) ש\"ח ספכ\"ח. מאמרי אדה\"א דברים ח\"ב ע' שסח. וש\"נ."],["2790","19","<b>יהא שמיה רבא מברך</b>: נוסח הקדיש."],["2791","20","<b>א\"ק נק' אדם דבריאה</b>: ראה מאמרי אדה\"ז על ענינים בתחלתן ובהנסמן לשם."],["2792","21","<b>כי לא אדם הוא</b>: שמואל-א טו, כט."],["2793","22","<b>דנשמת כל חי</b>: נוסח התפלה דשויו\"ט. ראה גם מאמרי אדה\"א בראשית ריש ע' תנה. דברים ח\"ב ע' תסא."],["2794","23","<b>מל' שבעליון נעשה כתר לתחתון</b>: נסמן לעיל קטז, ב."]]]]});
